window.UNIT_DATA = {"modules": [{"id": 1, "title": "Understanding a limit", "group": "1.1 · Limits & continuity", "page": 34, "description": "Separate what a function approaches from its value at a point.", "recognize": "Look for “approaches,” not “equals.” A limit describes nearby outputs.", "formula": "\\lim_{x\\to c}f(x)=L", "procedure": ["Identify the input being approached.", "Compare the outputs on both sides.", "Use the common approached value, regardless of the value at the point."], "mistake": "A filled point gives f(c), not necessarily the limit."}, {"id": 2, "title": "Reading limits from graphs", "group": "1.1 · Limits & continuity", "page": 34, "description": "Read open points, filled points, and nearby behavior.", "recognize": "Follow the curve toward the specified input from each side.", "formula": "\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L", "procedure": ["Trace the graph from the left.", "Trace it from the right.", "Compare the approached heights; inspect filled points separately."], "mistake": "An open circle can still mark the value of a limit."}, {"id": 3, "title": "One-sided limits", "group": "1.1 · Limits & continuity", "page": 35, "description": "Use direction to distinguish left and right behavior.", "recognize": "A minus superscript means inputs below c; a plus means inputs above c.", "formula": "\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)", "procedure": ["Identify the side indicated by the superscript.", "Use only the rule valid on that side.", "For a two-sided limit, require the sides to agree."], "mistake": "The minus sign specifies direction, not a negative answer."}, {"id": 4, "title": "Direct substitution", "group": "1.1 · Limits & continuity", "page": 35, "description": "Evaluate limits of continuous polynomial and radical functions.", "recognize": "Polynomials are continuous everywhere; radicals are continuous on their domains.", "formula": "\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c", "procedure": ["Check that the expression is defined nearby.", "Substitute the approached input.", "Apply order of operations."], "mistake": "Substitute into every occurrence of the variable."}, {"id": 5, "title": "Rational & trigonometric limits", "group": "1.1 · Limits & continuity", "page": 37, "description": "Substitute into rational and trigonometric expressions when allowed.", "recognize": "A nonzero denominator permits direct substitution. Trig inputs use radians.", "formula": "\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0", "procedure": ["Evaluate the denominator first.", "Check continuity of each part.", "Substitute and simplify using exact trig values."], "mistake": "Never use the quotient rule for limits if the denominator limit is zero."}, {"id": 6, "title": "Piecewise limits", "group": "1.1 · Limits & continuity", "page": 35, "description": "Choose the right branch and compare both sides of a boundary.", "recognize": "A formula changes at a boundary; the equality sign only controls the point value.", "formula": "\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}", "procedure": ["Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately.", "Compare the two results."], "mistake": "Using the branch containing the equality sign for both sides can give a false limit."}, {"id": 7, "title": "The continuity test", "group": "1.1 · Limits & continuity", "page": 34, "description": "Check the three requirements for continuity at a point.", "recognize": "Ask whether the value exists, the limit exists, and they match.", "formula": "\\lim_{x\\to c}f(x)=f(c)", "procedure": ["Find f(c).", "Determine the two-sided limit.", "Compare the limit with f(c)."], "mistake": "A defined function value alone does not establish continuity."}, {"id": 8, "title": "Classifying discontinuities", "group": "1.2 · Algebraic limits & IVT", "page": 38, "description": "Tell holes, jumps, and infinite discontinuities apart.", "recognize": "A finite shared limit gives a removable hole; unequal sides give a jump.", "formula": "\\text{Removable: a finite limit exists but continuity fails}", "procedure": ["Compute the one-sided limits.", "If both equal a finite value, check the point value.", "Classify unequal finite sides as a jump and unbounded behavior as infinite."], "mistake": "A vertical asymptote is not removable by changing one point."}, {"id": 9, "title": "Factoring indeterminate limits", "group": "1.2 · Algebraic limits & IVT", "page": 38, "description": "Resolve zero over zero by factoring and cancellation.", "recognize": "Direct substitution gives 0/0, suggesting a common factor.", "formula": "x^2-a^2=(x-a)(x+a)", "procedure": ["Try substitution and identify 0/0.", "Factor numerator and denominator.", "Cancel common factors for x ≠ c, then substitute."], "mistake": "Cancel factors, not terms. The original point remains excluded."}, {"id": 10, "title": "Rationalizing limits", "group": "1.2 · Algebraic limits & IVT", "page": 38, "description": "Use a conjugate to simplify radical differences.", "recognize": "A difference of radicals over a vanishing denominator often gives 0/0.", "formula": "(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v", "procedure": ["Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate.", "Cancel the vanishing factor and evaluate."], "mistake": "Multiply both numerator and denominator by the conjugate."}, {"id": 11, "title": "Limits from numerical tables", "group": "1.2 · Algebraic limits & IVT", "page": 38, "description": "Use nearby values as evidence for a limit.", "recognize": "Read the closest inputs on each side, without treating a finite table as proof.", "formula": "x\\to c^-\\quad\\text{and}\\quad x\\to c^+", "procedure": ["Sort inputs by the side they approach from.", "Compare the trend of nearby outputs.", "State an estimate; use algebra for certainty."], "mistake": "A finite table suggests behavior but cannot prove every nearby value follows it."}, {"id": 12, "title": "Making a function continuous", "group": "1.2 · Algebraic limits & IVT", "page": 38, "description": "Find missing values and parameters that join the pieces.", "recognize": "The unknown parameter must make both limits and the point value agree.", "formula": "\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)", "procedure": ["Evaluate the boundary expression on both sides.", "Set their values equal.", "Solve for the parameter and verify the point value."], "mistake": "Matching one side is insufficient if the other side differs."}, {"id": 13, "title": "Intermediate Value Theorem", "group": "1.2 · Algebraic limits & IVT", "page": 39, "description": "Check when a continuous function must reach a target output.", "recognize": "You need continuity on the whole closed interval and a target between endpoint values.", "formula": "f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k", "procedure": ["Verify continuity on [a,b].", "Compute both endpoint values and compare with the target.", "If the target lies strictly between them, IVT guarantees an interior solution."], "mistake": "IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."}, {"id": 14, "title": "Infinite limits", "group": "1.3 · Infinite limits & end behavior", "page": 41, "description": "Analyze sign near a zero denominator.", "recognize": "A nonzero numerator over a denominator approaching zero requires a sign check.", "formula": "\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty", "procedure": ["Check whether cancellation is possible.", "Determine numerator and denominator signs on each side.", "State signed infinity or DNE if the sides disagree."], "mistake": "Infinity describes unbounded behavior, not a real function value."}, {"id": 15, "title": "Asymptotes & multiplicity", "group": "1.3 · Infinite limits & end behavior", "page": 41, "description": "Use remaining factor powers to predict vertical asymptote behavior.", "recognize": "Reduce first; odd and even denominator powers behave differently across a root.", "formula": "f(x)=\\frac{A}{(x-c)^n}", "procedure": ["Reduce common factors.", "Locate remaining real denominator zeros.", "An even power preserves sign across the point; an odd power reverses it."], "mistake": "Classify multiplicity after cancellation, not before."}, {"id": 16, "title": "Rational limits at infinity", "group": "1.3 · Infinite limits & end behavior", "page": 42, "description": "Compare degrees and leading coefficients to read end behavior.", "recognize": "The input approaches infinity, so leading terms dominate.", "formula": "\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}", "procedure": ["Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b.", "Higher numerator degree requires a sign and parity check."], "mistake": "The largest individual factor is not the total degree of a product."}, {"id": 17, "title": "Radical limits at infinity", "group": "1.3 · Infinite limits & end behavior", "page": 42, "description": "Keep track of absolute values when extracting powers from radicals.", "recognize": "At negative infinity, the sign hidden in a square root matters.", "formula": "\\sqrt{x^2}=|x|", "procedure": ["Factor x² from under the radical.", "Replace √(x²) with |x|.", "Use |x|/x = 1 on the right and −1 on the left."], "mistake": "Writing √(x²) = x for negative x reverses the answer."}, {"id": 18, "title": "Exponential end behavior", "group": "1.3 · Infinite limits & end behavior", "page": 42, "description": "Combine exponential behavior with polynomial and rational terms.", "recognize": "Watch the sign of the exponent and whether x goes left or right.", "formula": "e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)", "procedure": ["Determine the exponent’s direction.", "Use exponential growth or decay.", "Combine with the remaining finite limits or compare dominant growth."], "mistake": "eˣ approaches zero at negative infinity, not at positive infinity."}, {"id": 19, "title": "Domain, holes & restrictions", "group": "1.4 · Curve sketching", "page": 45, "description": "Preserve original restrictions while finding removable holes.", "recognize": "Original denominator zeros stay excluded after cancellation.", "formula": "\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))", "procedure": ["Record original denominator zeros.", "Factor and reduce.", "Canceled restrictions become holes if the reduced value is finite."], "mistake": "Canceling a factor does not put its excluded input back in the domain."}, {"id": 20, "title": "Intercepts & curve sketching", "group": "1.4 · Curve sketching", "page": 45, "description": "Assemble intercepts, asymptotes, and end behavior into a graph.", "recognize": "A useful sketch begins with structural features, not random plotting.", "formula": "x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)", "procedure": ["Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts.", "Check end behavior and multiplicity before drawing."], "mistake": "A canceled numerator zero is not an x-intercept if the input is excluded."}, {"id": 21, "title": "Average rate of change", "group": "1.5 · Rates, squeeze & composition", "page": 48, "description": "Find a secant slope from formulas, points, and motion tables.", "recognize": "Two inputs or times signal an average rate over an interval.", "formula": "\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}", "procedure": ["Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs.", "Divide and include output-units per input-unit."], "mistake": "Average speed is distance change divided by time change, not the average of the two distances."}, {"id": 22, "title": "Estimating instantaneous rates", "group": "1.5 · Rates, squeeze & composition", "page": 48, "description": "Use nearby secant slopes to estimate a rate at one instant.", "recognize": "A single instant calls for a local estimate, not a long-interval average.", "formula": "f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}", "procedure": ["Choose nearby points that bracket the instant.", "Compute their secant slope.", "Describe the result as an estimate unless the graph is a straight segment."], "mistake": "This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."}, {"id": 23, "title": "Squeeze Theorem", "group": "1.5 · Rates, squeeze & composition", "page": 48, "description": "Find a limit by trapping a function between matching bounds.", "recognize": "A bounded oscillation multiplied by a vanishing factor is a common clue.", "formula": "f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L", "procedure": ["Verify the bounding inequality near the point.", "Find both bounding limits.", "If they agree, the middle function has the same limit."], "mistake": "Different bounding limits do not determine the middle limit."}, {"id": 24, "title": "Combining limits", "group": "1.5 · Rates, squeeze & composition", "page": 49, "description": "Use limit laws with sums, products, and quotients.", "recognize": "Known limits can be combined when the relevant operations are defined.", "formula": "\\lim(af+bg)=a\\lim f+b\\lim g", "procedure": ["Record each component limit.", "Apply sum, product, or quotient rules.", "For a quotient, check that the denominator limit is nonzero."], "mistake": "Do not insert a function value when the problem supplies a different limit."}, {"id": 25, "title": "Limits of compositions", "group": "1.5 · Rates, squeeze & composition", "page": 49, "description": "Follow inner outputs into the correct side of an outer function.", "recognize": "If the outer function is discontinuous, track which side the inner outputs approach.", "formula": "\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L", "procedure": ["Find the limiting inner output.", "Determine its approach side if the outer function jumps.", "Use the matching outer one-sided limit, not automatically f(L)."], "mistake": "At an outer discontinuity, knowing only the inner limit can be insufficient."}], "problems": [{"id": "U1-01-01", "module": 1, "family": 0, "topic": "Understanding a limit", "subtopic": "Recognize", "difficulty": "Easy", "question": "Near x = 1, both sides of f(x) approach 4, but f(1) = 8. Find the limit.", "math": "\\lim_{x\\to 1}f(x)", "answer": "4", "type": "number", "solutionSteps": ["Nearby values from both sides approach 4.", "The value f(1) = 8 affects the point, not the nearby trend.", "The limit is 4."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-02-01", "module": 2, "family": 0, "topic": "Reading limits from graphs", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the graph to find the two-sided limit.", "math": "\\lim_{x\\to -2}f(x)", "answer": "0", "type": "number", "solutionSteps": ["Both branches approach the open point at (-2, 0).", "The filled point is the function value, not the limit.", "The limit is 0."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": {"type": "hole", "c": -2, "L": 0, "value": 3, "m": 1}, "table": null, "numericAnswer": 0.0}, {"id": "U1-03-01", "module": 3, "family": 0, "topic": "One-sided limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 3^-}\\frac{1|x-3|}{x-3}", "answer": "-1", "type": "number", "solutionSteps": ["On this side, x − 3 is negative.", "Replace the absolute value with the negative of its argument.", "Cancel the nonzero factor nearby to get -1."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -1.0}, {"id": "U1-04-01", "module": 4, "family": 0, "topic": "Direct substitution", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 3}x + 3", "answer": "6", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 3.", "Simplify to $6$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-05-01", "module": 5, "family": 0, "topic": "Rational & trigonometric limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 1}\\frac{x + 1}{x^{2} + 3}", "answer": "\\frac{1}{2}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $1$ for x.", "Use exact values and simplify to $\\frac{1}{2}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.5}, {"id": "U1-06-01", "module": 6, "family": 0, "topic": "Piecewise limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the two-sided limit at x = 1.", "math": "f(x)=\\begin{cases}x^2+0&x<1\\\\3&x=1\\\\x+0&x>1\\end{cases}", "answer": "1", "type": "number", "solutionSteps": ["The left limit is 1.", "The right limit is 1.", "The two-sided limit is 1; the isolated value 3 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-07-01", "module": 7, "family": 0, "topic": "The continuity test", "subtopic": "Recognize", "difficulty": "Easy", "question": "At x = 3, the left limit is 1, the right limit is 1, and f(3) is 1. Is f continuous there?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value matches the common limit."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-01", "module": 8, "family": 0, "topic": "Classifying discontinuities", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the discontinuity at x = 1 for this function.", "math": "\\frac{x^{2} - 1}{x - 1}", "answer": "Removable", "type": "choice", "solutionSteps": ["Factor the numerator and cancel x − 1.", "The nearby behavior is the finite value 2.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-01", "module": 9, "family": 0, "topic": "Factoring indeterminate limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 1}\\frac{x^{2} - 1}{x - 1}", "answer": "2", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 1 for nearby x.", "The reduced expression is $x + 1$.", "Substitute x = 1 to obtain $2$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-10-01", "module": 10, "family": 0, "topic": "Rationalizing limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 1}\\frac{\\sqrt{x} - 1}{x - 1}", "answer": "\\frac{1}{2}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{2}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.5}, {"id": "U1-11-01", "module": 11, "family": 0, "topic": "Limits from numerical tables", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the limit as x approaches 1 from the table.", "math": "", "answer": "5", "type": "number", "solutionSteps": ["As inputs approach 1 from the left, outputs approach 5.", "The right-side outputs also approach 5.", "The table suggests a limit of 5."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["0.900", "4.800"], ["0.990", "4.980"], ["0.999", "4.998"], ["1.001", "5.002"], ["1.010", "5.020"], ["1.100", "5.200"]]}, "numericAnswer": 5.0}, {"id": "U1-12-01", "module": 12, "family": 0, "topic": "Making a function continuous", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}\\frac{x^2-1}{x-1}&x\\ne 1\\\\K&x=1\\end{cases}", "answer": "2", "type": "number", "solutionSteps": ["Factor and cancel x − 1.", "The nearby expression is x + 1, with limit 2.", "Set K = 2."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-13-01", "module": 13, "family": 0, "topic": "Intermediate Value Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "For f(x) = x² on [0, 3], does IVT guarantee an interior point with f(c) = 1?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["A polynomial is continuous on the whole interval.", "The endpoint values are 0 and 9.", "The target 1 is strictly between them."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-01", "module": 14, "family": 0, "topic": "Infinite limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 3^-}\\frac{1}{(x-3)^{1}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is 1, which is nonzero.", "The denominator approaches zero negatively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": {"type": "rational", "c": 3, "L": 0, "a": 1, "power": 1, "offset": 0}, "table": null}, {"id": "U1-15-01", "module": 15, "family": 0, "topic": "Asymptotes & multiplicity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the vertical asymptote at x = 1.", "math": "f(x)=\\frac{3}{(x-1)^{2}}", "answer": "Even", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 2.", "The asymptote has even multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-01", "module": 16, "family": 0, "topic": "Rational limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{x^{2} + 3}{3 x^{2} + 1}", "answer": "\\frac{1}{3}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{1}{3}$.", "At the specified end, the limit is $\\frac{1}{3}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.3333333333333333}, {"id": "U1-17-01", "module": 17, "family": 0, "topic": "Radical limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{x^{2} + 3}}{x}", "answer": "1", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $1$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-18-01", "module": 18, "family": 0, "topic": "Exponential end behavior", "subtopic": "Recognize", "difficulty": "Easy", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}e^{x} + 3", "answer": "3", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 3."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-19-01", "module": 19, "family": 0, "topic": "Domain, holes & restrictions", "subtopic": "Recognize", "difficulty": "Easy", "question": "Select every input excluded from the domain.", "math": "f(x)=\\frac{(x-1)(x+3)}{(x-1)(x+1)}", "answer": ["1", "-1"], "type": "multi", "solutionSteps": ["The original denominator vanishes at ±1.", "Both values are excluded even if a factor later cancels."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Easy"], "options": ["1", "-1", "0", "3"], "graph": null, "table": null}, {"id": "U1-20-01", "module": 20, "family": 0, "topic": "Intercepts & curve sketching", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the x-coordinate of the x-intercept.", "math": "f(x)=\\frac{x - 1}{x + 3}", "answer": "1", "type": "number", "solutionSteps": ["Set the numerator x − 1 equal to zero.", "At x = 1, the denominator is 4, nonzero.", "The x-intercept is (1, 0)."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-21-01", "module": 21, "family": 0, "topic": "Average rate of change", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the average rate of change on [0, 2].", "math": "f(x)=x^{2} + 1", "answer": "2", "type": "number", "solutionSteps": ["The endpoint outputs are 1 and 5.", "The input change is 2.", "Divide the output change by 2 to obtain $2$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-22-01", "module": 22, "family": 0, "topic": "Estimating instantaneous rates", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the instantaneous rate at x = 3 using the secant on [2.9, 3.1].", "math": "f(x)=x^{2} + 3 x", "answer": "9", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{29}{10}$ and $\\frac{31}{10}$.", "The output change is $\\frac{9}{5}$ and the input change is $\\frac{1}{5}$.", "The secant estimate is $9$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-23-01", "module": 23, "family": 0, "topic": "Squeeze Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}1x^{2}\\sin(1/x)+3", "answer": "3", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 3, both bounds approach 3.", "The Squeeze Theorem gives 3."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-24-01", "module": 24, "family": 0, "topic": "Combining limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x approaches 5, f(x) approaches 1 and g(x) approaches 3. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 5}2f(x)+3g(x)", "answer": "11", "type": "number", "solutionSteps": ["Use the component limits 1 and 3.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $11$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 11.0}, {"id": "U1-25-01", "module": 25, "family": 0, "topic": "Limits of compositions", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x → 3, g(x) → 1. If f(t) = t² + 3, find the limit of f(g(x)).", "math": "", "answer": "4", "type": "number", "solutionSteps": ["The inner output approaches 1.", "The outer polynomial is continuous.", "Evaluate f(1) = 4."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-01-02", "module": 1, "family": 0, "topic": "Understanding a limit", "subtopic": "Recognize", "difficulty": "Easy", "question": "Near x = 2, both sides of f(x) approach 5, but f(2) = 9. Find the limit.", "math": "\\lim_{x\\to 2}f(x)", "answer": "5", "type": "number", "solutionSteps": ["Nearby values from both sides approach 5.", "The value f(2) = 9 affects the point, not the nearby trend.", "The limit is 5."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-02-02", "module": 2, "family": 0, "topic": "Reading limits from graphs", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the graph to find the two-sided limit.", "math": "\\lim_{x\\to -1}f(x)", "answer": "1", "type": "number", "solutionSteps": ["Both branches approach the open point at (-1, 1).", "The filled point is the function value, not the limit.", "The limit is 1."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": {"type": "hole", "c": -1, "L": 1, "value": 4, "m": 1}, "table": null, "numericAnswer": 1.0}, {"id": "U1-03-02", "module": 3, "family": 0, "topic": "One-sided limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 4^-}\\frac{2|x-4|}{x-4}", "answer": "-2", "type": "number", "solutionSteps": ["On this side, x − 4 is negative.", "Replace the absolute value with the negative of its argument.", "Cancel the nonzero factor nearby to get -2."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -2.0}, {"id": "U1-04-02", "module": 4, "family": 0, "topic": "Direct substitution", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 4}2 x + 4", "answer": "12", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 4.", "Simplify to $12$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-05-02", "module": 5, "family": 0, "topic": "Rational & trigonometric limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 2}\\frac{x + 2}{x^{2} + 4}", "answer": "\\frac{1}{2}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $2$ for x.", "Use exact values and simplify to $\\frac{1}{2}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.5}, {"id": "U1-06-02", "module": 6, "family": 0, "topic": "Piecewise limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the two-sided limit at x = 2.", "math": "f(x)=\\begin{cases}x^2+0&x<2\\\\4&x=2\\\\x+2&x>2\\end{cases}", "answer": "4", "type": "number", "solutionSteps": ["The left limit is 4.", "The right limit is 4.", "The two-sided limit is 4; the isolated value 4 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-07-02", "module": 7, "family": 0, "topic": "The continuity test", "subtopic": "Recognize", "difficulty": "Easy", "question": "At x = 4, the left limit is 2, the right limit is 2, and f(4) is 2. Is f continuous there?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value matches the common limit."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-02", "module": 8, "family": 0, "topic": "Classifying discontinuities", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the discontinuity at x = 2 for this function.", "math": "\\frac{x^{2} - 4}{x - 2}", "answer": "Removable", "type": "choice", "solutionSteps": ["Factor the numerator and cancel x − 2.", "The nearby behavior is the finite value 4.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-02", "module": 9, "family": 0, "topic": "Factoring indeterminate limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 2}\\frac{x^{2} - 4}{x - 2}", "answer": "4", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 2 for nearby x.", "The reduced expression is $x + 2$.", "Substitute x = 2 to obtain $4$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-10-02", "module": 10, "family": 0, "topic": "Rationalizing limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 4}\\frac{\\sqrt{x} - 2}{x - 4}", "answer": "\\frac{1}{4}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{4}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.25}, {"id": "U1-11-02", "module": 11, "family": 0, "topic": "Limits from numerical tables", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the limit as x approaches 2 from the table.", "math": "", "answer": "8", "type": "number", "solutionSteps": ["As inputs approach 2 from the left, outputs approach 8.", "The right-side outputs also approach 8.", "The table suggests a limit of 8."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["1.900", "7.800"], ["1.990", "7.980"], ["1.999", "7.998"], ["2.001", "8.002"], ["2.010", "8.020"], ["2.100", "8.200"]]}, "numericAnswer": 8.0}, {"id": "U1-12-02", "module": 12, "family": 0, "topic": "Making a function continuous", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}\\frac{x^2-4}{x-2}&x\\ne 2\\\\K&x=2\\end{cases}", "answer": "4", "type": "number", "solutionSteps": ["Factor and cancel x − 2.", "The nearby expression is x + 2, with limit 4.", "Set K = 4."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-13-02", "module": 13, "family": 0, "topic": "Intermediate Value Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "For f(x) = x² on [0, 4], does IVT guarantee an interior point with f(c) = 4?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["A polynomial is continuous on the whole interval.", "The endpoint values are 0 and 16.", "The target 4 is strictly between them."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-02", "module": 14, "family": 0, "topic": "Infinite limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 4^-}\\frac{2}{(x-4)^{1}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is 2, which is nonzero.", "The denominator approaches zero negatively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": {"type": "rational", "c": 4, "L": 0, "a": 2, "power": 1, "offset": 0}, "table": null}, {"id": "U1-15-02", "module": 15, "family": 0, "topic": "Asymptotes & multiplicity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the vertical asymptote at x = 2.", "math": "f(x)=\\frac{4}{(x-2)^{2}}", "answer": "Even", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 2.", "The asymptote has even multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-02", "module": 16, "family": 0, "topic": "Rational limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{2 x^{2} + 4}{4 x^{2} + 1}", "answer": "\\frac{1}{2}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{1}{2}$.", "At the specified end, the limit is $\\frac{1}{2}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.5}, {"id": "U1-17-02", "module": 17, "family": 0, "topic": "Radical limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{4 x^{2} + 4}}{x}", "answer": "2", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $2$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-18-02", "module": 18, "family": 0, "topic": "Exponential end behavior", "subtopic": "Recognize", "difficulty": "Easy", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}2 e^{x} + 4", "answer": "4", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 4."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-19-02", "module": 19, "family": 0, "topic": "Domain, holes & restrictions", "subtopic": "Recognize", "difficulty": "Easy", "question": "Select every input excluded from the domain.", "math": "f(x)=\\frac{(x-2)(x+4)}{(x-2)(x+2)}", "answer": ["2", "-2"], "type": "multi", "solutionSteps": ["The original denominator vanishes at ±2.", "Both values are excluded even if a factor later cancels."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Easy"], "options": ["2", "-2", "0", "4"], "graph": null, "table": null}, {"id": "U1-20-02", "module": 20, "family": 0, "topic": "Intercepts & curve sketching", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the x-coordinate of the x-intercept.", "math": "f(x)=\\frac{x - 2}{x + 4}", "answer": "2", "type": "number", "solutionSteps": ["Set the numerator x − 2 equal to zero.", "At x = 2, the denominator is 6, nonzero.", "The x-intercept is (2, 0)."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-21-02", "module": 21, "family": 0, "topic": "Average rate of change", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the average rate of change on [1, 3].", "math": "f(x)=x^{2} + 2", "answer": "4", "type": "number", "solutionSteps": ["The endpoint outputs are 3 and 11.", "The input change is 2.", "Divide the output change by 2 to obtain $4$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-22-02", "module": 22, "family": 0, "topic": "Estimating instantaneous rates", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the instantaneous rate at x = 4 using the secant on [3.9, 4.1].", "math": "f(x)=2 x^{2} + 4 x", "answer": "20", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{39}{10}$ and $\\frac{41}{10}$.", "The output change is $4$ and the input change is $\\frac{1}{5}$.", "The secant estimate is $20$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 20.0}, {"id": "U1-23-02", "module": 23, "family": 0, "topic": "Squeeze Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}2x^{2}\\sin(1/x)+4", "answer": "4", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 4, both bounds approach 4.", "The Squeeze Theorem gives 4."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-24-02", "module": 24, "family": 0, "topic": "Combining limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x approaches 8, f(x) approaches 2 and g(x) approaches 4. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 8}2f(x)+3g(x)", "answer": "16", "type": "number", "solutionSteps": ["Use the component limits 2 and 4.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $16$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 16.0}, {"id": "U1-25-02", "module": 25, "family": 0, "topic": "Limits of compositions", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x → 4, g(x) → 2. If f(t) = t² + 4, find the limit of f(g(x)).", "math": "", "answer": "8", "type": "number", "solutionSteps": ["The inner output approaches 2.", "The outer polynomial is continuous.", "Evaluate f(2) = 8."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-01-03", "module": 1, "family": 0, "topic": "Understanding a limit", "subtopic": "Recognize", "difficulty": "Easy", "question": "Near x = 3, both sides of f(x) approach 6, but f(3) = 10. Find the limit.", "math": "\\lim_{x\\to 3}f(x)", "answer": "6", "type": "number", "solutionSteps": ["Nearby values from both sides approach 6.", "The value f(3) = 10 affects the point, not the nearby trend.", "The limit is 6."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-02-03", "module": 2, "family": 0, "topic": "Reading limits from graphs", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the graph to find the two-sided limit.", "math": "\\lim_{x\\to 0}f(x)", "answer": "2", "type": "number", "solutionSteps": ["Both branches approach the open point at (0, 2).", "The filled point is the function value, not the limit.", "The limit is 2."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": {"type": "hole", "c": 0, "L": 2, "value": 5, "m": 1}, "table": null, "numericAnswer": 2.0}, {"id": "U1-03-03", "module": 3, "family": 0, "topic": "One-sided limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 5^-}\\frac{3|x-5|}{x-5}", "answer": "-3", "type": "number", "solutionSteps": ["On this side, x − 5 is negative.", "Replace the absolute value with the negative of its argument.", "Cancel the nonzero factor nearby to get -3."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -3.0}, {"id": "U1-04-03", "module": 4, "family": 0, "topic": "Direct substitution", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 5}3 x + 5", "answer": "20", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 5.", "Simplify to $20$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 20.0}, {"id": "U1-05-03", "module": 5, "family": 0, "topic": "Rational & trigonometric limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 3}\\frac{x + 3}{x^{2} + 5}", "answer": "\\frac{3}{7}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $3$ for x.", "Use exact values and simplify to $\\frac{3}{7}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.42857142857142855}, {"id": "U1-06-03", "module": 6, "family": 0, "topic": "Piecewise limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the two-sided limit at x = 3.", "math": "f(x)=\\begin{cases}x^2+0&x<3\\\\5&x=3\\\\x+6&x>3\\end{cases}", "answer": "9", "type": "number", "solutionSteps": ["The left limit is 9.", "The right limit is 9.", "The two-sided limit is 9; the isolated value 5 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-07-03", "module": 7, "family": 0, "topic": "The continuity test", "subtopic": "Recognize", "difficulty": "Easy", "question": "At x = 5, the left limit is 3, the right limit is 3, and f(5) is 3. Is f continuous there?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value matches the common limit."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-03", "module": 8, "family": 0, "topic": "Classifying discontinuities", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the discontinuity at x = 3 for this function.", "math": "\\frac{x^{2} - 9}{x - 3}", "answer": "Removable", "type": "choice", "solutionSteps": ["Factor the numerator and cancel x − 3.", "The nearby behavior is the finite value 6.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-03", "module": 9, "family": 0, "topic": "Factoring indeterminate limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 3}\\frac{x^{2} - 9}{x - 3}", "answer": "6", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 3 for nearby x.", "The reduced expression is $x + 3$.", "Substitute x = 3 to obtain $6$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-10-03", "module": 10, "family": 0, "topic": "Rationalizing limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 9}\\frac{\\sqrt{x} - 3}{x - 9}", "answer": "\\frac{1}{6}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{6}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.16666666666666666}, {"id": "U1-11-03", "module": 11, "family": 0, "topic": "Limits from numerical tables", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the limit as x approaches 3 from the table.", "math": "", "answer": "11", "type": "number", "solutionSteps": ["As inputs approach 3 from the left, outputs approach 11.", "The right-side outputs also approach 11.", "The table suggests a limit of 11."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["2.900", "10.800"], ["2.990", "10.980"], ["2.999", "10.998"], ["3.001", "11.002"], ["3.010", "11.020"], ["3.100", "11.200"]]}, "numericAnswer": 11.0}, {"id": "U1-12-03", "module": 12, "family": 0, "topic": "Making a function continuous", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}\\frac{x^2-9}{x-3}&x\\ne 3\\\\K&x=3\\end{cases}", "answer": "6", "type": "number", "solutionSteps": ["Factor and cancel x − 3.", "The nearby expression is x + 3, with limit 6.", "Set K = 6."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-13-03", "module": 13, "family": 0, "topic": "Intermediate Value Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "For f(x) = x² on [0, 5], does IVT guarantee an interior point with f(c) = 9?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["A polynomial is continuous on the whole interval.", "The endpoint values are 0 and 25.", "The target 9 is strictly between them."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-03", "module": 14, "family": 0, "topic": "Infinite limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 5^-}\\frac{3}{(x-5)^{1}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is 3, which is nonzero.", "The denominator approaches zero negatively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": {"type": "rational", "c": 5, "L": 0, "a": 3, "power": 1, "offset": 0}, "table": null}, {"id": "U1-15-03", "module": 15, "family": 0, "topic": "Asymptotes & multiplicity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the vertical asymptote at x = 3.", "math": "f(x)=\\frac{5}{(x-3)^{2}}", "answer": "Even", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 2.", "The asymptote has even multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-03", "module": 16, "family": 0, "topic": "Rational limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{3 x^{2} + 5}{5 x^{2} + 1}", "answer": "\\frac{3}{5}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{3}{5}$.", "At the specified end, the limit is $\\frac{3}{5}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.6}, {"id": "U1-17-03", "module": 17, "family": 0, "topic": "Radical limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{9 x^{2} + 5}}{x}", "answer": "3", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $3$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-18-03", "module": 18, "family": 0, "topic": "Exponential end behavior", "subtopic": "Recognize", "difficulty": "Easy", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}3 e^{x} + 5", "answer": "5", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 5."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-19-03", "module": 19, "family": 0, "topic": "Domain, holes & restrictions", "subtopic": "Recognize", "difficulty": "Easy", "question": "Select every input excluded from the domain.", "math": "f(x)=\\frac{(x-3)(x+5)}{(x-3)(x+3)}", "answer": ["3", "-3"], "type": "multi", "solutionSteps": ["The original denominator vanishes at ±3.", "Both values are excluded even if a factor later cancels."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Easy"], "options": ["3", "-3", "0", "5"], "graph": null, "table": null}, {"id": "U1-20-03", "module": 20, "family": 0, "topic": "Intercepts & curve sketching", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the x-coordinate of the x-intercept.", "math": "f(x)=\\frac{x - 3}{x + 5}", "answer": "3", "type": "number", "solutionSteps": ["Set the numerator x − 3 equal to zero.", "At x = 3, the denominator is 8, nonzero.", "The x-intercept is (3, 0)."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-21-03", "module": 21, "family": 0, "topic": "Average rate of change", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the average rate of change on [2, 4].", "math": "f(x)=x^{2} + 3", "answer": "6", "type": "number", "solutionSteps": ["The endpoint outputs are 7 and 19.", "The input change is 2.", "Divide the output change by 2 to obtain $6$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-22-03", "module": 22, "family": 0, "topic": "Estimating instantaneous rates", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the instantaneous rate at x = 5 using the secant on [4.9, 5.1].", "math": "f(x)=3 x^{2} + 5 x", "answer": "35", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{49}{10}$ and $\\frac{51}{10}$.", "The output change is $7$ and the input change is $\\frac{1}{5}$.", "The secant estimate is $35$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 35.0}, {"id": "U1-23-03", "module": 23, "family": 0, "topic": "Squeeze Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}3x^{2}\\sin(1/x)+5", "answer": "5", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 5, both bounds approach 5.", "The Squeeze Theorem gives 5."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-24-03", "module": 24, "family": 0, "topic": "Combining limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x approaches 11, f(x) approaches 3 and g(x) approaches 5. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 11}2f(x)+3g(x)", "answer": "21", "type": "number", "solutionSteps": ["Use the component limits 3 and 5.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $21$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 21.0}, {"id": "U1-25-03", "module": 25, "family": 0, "topic": "Limits of compositions", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x → 5, g(x) → 3. If f(t) = t² + 5, find the limit of f(g(x)).", "math": "", "answer": "14", "type": "number", "solutionSteps": ["The inner output approaches 3.", "The outer polynomial is continuous.", "Evaluate f(3) = 14."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 14.0}, {"id": "U1-01-04", "module": 1, "family": 0, "topic": "Understanding a limit", "subtopic": "Recognize", "difficulty": "Easy", "question": "Near x = 4, both sides of f(x) approach 7, but f(4) = 11. Find the limit.", "math": "\\lim_{x\\to 4}f(x)", "answer": "7", "type": "number", "solutionSteps": ["Nearby values from both sides approach 7.", "The value f(4) = 11 affects the point, not the nearby trend.", "The limit is 7."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-02-04", "module": 2, "family": 0, "topic": "Reading limits from graphs", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the graph to find the two-sided limit.", "math": "\\lim_{x\\to 1}f(x)", "answer": "3", "type": "number", "solutionSteps": ["Both branches approach the open point at (1, 3).", "The filled point is the function value, not the limit.", "The limit is 3."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": {"type": "hole", "c": 1, "L": 3, "value": 6, "m": 1}, "table": null, "numericAnswer": 3.0}, {"id": "U1-03-04", "module": 3, "family": 0, "topic": "One-sided limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 6^-}\\frac{4|x-6|}{x-6}", "answer": "-4", "type": "number", "solutionSteps": ["On this side, x − 6 is negative.", "Replace the absolute value with the negative of its argument.", "Cancel the nonzero factor nearby to get -4."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -4.0}, {"id": "U1-04-04", "module": 4, "family": 0, "topic": "Direct substitution", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 6}4 x + 6", "answer": "30", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 6.", "Simplify to $30$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 30.0}, {"id": "U1-05-04", "module": 5, "family": 0, "topic": "Rational & trigonometric limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 4}\\frac{x + 4}{x^{2} + 6}", "answer": "\\frac{4}{11}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $4$ for x.", "Use exact values and simplify to $\\frac{4}{11}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.36363636363636365}, {"id": "U1-06-04", "module": 6, "family": 0, "topic": "Piecewise limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the two-sided limit at x = 4.", "math": "f(x)=\\begin{cases}x^2+0&x<4\\\\6&x=4\\\\x+12&x>4\\end{cases}", "answer": "16", "type": "number", "solutionSteps": ["The left limit is 16.", "The right limit is 16.", "The two-sided limit is 16; the isolated value 6 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 16.0}, {"id": "U1-07-04", "module": 7, "family": 0, "topic": "The continuity test", "subtopic": "Recognize", "difficulty": "Easy", "question": "At x = 6, the left limit is 4, the right limit is 4, and f(6) is 4. Is f continuous there?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value matches the common limit."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-04", "module": 8, "family": 0, "topic": "Classifying discontinuities", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the discontinuity at x = 4 for this function.", "math": "\\frac{x^{2} - 16}{x - 4}", "answer": "Removable", "type": "choice", "solutionSteps": ["Factor the numerator and cancel x − 4.", "The nearby behavior is the finite value 8.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-04", "module": 9, "family": 0, "topic": "Factoring indeterminate limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 4}\\frac{x^{2} - 16}{x - 4}", "answer": "8", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 4 for nearby x.", "The reduced expression is $x + 4$.", "Substitute x = 4 to obtain $8$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-10-04", "module": 10, "family": 0, "topic": "Rationalizing limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 16}\\frac{\\sqrt{x} - 4}{x - 16}", "answer": "\\frac{1}{8}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{8}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.125}, {"id": "U1-11-04", "module": 11, "family": 0, "topic": "Limits from numerical tables", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the limit as x approaches 4 from the table.", "math": "", "answer": "14", "type": "number", "solutionSteps": ["As inputs approach 4 from the left, outputs approach 14.", "The right-side outputs also approach 14.", "The table suggests a limit of 14."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["3.900", "13.800"], ["3.990", "13.980"], ["3.999", "13.998"], ["4.001", "14.002"], ["4.010", "14.020"], ["4.100", "14.200"]]}, "numericAnswer": 14.0}, {"id": "U1-12-04", "module": 12, "family": 0, "topic": "Making a function continuous", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}\\frac{x^2-16}{x-4}&x\\ne 4\\\\K&x=4\\end{cases}", "answer": "8", "type": "number", "solutionSteps": ["Factor and cancel x − 4.", "The nearby expression is x + 4, with limit 8.", "Set K = 8."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-13-04", "module": 13, "family": 0, "topic": "Intermediate Value Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "For f(x) = x² on [0, 6], does IVT guarantee an interior point with f(c) = 16?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["A polynomial is continuous on the whole interval.", "The endpoint values are 0 and 36.", "The target 16 is strictly between them."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-04", "module": 14, "family": 0, "topic": "Infinite limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 6^-}\\frac{4}{(x-6)^{1}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is 4, which is nonzero.", "The denominator approaches zero negatively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": {"type": "rational", "c": 6, "L": 0, "a": 4, "power": 1, "offset": 0}, "table": null}, {"id": "U1-15-04", "module": 15, "family": 0, "topic": "Asymptotes & multiplicity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the vertical asymptote at x = 4.", "math": "f(x)=\\frac{6}{(x-4)^{2}}", "answer": "Even", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 2.", "The asymptote has even multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-04", "module": 16, "family": 0, "topic": "Rational limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{4 x^{2} + 6}{6 x^{2} + 1}", "answer": "\\frac{2}{3}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{2}{3}$.", "At the specified end, the limit is $\\frac{2}{3}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.6666666666666666}, {"id": "U1-17-04", "module": 17, "family": 0, "topic": "Radical limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{16 x^{2} + 6}}{x}", "answer": "4", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $4$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-18-04", "module": 18, "family": 0, "topic": "Exponential end behavior", "subtopic": "Recognize", "difficulty": "Easy", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}4 e^{x} + 6", "answer": "6", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 6."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-19-04", "module": 19, "family": 0, "topic": "Domain, holes & restrictions", "subtopic": "Recognize", "difficulty": "Easy", "question": "Select every input excluded from the domain.", "math": "f(x)=\\frac{(x-4)(x+6)}{(x-4)(x+4)}", "answer": ["4", "-4"], "type": "multi", "solutionSteps": ["The original denominator vanishes at ±4.", "Both values are excluded even if a factor later cancels."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Easy"], "options": ["4", "-4", "0", "6"], "graph": null, "table": null}, {"id": "U1-20-04", "module": 20, "family": 0, "topic": "Intercepts & curve sketching", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the x-coordinate of the x-intercept.", "math": "f(x)=\\frac{x - 4}{x + 6}", "answer": "4", "type": "number", "solutionSteps": ["Set the numerator x − 4 equal to zero.", "At x = 4, the denominator is 10, nonzero.", "The x-intercept is (4, 0)."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-21-04", "module": 21, "family": 0, "topic": "Average rate of change", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the average rate of change on [3, 5].", "math": "f(x)=x^{2} + 4", "answer": "8", "type": "number", "solutionSteps": ["The endpoint outputs are 13 and 29.", "The input change is 2.", "Divide the output change by 2 to obtain $8$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-22-04", "module": 22, "family": 0, "topic": "Estimating instantaneous rates", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the instantaneous rate at x = 6 using the secant on [5.9, 6.1].", "math": "f(x)=4 x^{2} + 6 x", "answer": "54", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{59}{10}$ and $\\frac{61}{10}$.", "The output change is $\\frac{54}{5}$ and the input change is $\\frac{1}{5}$.", "The secant estimate is $54$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 54.0}, {"id": "U1-23-04", "module": 23, "family": 0, "topic": "Squeeze Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}4x^{2}\\sin(1/x)+6", "answer": "6", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 6, both bounds approach 6.", "The Squeeze Theorem gives 6."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-24-04", "module": 24, "family": 0, "topic": "Combining limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x approaches 14, f(x) approaches 4 and g(x) approaches 6. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 14}2f(x)+3g(x)", "answer": "26", "type": "number", "solutionSteps": ["Use the component limits 4 and 6.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $26$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 26.0}, {"id": "U1-25-04", "module": 25, "family": 0, "topic": "Limits of compositions", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x → 6, g(x) → 4. If f(t) = t² + 6, find the limit of f(g(x)).", "math": "", "answer": "22", "type": "number", "solutionSteps": ["The inner output approaches 4.", "The outer polynomial is continuous.", "Evaluate f(4) = 22."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 22.0}, {"id": "U1-01-05", "module": 1, "family": 0, "topic": "Understanding a limit", "subtopic": "Recognize", "difficulty": "Easy", "question": "Near x = 5, both sides of f(x) approach 8, but f(5) = 12. Find the limit.", "math": "\\lim_{x\\to 5}f(x)", "answer": "8", "type": "number", "solutionSteps": ["Nearby values from both sides approach 8.", "The value f(5) = 12 affects the point, not the nearby trend.", "The limit is 8."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-02-05", "module": 2, "family": 0, "topic": "Reading limits from graphs", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the graph to find the two-sided limit.", "math": "\\lim_{x\\to 2}f(x)", "answer": "4", "type": "number", "solutionSteps": ["Both branches approach the open point at (2, 4).", "The filled point is the function value, not the limit.", "The limit is 4."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": {"type": "hole", "c": 2, "L": 4, "value": 7, "m": 1}, "table": null, "numericAnswer": 4.0}, {"id": "U1-03-05", "module": 3, "family": 0, "topic": "One-sided limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 7^-}\\frac{5|x-7|}{x-7}", "answer": "-5", "type": "number", "solutionSteps": ["On this side, x − 7 is negative.", "Replace the absolute value with the negative of its argument.", "Cancel the nonzero factor nearby to get -5."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -5.0}, {"id": "U1-04-05", "module": 4, "family": 0, "topic": "Direct substitution", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 7}5 x + 7", "answer": "42", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 7.", "Simplify to $42$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 42.0}, {"id": "U1-05-05", "module": 5, "family": 0, "topic": "Rational & trigonometric limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 5}\\frac{x + 5}{x^{2} + 7}", "answer": "\\frac{5}{16}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $5$ for x.", "Use exact values and simplify to $\\frac{5}{16}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.3125}, {"id": "U1-06-05", "module": 6, "family": 0, "topic": "Piecewise limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the two-sided limit at x = 5.", "math": "f(x)=\\begin{cases}x^2+0&x<5\\\\7&x=5\\\\x+20&x>5\\end{cases}", "answer": "25", "type": "number", "solutionSteps": ["The left limit is 25.", "The right limit is 25.", "The two-sided limit is 25; the isolated value 7 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 25.0}, {"id": "U1-07-05", "module": 7, "family": 0, "topic": "The continuity test", "subtopic": "Recognize", "difficulty": "Easy", "question": "At x = 7, the left limit is 5, the right limit is 5, and f(7) is 5. Is f continuous there?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value matches the common limit."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-05", "module": 8, "family": 0, "topic": "Classifying discontinuities", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the discontinuity at x = 5 for this function.", "math": "\\frac{x^{2} - 25}{x - 5}", "answer": "Removable", "type": "choice", "solutionSteps": ["Factor the numerator and cancel x − 5.", "The nearby behavior is the finite value 10.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-05", "module": 9, "family": 0, "topic": "Factoring indeterminate limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 5}\\frac{x^{2} - 25}{x - 5}", "answer": "10", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 5 for nearby x.", "The reduced expression is $x + 5$.", "Substitute x = 5 to obtain $10$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-10-05", "module": 10, "family": 0, "topic": "Rationalizing limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 25}\\frac{\\sqrt{x} - 5}{x - 25}", "answer": "\\frac{1}{10}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{10}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.1}, {"id": "U1-11-05", "module": 11, "family": 0, "topic": "Limits from numerical tables", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the limit as x approaches 5 from the table.", "math": "", "answer": "17", "type": "number", "solutionSteps": ["As inputs approach 5 from the left, outputs approach 17.", "The right-side outputs also approach 17.", "The table suggests a limit of 17."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["4.900", "16.800"], ["4.990", "16.980"], ["4.999", "16.998"], ["5.001", "17.002"], ["5.010", "17.020"], ["5.100", "17.200"]]}, "numericAnswer": 17.0}, {"id": "U1-12-05", "module": 12, "family": 0, "topic": "Making a function continuous", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}\\frac{x^2-25}{x-5}&x\\ne 5\\\\K&x=5\\end{cases}", "answer": "10", "type": "number", "solutionSteps": ["Factor and cancel x − 5.", "The nearby expression is x + 5, with limit 10.", "Set K = 10."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-13-05", "module": 13, "family": 0, "topic": "Intermediate Value Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "For f(x) = x² on [0, 7], does IVT guarantee an interior point with f(c) = 25?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["A polynomial is continuous on the whole interval.", "The endpoint values are 0 and 49.", "The target 25 is strictly between them."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-05", "module": 14, "family": 0, "topic": "Infinite limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 7^-}\\frac{5}{(x-7)^{1}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is 5, which is nonzero.", "The denominator approaches zero negatively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": {"type": "rational", "c": 7, "L": 0, "a": 5, "power": 1, "offset": 0}, "table": null}, {"id": "U1-15-05", "module": 15, "family": 0, "topic": "Asymptotes & multiplicity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the vertical asymptote at x = 5.", "math": "f(x)=\\frac{7}{(x-5)^{2}}", "answer": "Even", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 2.", "The asymptote has even multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-05", "module": 16, "family": 0, "topic": "Rational limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{5 x^{2} + 7}{7 x^{2} + 1}", "answer": "\\frac{5}{7}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{5}{7}$.", "At the specified end, the limit is $\\frac{5}{7}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.7142857142857143}, {"id": "U1-17-05", "module": 17, "family": 0, "topic": "Radical limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{25 x^{2} + 7}}{x}", "answer": "5", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $5$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-18-05", "module": 18, "family": 0, "topic": "Exponential end behavior", "subtopic": "Recognize", "difficulty": "Easy", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}5 e^{x} + 7", "answer": "7", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 7."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-19-05", "module": 19, "family": 0, "topic": "Domain, holes & restrictions", "subtopic": "Recognize", "difficulty": "Easy", "question": "Select every input excluded from the domain.", "math": "f(x)=\\frac{(x-5)(x+7)}{(x-5)(x+5)}", "answer": ["5", "-5"], "type": "multi", "solutionSteps": ["The original denominator vanishes at ±5.", "Both values are excluded even if a factor later cancels."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Easy"], "options": ["5", "-5", "0", "7"], "graph": null, "table": null}, {"id": "U1-20-05", "module": 20, "family": 0, "topic": "Intercepts & curve sketching", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the x-coordinate of the x-intercept.", "math": "f(x)=\\frac{x - 5}{x + 7}", "answer": "5", "type": "number", "solutionSteps": ["Set the numerator x − 5 equal to zero.", "At x = 5, the denominator is 12, nonzero.", "The x-intercept is (5, 0)."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-21-05", "module": 21, "family": 0, "topic": "Average rate of change", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the average rate of change on [4, 6].", "math": "f(x)=x^{2} + 5", "answer": "10", "type": "number", "solutionSteps": ["The endpoint outputs are 21 and 41.", "The input change is 2.", "Divide the output change by 2 to obtain $10$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-22-05", "module": 22, "family": 0, "topic": "Estimating instantaneous rates", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the instantaneous rate at x = 7 using the secant on [6.9, 7.1].", "math": "f(x)=5 x^{2} + 7 x", "answer": "77", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{69}{10}$ and $\\frac{71}{10}$.", "The output change is $\\frac{77}{5}$ and the input change is $\\frac{1}{5}$.", "The secant estimate is $77$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 77.0}, {"id": "U1-23-05", "module": 23, "family": 0, "topic": "Squeeze Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}5x^{2}\\sin(1/x)+7", "answer": "7", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 7, both bounds approach 7.", "The Squeeze Theorem gives 7."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-24-05", "module": 24, "family": 0, "topic": "Combining limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x approaches 17, f(x) approaches 5 and g(x) approaches 7. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 17}2f(x)+3g(x)", "answer": "31", "type": "number", "solutionSteps": ["Use the component limits 5 and 7.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $31$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 31.0}, {"id": "U1-25-05", "module": 25, "family": 0, "topic": "Limits of compositions", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x → 7, g(x) → 5. If f(t) = t² + 7, find the limit of f(g(x)).", "math": "", "answer": "32", "type": "number", "solutionSteps": ["The inner output approaches 5.", "The outer polynomial is continuous.", "Evaluate f(5) = 32."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 32.0}, {"id": "U1-01-06", "module": 1, "family": 1, "topic": "Understanding a limit", "subtopic": "Apply", "difficulty": "Easy", "question": "The left limit is 1 and the right limit is 3. Find the two-sided limit.", "math": "\\lim_{x\\to 4}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left side approaches 1.", "The right side approaches 3.", "The sides differ, so the two-sided limit does not exist."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Easy"], "options": ["DNE", "1", "3", "4"], "graph": null, "table": null}, {"id": "U1-02-06", "module": 2, "family": 1, "topic": "Reading limits from graphs", "subtopic": "Apply", "difficulty": "Easy", "question": "Use the filled point to find f(-2).", "math": "", "answer": "3", "type": "number", "solutionSteps": ["Locate x = -2.", "The closed point has height 3.", "f(-2) = 3."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": {"type": "hole", "c": -2, "L": 0, "value": 3, "m": 1}, "table": null, "numericAnswer": 3.0}, {"id": "U1-03-06", "module": 3, "family": 1, "topic": "One-sided limits", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 3^+}\\frac{1|x-3|}{x-3}", "answer": "1", "type": "number", "solutionSteps": ["On this side, x − 3 is positive.", "Replace the absolute value with its argument.", "Cancel the nonzero factor nearby to get 1."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-04-06", "module": 4, "family": 1, "topic": "Direct substitution", "subtopic": "Apply", "difficulty": "Easy", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to -1}x^{2} - x + 3", "answer": "5", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = -1.", "Simplify to $5$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-05-06", "module": 5, "family": 1, "topic": "Rational & trigonometric limits", "subtopic": "Apply", "difficulty": "Easy", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 0}\\sin{\\left(x \\right)} + \\cos{\\left(x \\right)}", "answer": "1", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $0$ for x.", "Use exact values and simplify to $1$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-06-06", "module": 6, "family": 1, "topic": "Piecewise limits", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the two-sided limit at x = 1.", "math": "f(x)=\\begin{cases}x^2+2&x<1\\\\4&x=1\\\\x+3&x>1\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 3.", "The right limit is 4.", "The two-sided limit is DNE; the isolated value 4 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Easy"], "options": ["DNE", "3", "4", "4"], "graph": null, "table": null}, {"id": "U1-07-06", "module": 7, "family": 1, "topic": "The continuity test", "subtopic": "Apply", "difficulty": "Easy", "question": "At x = 3, the left limit is 1, the right limit is 1, and f(3) is 3. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-06", "module": 8, "family": 1, "topic": "Classifying discontinuities", "subtopic": "Apply", "difficulty": "Easy", "question": "Classify the discontinuity at x = 1 for this function.", "math": "\\frac{1}{\\left(x - 1\\right)^{2}}", "answer": "Infinite", "type": "choice", "solutionSteps": ["The squared denominator approaches zero positively.", "The nearby behavior is unbounded.", "This is a infinite discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-06", "module": 9, "family": 1, "topic": "Factoring indeterminate limits", "subtopic": "Apply", "difficulty": "Easy", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 1}\\frac{x^{3} - 1}{x - 1}", "answer": "3", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 1 for nearby x.", "The reduced expression is $x^{2} + x + 1$.", "Substitute x = 1 to obtain $3$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-10-06", "module": 10, "family": 1, "topic": "Rationalizing limits", "subtopic": "Apply", "difficulty": "Easy", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 1}\\frac{x - 1}{\\sqrt{x} - 1}", "answer": "2", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $2$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-11-06", "module": 11, "family": 1, "topic": "Limits from numerical tables", "subtopic": "Apply", "difficulty": "Easy", "question": "Does this finite table prove the limit at x = 1 with absolute certainty?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Only finitely many values are shown.", "Unsampled values could behave differently.", "The table provides evidence, not a proof."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["0.900", "4.800"], ["0.990", "4.980"], ["0.999", "4.998"], ["1.001", "5.002"], ["1.010", "5.020"], ["1.100", "5.200"]]}}, {"id": "U1-12-06", "module": 12, "family": 1, "topic": "Making a function continuous", "subtopic": "Apply", "difficulty": "Easy", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2&x<1\\\\x+K&x\\ge 1\\end{cases}", "answer": "0", "type": "number", "solutionSteps": ["The left limit is 1.", "The right limit and point value are 1 + K.", "Solve 1 + K = 1, giving K = 0."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-13-06", "module": 13, "family": 1, "topic": "Intermediate Value Theorem", "subtopic": "Apply", "difficulty": "Easy", "question": "For f(x) = 1/(x − 1) on [0, 2], does IVT apply across the entire interval?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["The denominator is zero at 1.", "This point lies inside the interval.", "Continuity on the full closed interval fails."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-06", "module": 14, "family": 1, "topic": "Infinite limits", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 3^+}\\frac{1}{(x-3)^{1}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 1, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": {"type": "rational", "c": 3, "L": 0, "a": 1, "power": 1, "offset": 0}, "table": null}, {"id": "U1-15-06", "module": 15, "family": 1, "topic": "Asymptotes & multiplicity", "subtopic": "Apply", "difficulty": "Easy", "question": "Classify the vertical asymptote at x = 1.", "math": "f(x)=\\frac{3}{(x-1)^{3}}", "answer": "Odd", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 3.", "The asymptote has odd multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-06", "module": 16, "family": 1, "topic": "Rational limits at infinity", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{x + 3}{x^{2} + 1}", "answer": "0", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{1}{x}$.", "At the specified end, the limit is $0$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-17-06", "module": 17, "family": 1, "topic": "Radical limits at infinity", "subtopic": "Apply", "difficulty": "Easy", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{x^{2} + 3}}{x}", "answer": "-1", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $-1$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -1.0}, {"id": "U1-18-06", "module": 18, "family": 1, "topic": "Exponential end behavior", "subtopic": "Apply", "difficulty": "Easy", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}1 + e^{- x}", "answer": "1", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 1."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-19-06", "module": 19, "family": 1, "topic": "Domain, holes & restrictions", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the y-coordinate of the hole at x = 1.", "math": "f(x)=\\frac{(x-1)(x+3)}{(x-1)(x+1)}", "answer": "2", "type": "number", "solutionSteps": ["Cancel x − 1.", "Evaluate (x + 3)/(x + 1) at x = 1.", "The hole has height $2$."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-20-06", "module": 20, "family": 1, "topic": "Intercepts & curve sketching", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the y-coordinate of the y-intercept.", "math": "f(x)=\\frac{x - 1}{x + 3}", "answer": "- \\frac{1}{3}", "type": "number", "solutionSteps": ["Set x = 0.", "The numerator is −1 and denominator is 3.", "The y-intercept has height $- \\frac{1}{3}$."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -0.3333333333333333}, {"id": "U1-21-06", "module": 21, "family": 1, "topic": "Average rate of change", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the average rate of change on [0, 2].", "math": "f(x)=x^{3} - 3 x", "answer": "1", "type": "number", "solutionSteps": ["The endpoint outputs are 0 and 2.", "The input change is 2.", "Divide the output change by 2 to obtain $1$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-22-06", "module": 22, "family": 1, "topic": "Estimating instantaneous rates", "subtopic": "Apply", "difficulty": "Easy", "question": "Estimate the instantaneous rate at x = 3 using the secant on [2.99, 3.01].", "math": "f(x)=x^{2} + 3 x", "answer": "9", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{299}{100}$ and $\\frac{301}{100}$.", "The output change is $\\frac{9}{50}$ and the input change is $\\frac{1}{50}$.", "The secant estimate is $9$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-23-06", "module": 23, "family": 1, "topic": "Squeeze Theorem", "subtopic": "Apply", "difficulty": "Easy", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}1x^{4}\\sin(1/x)+3", "answer": "3", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 3, both bounds approach 3.", "The Squeeze Theorem gives 3."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-24-06", "module": 24, "family": 1, "topic": "Combining limits", "subtopic": "Apply", "difficulty": "Easy", "question": "As x approaches 5, f(x) approaches 1 and g(x) approaches 3. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 5}f(x)g(x)", "answer": "3", "type": "number", "solutionSteps": ["Use the component limits 1 and 3.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $3$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-25-06", "module": 25, "family": 1, "topic": "Limits of compositions", "subtopic": "Apply", "difficulty": "Easy", "question": "Let f(t) = 1 for t < 3, f(t) = 6 for t > 3, and f(3) = 99. If g(x) = 3 − x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "1", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) < 3.", "The inner output approaches the boundary from below.", "The outer left branch is always 1."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-01-07", "module": 1, "family": 1, "topic": "Understanding a limit", "subtopic": "Apply", "difficulty": "Medium", "question": "The left limit is 2 and the right limit is 4. Find the two-sided limit.", "math": "\\lim_{x\\to 5}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left side approaches 2.", "The right side approaches 4.", "The sides differ, so the two-sided limit does not exist."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "2", "4", "5"], "graph": null, "table": null}, {"id": "U1-02-07", "module": 2, "family": 1, "topic": "Reading limits from graphs", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the filled point to find f(-1).", "math": "", "answer": "4", "type": "number", "solutionSteps": ["Locate x = -1.", "The closed point has height 4.", "f(-1) = 4."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": {"type": "hole", "c": -1, "L": 1, "value": 4, "m": 1}, "table": null, "numericAnswer": 4.0}, {"id": "U1-03-07", "module": 3, "family": 1, "topic": "One-sided limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 4^+}\\frac{2|x-4|}{x-4}", "answer": "2", "type": "number", "solutionSteps": ["On this side, x − 4 is positive.", "Replace the absolute value with its argument.", "Cancel the nonzero factor nearby to get 2."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-04-07", "module": 4, "family": 1, "topic": "Direct substitution", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to -2}x^{2} - 2 x + 4", "answer": "12", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = -2.", "Simplify to $12$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-05-07", "module": 5, "family": 1, "topic": "Rational & trigonometric limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 0}\\sin{\\left(x \\right)} + 2 \\cos{\\left(x \\right)}", "answer": "2", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $0$ for x.", "Use exact values and simplify to $2$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-06-07", "module": 6, "family": 1, "topic": "Piecewise limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the two-sided limit at x = 2.", "math": "f(x)=\\begin{cases}x^2+2&x<2\\\\5&x=2\\\\x+5&x>2\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 6.", "The right limit is 7.", "The two-sided limit is DNE; the isolated value 5 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "6", "7", "5"], "graph": null, "table": null}, {"id": "U1-07-07", "module": 7, "family": 1, "topic": "The continuity test", "subtopic": "Apply", "difficulty": "Medium", "question": "At x = 4, the left limit is 2, the right limit is 2, and f(4) is 4. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-07", "module": 8, "family": 1, "topic": "Classifying discontinuities", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the discontinuity at x = 2 for this function.", "math": "\\frac{1}{\\left(x - 2\\right)^{2}}", "answer": "Infinite", "type": "choice", "solutionSteps": ["The squared denominator approaches zero positively.", "The nearby behavior is unbounded.", "This is a infinite discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-07", "module": 9, "family": 1, "topic": "Factoring indeterminate limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 2}\\frac{x^{3} - 8}{x - 2}", "answer": "12", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 2 for nearby x.", "The reduced expression is $x^{2} + 2 x + 4$.", "Substitute x = 2 to obtain $12$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-10-07", "module": 10, "family": 1, "topic": "Rationalizing limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 4}\\frac{x - 4}{\\sqrt{x} - 2}", "answer": "4", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $4$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-11-07", "module": 11, "family": 1, "topic": "Limits from numerical tables", "subtopic": "Apply", "difficulty": "Medium", "question": "Does this finite table prove the limit at x = 2 with absolute certainty?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Only finitely many values are shown.", "Unsampled values could behave differently.", "The table provides evidence, not a proof."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["1.900", "7.800"], ["1.990", "7.980"], ["1.999", "7.998"], ["2.001", "8.002"], ["2.010", "8.020"], ["2.100", "8.200"]]}}, {"id": "U1-12-07", "module": 12, "family": 1, "topic": "Making a function continuous", "subtopic": "Apply", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2&x<2\\\\x+K&x\\ge 2\\end{cases}", "answer": "2", "type": "number", "solutionSteps": ["The left limit is 4.", "The right limit and point value are 2 + K.", "Solve 2 + K = 4, giving K = 2."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-13-07", "module": 13, "family": 1, "topic": "Intermediate Value Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "For f(x) = 1/(x − 2) on [1, 3], does IVT apply across the entire interval?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["The denominator is zero at 2.", "This point lies inside the interval.", "Continuity on the full closed interval fails."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-07", "module": 14, "family": 1, "topic": "Infinite limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 4^+}\\frac{2}{(x-4)^{1}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 2, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-07", "module": 15, "family": 1, "topic": "Asymptotes & multiplicity", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the vertical asymptote at x = 2.", "math": "f(x)=\\frac{4}{(x-2)^{3}}", "answer": "Odd", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 3.", "The asymptote has odd multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-07", "module": 16, "family": 1, "topic": "Rational limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{2 x + 4}{x^{2} + 1}", "answer": "0", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{2}{x}$.", "At the specified end, the limit is $0$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-17-07", "module": 17, "family": 1, "topic": "Radical limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{4 x^{2} + 4}}{x}", "answer": "-2", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $-2$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -2.0}, {"id": "U1-18-07", "module": 18, "family": 1, "topic": "Exponential end behavior", "subtopic": "Apply", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}2 + e^{- x}", "answer": "2", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 2."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-19-07", "module": 19, "family": 1, "topic": "Domain, holes & restrictions", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the hole at x = 2.", "math": "f(x)=\\frac{(x-2)(x+4)}{(x-2)(x+2)}", "answer": "\\frac{3}{2}", "type": "number", "solutionSteps": ["Cancel x − 2.", "Evaluate (x + 4)/(x + 2) at x = 2.", "The hole has height $\\frac{3}{2}$."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.5}, {"id": "U1-20-07", "module": 20, "family": 1, "topic": "Intercepts & curve sketching", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the y-intercept.", "math": "f(x)=\\frac{x - 2}{x + 4}", "answer": "- \\frac{1}{2}", "type": "number", "solutionSteps": ["Set x = 0.", "The numerator is −2 and denominator is 4.", "The y-intercept has height $- \\frac{1}{2}$."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -0.5}, {"id": "U1-21-07", "module": 21, "family": 1, "topic": "Average rate of change", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the average rate of change on [1, 3].", "math": "f(x)=2 x^{3} - 4 x", "answer": "22", "type": "number", "solutionSteps": ["The endpoint outputs are -2 and 42.", "The input change is 2.", "Divide the output change by 2 to obtain $22$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 22.0}, {"id": "U1-22-07", "module": 22, "family": 1, "topic": "Estimating instantaneous rates", "subtopic": "Apply", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 4 using the secant on [3.99, 4.01].", "math": "f(x)=2 x^{2} + 4 x", "answer": "20", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{399}{100}$ and $\\frac{401}{100}$.", "The output change is $\\frac{2}{5}$ and the input change is $\\frac{1}{50}$.", "The secant estimate is $20$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 20.0}, {"id": "U1-23-07", "module": 23, "family": 1, "topic": "Squeeze Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}2x^{4}\\sin(1/x)+4", "answer": "4", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 4, both bounds approach 4.", "The Squeeze Theorem gives 4."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-24-07", "module": 24, "family": 1, "topic": "Combining limits", "subtopic": "Apply", "difficulty": "Medium", "question": "As x approaches 8, f(x) approaches 2 and g(x) approaches 4. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 8}f(x)g(x)", "answer": "8", "type": "number", "solutionSteps": ["Use the component limits 2 and 4.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $8$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-25-07", "module": 25, "family": 1, "topic": "Limits of compositions", "subtopic": "Apply", "difficulty": "Medium", "question": "Let f(t) = 2 for t < 4, f(t) = 7 for t > 4, and f(4) = 99. If g(x) = 4 − x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "2", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) < 4.", "The inner output approaches the boundary from below.", "The outer left branch is always 2."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-01-08", "module": 1, "family": 1, "topic": "Understanding a limit", "subtopic": "Apply", "difficulty": "Medium", "question": "The left limit is 3 and the right limit is 5. Find the two-sided limit.", "math": "\\lim_{x\\to 6}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left side approaches 3.", "The right side approaches 5.", "The sides differ, so the two-sided limit does not exist."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "3", "5", "6"], "graph": null, "table": null}, {"id": "U1-02-08", "module": 2, "family": 1, "topic": "Reading limits from graphs", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the filled point to find f(0).", "math": "", "answer": "5", "type": "number", "solutionSteps": ["Locate x = 0.", "The closed point has height 5.", "f(0) = 5."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": {"type": "hole", "c": 0, "L": 2, "value": 5, "m": 1}, "table": null, "numericAnswer": 5.0}, {"id": "U1-03-08", "module": 3, "family": 1, "topic": "One-sided limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 5^+}\\frac{3|x-5|}{x-5}", "answer": "3", "type": "number", "solutionSteps": ["On this side, x − 5 is positive.", "Replace the absolute value with its argument.", "Cancel the nonzero factor nearby to get 3."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-04-08", "module": 4, "family": 1, "topic": "Direct substitution", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to -3}x^{2} - 3 x + 5", "answer": "23", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = -3.", "Simplify to $23$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 23.0}, {"id": "U1-05-08", "module": 5, "family": 1, "topic": "Rational & trigonometric limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 0}\\sin{\\left(x \\right)} + 3 \\cos{\\left(x \\right)}", "answer": "3", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $0$ for x.", "Use exact values and simplify to $3$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-06-08", "module": 6, "family": 1, "topic": "Piecewise limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the two-sided limit at x = 3.", "math": "f(x)=\\begin{cases}x^2+2&x<3\\\\6&x=3\\\\x+9&x>3\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 11.", "The right limit is 12.", "The two-sided limit is DNE; the isolated value 6 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "11", "12", "6"], "graph": null, "table": null}, {"id": "U1-07-08", "module": 7, "family": 1, "topic": "The continuity test", "subtopic": "Apply", "difficulty": "Medium", "question": "At x = 5, the left limit is 3, the right limit is 3, and f(5) is 5. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-08", "module": 8, "family": 1, "topic": "Classifying discontinuities", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the discontinuity at x = 3 for this function.", "math": "\\frac{1}{\\left(x - 3\\right)^{2}}", "answer": "Infinite", "type": "choice", "solutionSteps": ["The squared denominator approaches zero positively.", "The nearby behavior is unbounded.", "This is a infinite discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-08", "module": 9, "family": 1, "topic": "Factoring indeterminate limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 3}\\frac{x^{3} - 27}{x - 3}", "answer": "27", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 3 for nearby x.", "The reduced expression is $x^{2} + 3 x + 9$.", "Substitute x = 3 to obtain $27$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 27.0}, {"id": "U1-10-08", "module": 10, "family": 1, "topic": "Rationalizing limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 9}\\frac{x - 9}{\\sqrt{x} - 3}", "answer": "6", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $6$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-11-08", "module": 11, "family": 1, "topic": "Limits from numerical tables", "subtopic": "Apply", "difficulty": "Medium", "question": "Does this finite table prove the limit at x = 3 with absolute certainty?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Only finitely many values are shown.", "Unsampled values could behave differently.", "The table provides evidence, not a proof."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["2.900", "10.800"], ["2.990", "10.980"], ["2.999", "10.998"], ["3.001", "11.002"], ["3.010", "11.020"], ["3.100", "11.200"]]}}, {"id": "U1-12-08", "module": 12, "family": 1, "topic": "Making a function continuous", "subtopic": "Apply", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2&x<3\\\\x+K&x\\ge 3\\end{cases}", "answer": "6", "type": "number", "solutionSteps": ["The left limit is 9.", "The right limit and point value are 3 + K.", "Solve 3 + K = 9, giving K = 6."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-13-08", "module": 13, "family": 1, "topic": "Intermediate Value Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "For f(x) = 1/(x − 3) on [2, 4], does IVT apply across the entire interval?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["The denominator is zero at 3.", "This point lies inside the interval.", "Continuity on the full closed interval fails."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-08", "module": 14, "family": 1, "topic": "Infinite limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 5^+}\\frac{3}{(x-5)^{1}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 3, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-08", "module": 15, "family": 1, "topic": "Asymptotes & multiplicity", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the vertical asymptote at x = 3.", "math": "f(x)=\\frac{5}{(x-3)^{3}}", "answer": "Odd", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 3.", "The asymptote has odd multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-08", "module": 16, "family": 1, "topic": "Rational limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{3 x + 5}{x^{2} + 1}", "answer": "0", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{3}{x}$.", "At the specified end, the limit is $0$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-17-08", "module": 17, "family": 1, "topic": "Radical limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{9 x^{2} + 5}}{x}", "answer": "-3", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $-3$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -3.0}, {"id": "U1-18-08", "module": 18, "family": 1, "topic": "Exponential end behavior", "subtopic": "Apply", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}3 + e^{- x}", "answer": "3", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 3."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-19-08", "module": 19, "family": 1, "topic": "Domain, holes & restrictions", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the hole at x = 3.", "math": "f(x)=\\frac{(x-3)(x+5)}{(x-3)(x+3)}", "answer": "\\frac{4}{3}", "type": "number", "solutionSteps": ["Cancel x − 3.", "Evaluate (x + 5)/(x + 3) at x = 3.", "The hole has height $\\frac{4}{3}$."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.3333333333333333}, {"id": "U1-20-08", "module": 20, "family": 1, "topic": "Intercepts & curve sketching", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the y-intercept.", "math": "f(x)=\\frac{x - 3}{x + 5}", "answer": "- \\frac{3}{5}", "type": "number", "solutionSteps": ["Set x = 0.", "The numerator is −3 and denominator is 5.", "The y-intercept has height $- \\frac{3}{5}$."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -0.6}, {"id": "U1-21-08", "module": 21, "family": 1, "topic": "Average rate of change", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the average rate of change on [2, 4].", "math": "f(x)=3 x^{3} - 5 x", "answer": "79", "type": "number", "solutionSteps": ["The endpoint outputs are 14 and 172.", "The input change is 2.", "Divide the output change by 2 to obtain $79$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 79.0}, {"id": "U1-22-08", "module": 22, "family": 1, "topic": "Estimating instantaneous rates", "subtopic": "Apply", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 5 using the secant on [4.99, 5.01].", "math": "f(x)=3 x^{2} + 5 x", "answer": "35", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{499}{100}$ and $\\frac{501}{100}$.", "The output change is $\\frac{7}{10}$ and the input change is $\\frac{1}{50}$.", "The secant estimate is $35$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 35.0}, {"id": "U1-23-08", "module": 23, "family": 1, "topic": "Squeeze Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}3x^{4}\\sin(1/x)+5", "answer": "5", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 5, both bounds approach 5.", "The Squeeze Theorem gives 5."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-24-08", "module": 24, "family": 1, "topic": "Combining limits", "subtopic": "Apply", "difficulty": "Medium", "question": "As x approaches 11, f(x) approaches 3 and g(x) approaches 5. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 11}f(x)g(x)", "answer": "15", "type": "number", "solutionSteps": ["Use the component limits 3 and 5.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $15$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 15.0}, {"id": "U1-25-08", "module": 25, "family": 1, "topic": "Limits of compositions", "subtopic": "Apply", "difficulty": "Medium", "question": "Let f(t) = 3 for t < 5, f(t) = 8 for t > 5, and f(5) = 99. If g(x) = 5 − x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "3", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) < 5.", "The inner output approaches the boundary from below.", "The outer left branch is always 3."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-01-09", "module": 1, "family": 1, "topic": "Understanding a limit", "subtopic": "Apply", "difficulty": "Medium", "question": "The left limit is 4 and the right limit is 6. Find the two-sided limit.", "math": "\\lim_{x\\to 7}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left side approaches 4.", "The right side approaches 6.", "The sides differ, so the two-sided limit does not exist."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "4", "6", "7"], "graph": null, "table": null}, {"id": "U1-02-09", "module": 2, "family": 1, "topic": "Reading limits from graphs", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the filled point to find f(1).", "math": "", "answer": "6", "type": "number", "solutionSteps": ["Locate x = 1.", "The closed point has height 6.", "f(1) = 6."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": {"type": "hole", "c": 1, "L": 3, "value": 6, "m": 1}, "table": null, "numericAnswer": 6.0}, {"id": "U1-03-09", "module": 3, "family": 1, "topic": "One-sided limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 6^+}\\frac{4|x-6|}{x-6}", "answer": "4", "type": "number", "solutionSteps": ["On this side, x − 6 is positive.", "Replace the absolute value with its argument.", "Cancel the nonzero factor nearby to get 4."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-04-09", "module": 4, "family": 1, "topic": "Direct substitution", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to -4}x^{2} - 4 x + 6", "answer": "38", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = -4.", "Simplify to $38$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 38.0}, {"id": "U1-05-09", "module": 5, "family": 1, "topic": "Rational & trigonometric limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 0}\\sin{\\left(x \\right)} + 4 \\cos{\\left(x \\right)}", "answer": "4", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $0$ for x.", "Use exact values and simplify to $4$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-06-09", "module": 6, "family": 1, "topic": "Piecewise limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the two-sided limit at x = 4.", "math": "f(x)=\\begin{cases}x^2+2&x<4\\\\7&x=4\\\\x+15&x>4\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 18.", "The right limit is 19.", "The two-sided limit is DNE; the isolated value 7 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "18", "19", "7"], "graph": null, "table": null}, {"id": "U1-07-09", "module": 7, "family": 1, "topic": "The continuity test", "subtopic": "Apply", "difficulty": "Medium", "question": "At x = 6, the left limit is 4, the right limit is 4, and f(6) is 6. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-09", "module": 8, "family": 1, "topic": "Classifying discontinuities", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the discontinuity at x = 4 for this function.", "math": "\\frac{1}{\\left(x - 4\\right)^{2}}", "answer": "Infinite", "type": "choice", "solutionSteps": ["The squared denominator approaches zero positively.", "The nearby behavior is unbounded.", "This is a infinite discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-09", "module": 9, "family": 1, "topic": "Factoring indeterminate limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 4}\\frac{x^{3} - 64}{x - 4}", "answer": "48", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 4 for nearby x.", "The reduced expression is $x^{2} + 4 x + 16$.", "Substitute x = 4 to obtain $48$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 48.0}, {"id": "U1-10-09", "module": 10, "family": 1, "topic": "Rationalizing limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 16}\\frac{x - 16}{\\sqrt{x} - 4}", "answer": "8", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $8$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-11-09", "module": 11, "family": 1, "topic": "Limits from numerical tables", "subtopic": "Apply", "difficulty": "Medium", "question": "Does this finite table prove the limit at x = 4 with absolute certainty?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Only finitely many values are shown.", "Unsampled values could behave differently.", "The table provides evidence, not a proof."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["3.900", "13.800"], ["3.990", "13.980"], ["3.999", "13.998"], ["4.001", "14.002"], ["4.010", "14.020"], ["4.100", "14.200"]]}}, {"id": "U1-12-09", "module": 12, "family": 1, "topic": "Making a function continuous", "subtopic": "Apply", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2&x<4\\\\x+K&x\\ge 4\\end{cases}", "answer": "12", "type": "number", "solutionSteps": ["The left limit is 16.", "The right limit and point value are 4 + K.", "Solve 4 + K = 16, giving K = 12."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-13-09", "module": 13, "family": 1, "topic": "Intermediate Value Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "For f(x) = 1/(x − 4) on [3, 5], does IVT apply across the entire interval?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["The denominator is zero at 4.", "This point lies inside the interval.", "Continuity on the full closed interval fails."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-09", "module": 14, "family": 1, "topic": "Infinite limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 6^+}\\frac{4}{(x-6)^{1}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 4, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-09", "module": 15, "family": 1, "topic": "Asymptotes & multiplicity", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the vertical asymptote at x = 4.", "math": "f(x)=\\frac{6}{(x-4)^{3}}", "answer": "Odd", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 3.", "The asymptote has odd multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-09", "module": 16, "family": 1, "topic": "Rational limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{4 x + 6}{x^{2} + 1}", "answer": "0", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{4}{x}$.", "At the specified end, the limit is $0$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-17-09", "module": 17, "family": 1, "topic": "Radical limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{16 x^{2} + 6}}{x}", "answer": "-4", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $-4$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -4.0}, {"id": "U1-18-09", "module": 18, "family": 1, "topic": "Exponential end behavior", "subtopic": "Apply", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}4 + e^{- x}", "answer": "4", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 4."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-19-09", "module": 19, "family": 1, "topic": "Domain, holes & restrictions", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the hole at x = 4.", "math": "f(x)=\\frac{(x-4)(x+6)}{(x-4)(x+4)}", "answer": "\\frac{5}{4}", "type": "number", "solutionSteps": ["Cancel x − 4.", "Evaluate (x + 6)/(x + 4) at x = 4.", "The hole has height $\\frac{5}{4}$."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.25}, {"id": "U1-20-09", "module": 20, "family": 1, "topic": "Intercepts & curve sketching", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the y-intercept.", "math": "f(x)=\\frac{x - 4}{x + 6}", "answer": "- \\frac{2}{3}", "type": "number", "solutionSteps": ["Set x = 0.", "The numerator is −4 and denominator is 6.", "The y-intercept has height $- \\frac{2}{3}$."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -0.6666666666666666}, {"id": "U1-21-09", "module": 21, "family": 1, "topic": "Average rate of change", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the average rate of change on [3, 5].", "math": "f(x)=4 x^{3} - 6 x", "answer": "190", "type": "number", "solutionSteps": ["The endpoint outputs are 90 and 470.", "The input change is 2.", "Divide the output change by 2 to obtain $190$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 190.0}, {"id": "U1-22-09", "module": 22, "family": 1, "topic": "Estimating instantaneous rates", "subtopic": "Apply", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 6 using the secant on [5.99, 6.01].", "math": "f(x)=4 x^{2} + 6 x", "answer": "54", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{599}{100}$ and $\\frac{601}{100}$.", "The output change is $\\frac{27}{25}$ and the input change is $\\frac{1}{50}$.", "The secant estimate is $54$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 54.0}, {"id": "U1-23-09", "module": 23, "family": 1, "topic": "Squeeze Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}4x^{4}\\sin(1/x)+6", "answer": "6", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 6, both bounds approach 6.", "The Squeeze Theorem gives 6."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-24-09", "module": 24, "family": 1, "topic": "Combining limits", "subtopic": "Apply", "difficulty": "Medium", "question": "As x approaches 14, f(x) approaches 4 and g(x) approaches 6. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 14}f(x)g(x)", "answer": "24", "type": "number", "solutionSteps": ["Use the component limits 4 and 6.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $24$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 24.0}, {"id": "U1-25-09", "module": 25, "family": 1, "topic": "Limits of compositions", "subtopic": "Apply", "difficulty": "Medium", "question": "Let f(t) = 4 for t < 6, f(t) = 9 for t > 6, and f(6) = 99. If g(x) = 6 − x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "4", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) < 6.", "The inner output approaches the boundary from below.", "The outer left branch is always 4."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-01-10", "module": 1, "family": 1, "topic": "Understanding a limit", "subtopic": "Apply", "difficulty": "Medium", "question": "The left limit is 5 and the right limit is 7. Find the two-sided limit.", "math": "\\lim_{x\\to 8}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left side approaches 5.", "The right side approaches 7.", "The sides differ, so the two-sided limit does not exist."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "5", "7", "8"], "graph": null, "table": null}, {"id": "U1-02-10", "module": 2, "family": 1, "topic": "Reading limits from graphs", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the filled point to find f(2).", "math": "", "answer": "7", "type": "number", "solutionSteps": ["Locate x = 2.", "The closed point has height 7.", "f(2) = 7."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": {"type": "hole", "c": 2, "L": 4, "value": 7, "m": 1}, "table": null, "numericAnswer": 7.0}, {"id": "U1-03-10", "module": 3, "family": 1, "topic": "One-sided limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 7^+}\\frac{5|x-7|}{x-7}", "answer": "5", "type": "number", "solutionSteps": ["On this side, x − 7 is positive.", "Replace the absolute value with its argument.", "Cancel the nonzero factor nearby to get 5."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-04-10", "module": 4, "family": 1, "topic": "Direct substitution", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to -5}x^{2} - 5 x + 7", "answer": "57", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = -5.", "Simplify to $57$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 57.0}, {"id": "U1-05-10", "module": 5, "family": 1, "topic": "Rational & trigonometric limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 0}\\sin{\\left(x \\right)} + 5 \\cos{\\left(x \\right)}", "answer": "5", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $0$ for x.", "Use exact values and simplify to $5$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-06-10", "module": 6, "family": 1, "topic": "Piecewise limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the two-sided limit at x = 5.", "math": "f(x)=\\begin{cases}x^2+2&x<5\\\\8&x=5\\\\x+23&x>5\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 27.", "The right limit is 28.", "The two-sided limit is DNE; the isolated value 8 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "27", "28", "8"], "graph": null, "table": null}, {"id": "U1-07-10", "module": 7, "family": 1, "topic": "The continuity test", "subtopic": "Apply", "difficulty": "Medium", "question": "At x = 7, the left limit is 5, the right limit is 5, and f(7) is 7. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-10", "module": 8, "family": 1, "topic": "Classifying discontinuities", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the discontinuity at x = 5 for this function.", "math": "\\frac{1}{\\left(x - 5\\right)^{2}}", "answer": "Infinite", "type": "choice", "solutionSteps": ["The squared denominator approaches zero positively.", "The nearby behavior is unbounded.", "This is a infinite discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-10", "module": 9, "family": 1, "topic": "Factoring indeterminate limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 5}\\frac{x^{3} - 125}{x - 5}", "answer": "75", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 5 for nearby x.", "The reduced expression is $x^{2} + 5 x + 25$.", "Substitute x = 5 to obtain $75$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 75.0}, {"id": "U1-10-10", "module": 10, "family": 1, "topic": "Rationalizing limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 25}\\frac{x - 25}{\\sqrt{x} - 5}", "answer": "10", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $10$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-11-10", "module": 11, "family": 1, "topic": "Limits from numerical tables", "subtopic": "Apply", "difficulty": "Medium", "question": "Does this finite table prove the limit at x = 5 with absolute certainty?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Only finitely many values are shown.", "Unsampled values could behave differently.", "The table provides evidence, not a proof."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["4.900", "16.800"], ["4.990", "16.980"], ["4.999", "16.998"], ["5.001", "17.002"], ["5.010", "17.020"], ["5.100", "17.200"]]}}, {"id": "U1-12-10", "module": 12, "family": 1, "topic": "Making a function continuous", "subtopic": "Apply", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2&x<5\\\\x+K&x\\ge 5\\end{cases}", "answer": "20", "type": "number", "solutionSteps": ["The left limit is 25.", "The right limit and point value are 5 + K.", "Solve 5 + K = 25, giving K = 20."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 20.0}, {"id": "U1-13-10", "module": 13, "family": 1, "topic": "Intermediate Value Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "For f(x) = 1/(x − 5) on [4, 6], does IVT apply across the entire interval?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["The denominator is zero at 5.", "This point lies inside the interval.", "Continuity on the full closed interval fails."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-10", "module": 14, "family": 1, "topic": "Infinite limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 7^+}\\frac{5}{(x-7)^{1}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 5, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-10", "module": 15, "family": 1, "topic": "Asymptotes & multiplicity", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the vertical asymptote at x = 5.", "math": "f(x)=\\frac{7}{(x-5)^{3}}", "answer": "Odd", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 3.", "The asymptote has odd multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-10", "module": 16, "family": 1, "topic": "Rational limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{5 x + 7}{x^{2} + 1}", "answer": "0", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{5}{x}$.", "At the specified end, the limit is $0$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-17-10", "module": 17, "family": 1, "topic": "Radical limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{25 x^{2} + 7}}{x}", "answer": "-5", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $-5$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -5.0}, {"id": "U1-18-10", "module": 18, "family": 1, "topic": "Exponential end behavior", "subtopic": "Apply", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}5 + e^{- x}", "answer": "5", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 5."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-19-10", "module": 19, "family": 1, "topic": "Domain, holes & restrictions", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the hole at x = 5.", "math": "f(x)=\\frac{(x-5)(x+7)}{(x-5)(x+5)}", "answer": "\\frac{6}{5}", "type": "number", "solutionSteps": ["Cancel x − 5.", "Evaluate (x + 7)/(x + 5) at x = 5.", "The hole has height $\\frac{6}{5}$."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.2}, {"id": "U1-20-10", "module": 20, "family": 1, "topic": "Intercepts & curve sketching", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the y-intercept.", "math": "f(x)=\\frac{x - 5}{x + 7}", "answer": "- \\frac{5}{7}", "type": "number", "solutionSteps": ["Set x = 0.", "The numerator is −5 and denominator is 7.", "The y-intercept has height $- \\frac{5}{7}$."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -0.7142857142857143}, {"id": "U1-21-10", "module": 21, "family": 1, "topic": "Average rate of change", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the average rate of change on [4, 6].", "math": "f(x)=5 x^{3} - 7 x", "answer": "373", "type": "number", "solutionSteps": ["The endpoint outputs are 292 and 1038.", "The input change is 2.", "Divide the output change by 2 to obtain $373$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 373.0}, {"id": "U1-22-10", "module": 22, "family": 1, "topic": "Estimating instantaneous rates", "subtopic": "Apply", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 7 using the secant on [6.99, 7.01].", "math": "f(x)=5 x^{2} + 7 x", "answer": "77", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{699}{100}$ and $\\frac{701}{100}$.", "The output change is $\\frac{77}{50}$ and the input change is $\\frac{1}{50}$.", "The secant estimate is $77$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 77.0}, {"id": "U1-23-10", "module": 23, "family": 1, "topic": "Squeeze Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}5x^{4}\\sin(1/x)+7", "answer": "7", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 7, both bounds approach 7.", "The Squeeze Theorem gives 7."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-24-10", "module": 24, "family": 1, "topic": "Combining limits", "subtopic": "Apply", "difficulty": "Medium", "question": "As x approaches 17, f(x) approaches 5 and g(x) approaches 7. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 17}f(x)g(x)", "answer": "35", "type": "number", "solutionSteps": ["Use the component limits 5 and 7.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $35$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 35.0}, {"id": "U1-25-10", "module": 25, "family": 1, "topic": "Limits of compositions", "subtopic": "Apply", "difficulty": "Medium", "question": "Let f(t) = 5 for t < 7, f(t) = 10 for t > 7, and f(7) = 99. If g(x) = 7 − x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "5", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) < 7.", "The inner output approaches the boundary from below.", "The outer left branch is always 5."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-01-11", "module": 1, "family": 2, "topic": "Understanding a limit", "subtopic": "Connect", "difficulty": "Medium", "question": "Both sides approach 4 at x = 1, and f(1) is undefined. Select all true statements.", "math": "", "answer": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous"], "type": "multi", "solutionSteps": ["Both sides have the same finite limit.", "The undefined point prevents continuity.", "Set the missing value equal to the limit."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous", "The limit must be zero"], "graph": null, "table": null}, {"id": "U1-02-11", "module": 2, "family": 2, "topic": "Reading limits from graphs", "subtopic": "Connect", "difficulty": "Medium", "question": "Classify the discontinuity shown by the graph.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["The approached height is the same on both sides.", "The filled point has a different height.", "Changing that single point removes the discontinuity."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": ["Removable", "Jump", "Infinite", "Continuous"], "graph": {"type": "hole", "c": -2, "L": 0, "value": 3, "m": 1}, "table": null}, {"id": "U1-03-11", "module": 3, "family": 2, "topic": "One-sided limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<1\\\\x+3&x\\ge 1\\end{cases},\\quad\\lim_{x\\to 1^-}f(x)", "answer": "1", "type": "number", "solutionSteps": ["Use x² from the left.", "Substitute x = 1 into that branch.", "The one-sided limit is 1."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-04-11", "module": 4, "family": 2, "topic": "Direct substitution", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 0}\\sqrt{x + 1}", "answer": "1", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 0.", "Simplify to $1$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-05-11", "module": 5, "family": 2, "topic": "Rational & trigonometric limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to -1}\\frac{x^{2} + 1}{x + 3}", "answer": "1", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $-1$ for x.", "Use exact values and simplify to $1$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-06-11", "module": 6, "family": 2, "topic": "Piecewise limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the two-sided limit at x = 1.", "math": "f(x)=\\begin{cases}x^2+4&x<1\\\\5&x=1\\\\x+4&x>1\\end{cases}", "answer": "5", "type": "number", "solutionSteps": ["The left limit is 5.", "The right limit is 5.", "The two-sided limit is 5; the isolated value 5 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-07-11", "module": 7, "family": 2, "topic": "The continuity test", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 3, the left limit is 1, the right limit is 3, and f(3) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides disagree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-11", "module": 8, "family": 2, "topic": "Classifying discontinuities", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 1, the one-sided limits are 3 and 4, but f(1) = 7. Classify the discontinuity.", "math": "", "answer": "Jump", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They differ.", "This is a jump discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-11", "module": 9, "family": 2, "topic": "Factoring indeterminate limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 1}\\frac{x^{2} + 2 x - 3}{x - 1}", "answer": "4", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 1 for nearby x.", "The reduced expression is $x + 3$.", "Substitute x = 1 to obtain $4$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-10-11", "module": 10, "family": 2, "topic": "Rationalizing limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{x + 1} - 1}{x}", "answer": "\\frac{1}{2}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{2}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.5}, {"id": "U1-11-11", "module": 11, "family": 2, "topic": "Limits from numerical tables", "subtopic": "Connect", "difficulty": "Medium", "question": "Treating the displayed trends as representative, estimate the two-sided limit at 1.", "math": "", "answer": "DNE", "type": "choice", "solutionSteps": ["The left trend approaches 1.", "The right trend approaches 3.", "Unequal trends suggest DNE."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["DNE", "1", "3"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["0.900", "0.900"], ["0.990", "0.990"], ["0.999", "0.999"], ["1.001", "3.001"], ["1.010", "3.010"], ["1.100", "3.100"]]}}, {"id": "U1-12-11", "module": 12, "family": 2, "topic": "Making a function continuous", "subtopic": "Connect", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}Kx&x<1\\\\x^2+3&x\\ge 1\\end{cases}", "answer": "4", "type": "number", "solutionSteps": ["The left limit is 1K.", "The right limit is 4.", "Equating them gives K = $4$."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-13-11", "module": 13, "family": 2, "topic": "Intermediate Value Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "For f(x) = x² + 3 on [0, 2], find c with f(c) = 4.", "math": "", "answer": "1", "type": "number", "solutionSteps": ["The target lies between 3 and 7.", "Solve c² = 1.", "Only c = 1 lies in this interval."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-14-11", "module": 14, "family": 2, "topic": "Infinite limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 3^-}\\frac{1}{(x-3)^{2}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 1, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-11", "module": 15, "family": 2, "topic": "Asymptotes & multiplicity", "subtopic": "Connect", "difficulty": "Medium", "question": "After reduction, classify the asymptote at x = 1.", "math": "f(x)=\\frac{x-1}{(x-1)^{3}}", "answer": "Even", "type": "choice", "solutionSteps": ["Cancel one factor x − 1.", "The denominator power becomes 2.", "The remaining asymptote is even."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-11", "module": 16, "family": 2, "topic": "Rational limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to -\\infty}\\frac{x^{3} + 3}{3 x^{2} + 1}", "answer": "-infinity", "type": "choice", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{x}{3}$.", "At the specified end, the limit is $-\\infty$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-17-11", "module": 17, "family": 2, "topic": "Radical limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{x^{2} + 3}}{3 x}", "answer": "\\frac{1}{3}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $\\frac{1}{3}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.3333333333333333}, {"id": "U1-18-11", "module": 18, "family": 2, "topic": "Exponential end behavior", "subtopic": "Connect", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}\\frac{x^{2} + 3}{x^{2} + e^{x}}", "answer": "0", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "An exponential in the denominator dominates polynomial growth.", "The remaining expression approaches 0."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-19-11", "module": 19, "family": 2, "topic": "Domain, holes & restrictions", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the x-coordinate of the vertical asymptote.", "math": "f(x)=\\frac{(x-1)(x+3)}{(x-1)(x+1)}", "answer": "-1", "type": "number", "solutionSteps": ["Cancel x − 1.", "The remaining denominator x + 1 vanishes at −1.", "The remaining numerator is nonzero there."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -1.0}, {"id": "U1-20-11", "module": 20, "family": 2, "topic": "Intercepts & curve sketching", "subtopic": "Connect", "difficulty": "Medium", "question": "Does this graph cross or touch the x-axis at x = 1?", "math": "f(x)=\\left(x - 1\\right)^{2} \\left(x + 3\\right)", "answer": "Touches", "type": "choice", "solutionSteps": ["The factor x − 1 has multiplicity 2.", "The other factor is nonzero at this root.", "Even multiplicity preserves sign, so the graph touches."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-11", "module": 21, "family": 2, "topic": "Average rate of change", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the average rate of change on [0, 2] in km/h.", "math": "", "answer": "1", "type": "number", "solutionSteps": ["The endpoint outputs are 3 and 5.", "The input change is 2.", "Divide the output change by 2 to obtain $1$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": {"headers": ["Time (h)", "Distance (km)"], "rows": [["0", "3"], ["2", "5"]]}, "numericAnswer": 1.0}, {"id": "U1-22-11", "module": 22, "family": 2, "topic": "Estimating instantaneous rates", "subtopic": "Connect", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 3 using the secant on [2.5, 3.5].", "math": "f(x)=x^{3}", "answer": "\\frac{109}{4}", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{5}{2}$ and $\\frac{7}{2}$.", "The output change is $\\frac{109}{4}$ and the input change is $1$.", "The secant estimate is $\\frac{109}{4}$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 27.25}, {"id": "U1-23-11", "module": 23, "family": 2, "topic": "Squeeze Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "Near x = 1, p(x) ≤ g(x) ≤ q(x), and both bounding limits are 5. Find the limit of g.", "math": "", "answer": "5", "type": "number", "solutionSteps": ["The required nearby inequality is given.", "Both bounds approach 5.", "Therefore g also approaches 5."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-24-11", "module": 24, "family": 2, "topic": "Combining limits", "subtopic": "Connect", "difficulty": "Medium", "question": "As x approaches 5, f(x) approaches 1 and g(x) approaches 3. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 5}\\frac{f(x)^2}{g(x)}", "answer": "\\frac{1}{3}", "type": "number", "solutionSteps": ["Use the component limits 1 and 3.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $\\frac{1}{3}$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.3333333333333333}, {"id": "U1-25-11", "module": 25, "family": 2, "topic": "Limits of compositions", "subtopic": "Connect", "difficulty": "Medium", "question": "Let f(t) = 1 for t < 3, f(t) = 6 for t > 3, and f(3) = 99. If g(x) = 3 + x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "6", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) > 3.", "The inner output approaches the boundary from above.", "The outer right branch is always 6."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-01-12", "module": 1, "family": 2, "topic": "Understanding a limit", "subtopic": "Connect", "difficulty": "Medium", "question": "Both sides approach 5 at x = 2, and f(2) is undefined. Select all true statements.", "math": "", "answer": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous"], "type": "multi", "solutionSteps": ["Both sides have the same finite limit.", "The undefined point prevents continuity.", "Set the missing value equal to the limit."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous", "The limit must be zero"], "graph": null, "table": null}, {"id": "U1-02-12", "module": 2, "family": 2, "topic": "Reading limits from graphs", "subtopic": "Connect", "difficulty": "Medium", "question": "Classify the discontinuity shown by the graph.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["The approached height is the same on both sides.", "The filled point has a different height.", "Changing that single point removes the discontinuity."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": ["Removable", "Jump", "Infinite", "Continuous"], "graph": {"type": "hole", "c": -1, "L": 1, "value": 4, "m": 1}, "table": null}, {"id": "U1-03-12", "module": 3, "family": 2, "topic": "One-sided limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<2\\\\x+4&x\\ge 2\\end{cases},\\quad\\lim_{x\\to 2^-}f(x)", "answer": "4", "type": "number", "solutionSteps": ["Use x² from the left.", "Substitute x = 2 into that branch.", "The one-sided limit is 4."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-04-12", "module": 4, "family": 2, "topic": "Direct substitution", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 0}\\sqrt{x + 4}", "answer": "2", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 0.", "Simplify to $2$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-05-12", "module": 5, "family": 2, "topic": "Rational & trigonometric limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to -2}\\frac{x^{2} + 2}{x + 4}", "answer": "3", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $-2$ for x.", "Use exact values and simplify to $3$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-06-12", "module": 6, "family": 2, "topic": "Piecewise limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the two-sided limit at x = 2.", "math": "f(x)=\\begin{cases}x^2+4&x<2\\\\6&x=2\\\\x+6&x>2\\end{cases}", "answer": "8", "type": "number", "solutionSteps": ["The left limit is 8.", "The right limit is 8.", "The two-sided limit is 8; the isolated value 6 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-07-12", "module": 7, "family": 2, "topic": "The continuity test", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 4, the left limit is 2, the right limit is 4, and f(4) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides disagree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-12", "module": 8, "family": 2, "topic": "Classifying discontinuities", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 2, the one-sided limits are 4 and 5, but f(2) = 8. Classify the discontinuity.", "math": "", "answer": "Jump", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They differ.", "This is a jump discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-12", "module": 9, "family": 2, "topic": "Factoring indeterminate limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 2}\\frac{x^{2} + 2 x - 8}{x - 2}", "answer": "6", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 2 for nearby x.", "The reduced expression is $x + 4$.", "Substitute x = 2 to obtain $6$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-10-12", "module": 10, "family": 2, "topic": "Rationalizing limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{x + 4} - 2}{x}", "answer": "\\frac{1}{4}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{4}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.25}, {"id": "U1-11-12", "module": 11, "family": 2, "topic": "Limits from numerical tables", "subtopic": "Connect", "difficulty": "Medium", "question": "Treating the displayed trends as representative, estimate the two-sided limit at 2.", "math": "", "answer": "DNE", "type": "choice", "solutionSteps": ["The left trend approaches 2.", "The right trend approaches 4.", "Unequal trends suggest DNE."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["DNE", "2", "4"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["1.900", "1.900"], ["1.990", "1.990"], ["1.999", "1.999"], ["2.001", "4.001"], ["2.010", "4.010"], ["2.100", "4.100"]]}}, {"id": "U1-12-12", "module": 12, "family": 2, "topic": "Making a function continuous", "subtopic": "Connect", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}Kx&x<2\\\\x^2+4&x\\ge 2\\end{cases}", "answer": "4", "type": "number", "solutionSteps": ["The left limit is 2K.", "The right limit is 8.", "Equating them gives K = $4$."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-13-12", "module": 13, "family": 2, "topic": "Intermediate Value Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "For f(x) = x² + 4 on [0, 3], find c with f(c) = 8.", "math": "", "answer": "2", "type": "number", "solutionSteps": ["The target lies between 4 and 13.", "Solve c² = 4.", "Only c = 2 lies in this interval."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-14-12", "module": 14, "family": 2, "topic": "Infinite limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 4^-}\\frac{2}{(x-4)^{2}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 2, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-12", "module": 15, "family": 2, "topic": "Asymptotes & multiplicity", "subtopic": "Connect", "difficulty": "Medium", "question": "After reduction, classify the asymptote at x = 2.", "math": "f(x)=\\frac{x-2}{(x-2)^{3}}", "answer": "Even", "type": "choice", "solutionSteps": ["Cancel one factor x − 2.", "The denominator power becomes 2.", "The remaining asymptote is even."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-12", "module": 16, "family": 2, "topic": "Rational limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to -\\infty}\\frac{2 x^{3} + 4}{4 x^{2} + 1}", "answer": "-infinity", "type": "choice", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{x}{2}$.", "At the specified end, the limit is $-\\infty$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-17-12", "module": 17, "family": 2, "topic": "Radical limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{4 x^{2} + 4}}{4 x}", "answer": "\\frac{1}{2}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $\\frac{1}{2}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.5}, {"id": "U1-18-12", "module": 18, "family": 2, "topic": "Exponential end behavior", "subtopic": "Connect", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}\\frac{2 x^{2} + 4}{x^{2} + e^{x}}", "answer": "0", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "An exponential in the denominator dominates polynomial growth.", "The remaining expression approaches 0."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-19-12", "module": 19, "family": 2, "topic": "Domain, holes & restrictions", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the x-coordinate of the vertical asymptote.", "math": "f(x)=\\frac{(x-2)(x+4)}{(x-2)(x+2)}", "answer": "-2", "type": "number", "solutionSteps": ["Cancel x − 2.", "The remaining denominator x + 2 vanishes at −2.", "The remaining numerator is nonzero there."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -2.0}, {"id": "U1-20-12", "module": 20, "family": 2, "topic": "Intercepts & curve sketching", "subtopic": "Connect", "difficulty": "Medium", "question": "Does this graph cross or touch the x-axis at x = 2?", "math": "f(x)=\\left(x - 2\\right)^{2} \\left(x + 4\\right)", "answer": "Touches", "type": "choice", "solutionSteps": ["The factor x − 2 has multiplicity 2.", "The other factor is nonzero at this root.", "Even multiplicity preserves sign, so the graph touches."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-12", "module": 21, "family": 2, "topic": "Average rate of change", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the average rate of change on [1, 3] in km/h.", "math": "", "answer": "2", "type": "number", "solutionSteps": ["The endpoint outputs are 6 and 10.", "The input change is 2.", "Divide the output change by 2 to obtain $2$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": {"headers": ["Time (h)", "Distance (km)"], "rows": [["1", "6"], ["3", "10"]]}, "numericAnswer": 2.0}, {"id": "U1-22-12", "module": 22, "family": 2, "topic": "Estimating instantaneous rates", "subtopic": "Connect", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 4 using the secant on [3.5, 4.5].", "math": "f(x)=2 x^{3}", "answer": "\\frac{193}{2}", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{7}{2}$ and $\\frac{9}{2}$.", "The output change is $\\frac{193}{2}$ and the input change is $1$.", "The secant estimate is $\\frac{193}{2}$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 96.5}, {"id": "U1-23-12", "module": 23, "family": 2, "topic": "Squeeze Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "Near x = 2, p(x) ≤ g(x) ≤ q(x), and both bounding limits are 8. Find the limit of g.", "math": "", "answer": "8", "type": "number", "solutionSteps": ["The required nearby inequality is given.", "Both bounds approach 8.", "Therefore g also approaches 8."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-24-12", "module": 24, "family": 2, "topic": "Combining limits", "subtopic": "Connect", "difficulty": "Medium", "question": "As x approaches 8, f(x) approaches 2 and g(x) approaches 4. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 8}\\frac{f(x)^2}{g(x)}", "answer": "1", "type": "number", "solutionSteps": ["Use the component limits 2 and 4.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $1$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-25-12", "module": 25, "family": 2, "topic": "Limits of compositions", "subtopic": "Connect", "difficulty": "Medium", "question": "Let f(t) = 2 for t < 4, f(t) = 7 for t > 4, and f(4) = 99. If g(x) = 4 + x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "7", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) > 4.", "The inner output approaches the boundary from above.", "The outer right branch is always 7."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-01-13", "module": 1, "family": 2, "topic": "Understanding a limit", "subtopic": "Connect", "difficulty": "Medium", "question": "Both sides approach 6 at x = 3, and f(3) is undefined. Select all true statements.", "math": "", "answer": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous"], "type": "multi", "solutionSteps": ["Both sides have the same finite limit.", "The undefined point prevents continuity.", "Set the missing value equal to the limit."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous", "The limit must be zero"], "graph": null, "table": null}, {"id": "U1-02-13", "module": 2, "family": 2, "topic": "Reading limits from graphs", "subtopic": "Connect", "difficulty": "Medium", "question": "Classify the discontinuity shown by the graph.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["The approached height is the same on both sides.", "The filled point has a different height.", "Changing that single point removes the discontinuity."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": ["Removable", "Jump", "Infinite", "Continuous"], "graph": {"type": "hole", "c": 0, "L": 2, "value": 5, "m": 1}, "table": null}, {"id": "U1-03-13", "module": 3, "family": 2, "topic": "One-sided limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<3\\\\x+5&x\\ge 3\\end{cases},\\quad\\lim_{x\\to 3^-}f(x)", "answer": "9", "type": "number", "solutionSteps": ["Use x² from the left.", "Substitute x = 3 into that branch.", "The one-sided limit is 9."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-04-13", "module": 4, "family": 2, "topic": "Direct substitution", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 0}\\sqrt{x + 9}", "answer": "3", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 0.", "Simplify to $3$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-05-13", "module": 5, "family": 2, "topic": "Rational & trigonometric limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to -3}\\frac{x^{2} + 3}{x + 5}", "answer": "6", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $-3$ for x.", "Use exact values and simplify to $6$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-06-13", "module": 6, "family": 2, "topic": "Piecewise limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the two-sided limit at x = 3.", "math": "f(x)=\\begin{cases}x^2+4&x<3\\\\7&x=3\\\\x+10&x>3\\end{cases}", "answer": "13", "type": "number", "solutionSteps": ["The left limit is 13.", "The right limit is 13.", "The two-sided limit is 13; the isolated value 7 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 13.0}, {"id": "U1-07-13", "module": 7, "family": 2, "topic": "The continuity test", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 5, the left limit is 3, the right limit is 5, and f(5) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides disagree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-13", "module": 8, "family": 2, "topic": "Classifying discontinuities", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 3, the one-sided limits are 5 and 6, but f(3) = 9. Classify the discontinuity.", "math": "", "answer": "Jump", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They differ.", "This is a jump discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-13", "module": 9, "family": 2, "topic": "Factoring indeterminate limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 3}\\frac{x^{2} + 2 x - 15}{x - 3}", "answer": "8", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 3 for nearby x.", "The reduced expression is $x + 5$.", "Substitute x = 3 to obtain $8$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-10-13", "module": 10, "family": 2, "topic": "Rationalizing limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{x + 9} - 3}{x}", "answer": "\\frac{1}{6}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{6}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.16666666666666666}, {"id": "U1-11-13", "module": 11, "family": 2, "topic": "Limits from numerical tables", "subtopic": "Connect", "difficulty": "Medium", "question": "Treating the displayed trends as representative, estimate the two-sided limit at 3.", "math": "", "answer": "DNE", "type": "choice", "solutionSteps": ["The left trend approaches 3.", "The right trend approaches 5.", "Unequal trends suggest DNE."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["DNE", "3", "5"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["2.900", "2.900"], ["2.990", "2.990"], ["2.999", "2.999"], ["3.001", "5.001"], ["3.010", "5.010"], ["3.100", "5.100"]]}}, {"id": "U1-12-13", "module": 12, "family": 2, "topic": "Making a function continuous", "subtopic": "Connect", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}Kx&x<3\\\\x^2+5&x\\ge 3\\end{cases}", "answer": "\\frac{14}{3}", "type": "number", "solutionSteps": ["The left limit is 3K.", "The right limit is 14.", "Equating them gives K = $\\frac{14}{3}$."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.666666666666667}, {"id": "U1-13-13", "module": 13, "family": 2, "topic": "Intermediate Value Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "For f(x) = x² + 5 on [0, 4], find c with f(c) = 14.", "math": "", "answer": "3", "type": "number", "solutionSteps": ["The target lies between 5 and 21.", "Solve c² = 9.", "Only c = 3 lies in this interval."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-14-13", "module": 14, "family": 2, "topic": "Infinite limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 5^-}\\frac{3}{(x-5)^{2}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 3, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-13", "module": 15, "family": 2, "topic": "Asymptotes & multiplicity", "subtopic": "Connect", "difficulty": "Medium", "question": "After reduction, classify the asymptote at x = 3.", "math": "f(x)=\\frac{x-3}{(x-3)^{3}}", "answer": "Even", "type": "choice", "solutionSteps": ["Cancel one factor x − 3.", "The denominator power becomes 2.", "The remaining asymptote is even."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-13", "module": 16, "family": 2, "topic": "Rational limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to -\\infty}\\frac{3 x^{3} + 5}{5 x^{2} + 1}", "answer": "-infinity", "type": "choice", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{3 x}{5}$.", "At the specified end, the limit is $-\\infty$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-17-13", "module": 17, "family": 2, "topic": "Radical limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{9 x^{2} + 5}}{5 x}", "answer": "\\frac{3}{5}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $\\frac{3}{5}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.6}, {"id": "U1-18-13", "module": 18, "family": 2, "topic": "Exponential end behavior", "subtopic": "Connect", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}\\frac{3 x^{2} + 5}{x^{2} + e^{x}}", "answer": "0", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "An exponential in the denominator dominates polynomial growth.", "The remaining expression approaches 0."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-19-13", "module": 19, "family": 2, "topic": "Domain, holes & restrictions", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the x-coordinate of the vertical asymptote.", "math": "f(x)=\\frac{(x-3)(x+5)}{(x-3)(x+3)}", "answer": "-3", "type": "number", "solutionSteps": ["Cancel x − 3.", "The remaining denominator x + 3 vanishes at −3.", "The remaining numerator is nonzero there."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -3.0}, {"id": "U1-20-13", "module": 20, "family": 2, "topic": "Intercepts & curve sketching", "subtopic": "Connect", "difficulty": "Medium", "question": "Does this graph cross or touch the x-axis at x = 3?", "math": "f(x)=\\left(x - 3\\right)^{2} \\left(x + 5\\right)", "answer": "Touches", "type": "choice", "solutionSteps": ["The factor x − 3 has multiplicity 2.", "The other factor is nonzero at this root.", "Even multiplicity preserves sign, so the graph touches."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-13", "module": 21, "family": 2, "topic": "Average rate of change", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the average rate of change on [2, 4] in km/h.", "math": "", "answer": "3", "type": "number", "solutionSteps": ["The endpoint outputs are 11 and 17.", "The input change is 2.", "Divide the output change by 2 to obtain $3$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": {"headers": ["Time (h)", "Distance (km)"], "rows": [["2", "11"], ["4", "17"]]}, "numericAnswer": 3.0}, {"id": "U1-22-13", "module": 22, "family": 2, "topic": "Estimating instantaneous rates", "subtopic": "Connect", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 5 using the secant on [4.5, 5.5].", "math": "f(x)=3 x^{3}", "answer": "\\frac{903}{4}", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{9}{2}$ and $\\frac{11}{2}$.", "The output change is $\\frac{903}{4}$ and the input change is $1$.", "The secant estimate is $\\frac{903}{4}$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 225.75}, {"id": "U1-23-13", "module": 23, "family": 2, "topic": "Squeeze Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "Near x = 3, p(x) ≤ g(x) ≤ q(x), and both bounding limits are 11. Find the limit of g.", "math": "", "answer": "11", "type": "number", "solutionSteps": ["The required nearby inequality is given.", "Both bounds approach 11.", "Therefore g also approaches 11."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 11.0}, {"id": "U1-24-13", "module": 24, "family": 2, "topic": "Combining limits", "subtopic": "Connect", "difficulty": "Medium", "question": "As x approaches 11, f(x) approaches 3 and g(x) approaches 5. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 11}\\frac{f(x)^2}{g(x)}", "answer": "\\frac{9}{5}", "type": "number", "solutionSteps": ["Use the component limits 3 and 5.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $\\frac{9}{5}$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.8}, {"id": "U1-25-13", "module": 25, "family": 2, "topic": "Limits of compositions", "subtopic": "Connect", "difficulty": "Medium", "question": "Let f(t) = 3 for t < 5, f(t) = 8 for t > 5, and f(5) = 99. If g(x) = 5 + x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "8", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) > 5.", "The inner output approaches the boundary from above.", "The outer right branch is always 8."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-01-14", "module": 1, "family": 2, "topic": "Understanding a limit", "subtopic": "Connect", "difficulty": "Medium", "question": "Both sides approach 7 at x = 4, and f(4) is undefined. Select all true statements.", "math": "", "answer": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous"], "type": "multi", "solutionSteps": ["Both sides have the same finite limit.", "The undefined point prevents continuity.", "Set the missing value equal to the limit."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous", "The limit must be zero"], "graph": null, "table": null}, {"id": "U1-02-14", "module": 2, "family": 2, "topic": "Reading limits from graphs", "subtopic": "Connect", "difficulty": "Medium", "question": "Classify the discontinuity shown by the graph.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["The approached height is the same on both sides.", "The filled point has a different height.", "Changing that single point removes the discontinuity."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": ["Removable", "Jump", "Infinite", "Continuous"], "graph": {"type": "hole", "c": 1, "L": 3, "value": 6, "m": 1}, "table": null}, {"id": "U1-03-14", "module": 3, "family": 2, "topic": "One-sided limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<4\\\\x+6&x\\ge 4\\end{cases},\\quad\\lim_{x\\to 4^-}f(x)", "answer": "16", "type": "number", "solutionSteps": ["Use x² from the left.", "Substitute x = 4 into that branch.", "The one-sided limit is 16."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 16.0}, {"id": "U1-04-14", "module": 4, "family": 2, "topic": "Direct substitution", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 0}\\sqrt{x + 16}", "answer": "4", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 0.", "Simplify to $4$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-05-14", "module": 5, "family": 2, "topic": "Rational & trigonometric limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to -4}\\frac{x^{2} + 4}{x + 6}", "answer": "10", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $-4$ for x.", "Use exact values and simplify to $10$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-06-14", "module": 6, "family": 2, "topic": "Piecewise limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the two-sided limit at x = 4.", "math": "f(x)=\\begin{cases}x^2+4&x<4\\\\8&x=4\\\\x+16&x>4\\end{cases}", "answer": "20", "type": "number", "solutionSteps": ["The left limit is 20.", "The right limit is 20.", "The two-sided limit is 20; the isolated value 8 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 20.0}, {"id": "U1-07-14", "module": 7, "family": 2, "topic": "The continuity test", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 6, the left limit is 4, the right limit is 6, and f(6) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides disagree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-14", "module": 8, "family": 2, "topic": "Classifying discontinuities", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 4, the one-sided limits are 6 and 7, but f(4) = 10. Classify the discontinuity.", "math": "", "answer": "Jump", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They differ.", "This is a jump discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-14", "module": 9, "family": 2, "topic": "Factoring indeterminate limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 4}\\frac{x^{2} + 2 x - 24}{x - 4}", "answer": "10", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 4 for nearby x.", "The reduced expression is $x + 6$.", "Substitute x = 4 to obtain $10$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-10-14", "module": 10, "family": 2, "topic": "Rationalizing limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{x + 16} - 4}{x}", "answer": "\\frac{1}{8}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{8}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.125}, {"id": "U1-11-14", "module": 11, "family": 2, "topic": "Limits from numerical tables", "subtopic": "Connect", "difficulty": "Medium", "question": "Treating the displayed trends as representative, estimate the two-sided limit at 4.", "math": "", "answer": "DNE", "type": "choice", "solutionSteps": ["The left trend approaches 4.", "The right trend approaches 6.", "Unequal trends suggest DNE."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["DNE", "4", "6"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["3.900", "3.900"], ["3.990", "3.990"], ["3.999", "3.999"], ["4.001", "6.001"], ["4.010", "6.010"], ["4.100", "6.100"]]}}, {"id": "U1-12-14", "module": 12, "family": 2, "topic": "Making a function continuous", "subtopic": "Connect", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}Kx&x<4\\\\x^2+6&x\\ge 4\\end{cases}", "answer": "\\frac{11}{2}", "type": "number", "solutionSteps": ["The left limit is 4K.", "The right limit is 22.", "Equating them gives K = $\\frac{11}{2}$."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 5.5}, {"id": "U1-13-14", "module": 13, "family": 2, "topic": "Intermediate Value Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "For f(x) = x² + 6 on [0, 5], find c with f(c) = 22.", "math": "", "answer": "4", "type": "number", "solutionSteps": ["The target lies between 6 and 31.", "Solve c² = 16.", "Only c = 4 lies in this interval."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-14-14", "module": 14, "family": 2, "topic": "Infinite limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 6^-}\\frac{4}{(x-6)^{2}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 4, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-14", "module": 15, "family": 2, "topic": "Asymptotes & multiplicity", "subtopic": "Connect", "difficulty": "Medium", "question": "After reduction, classify the asymptote at x = 4.", "math": "f(x)=\\frac{x-4}{(x-4)^{3}}", "answer": "Even", "type": "choice", "solutionSteps": ["Cancel one factor x − 4.", "The denominator power becomes 2.", "The remaining asymptote is even."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-14", "module": 16, "family": 2, "topic": "Rational limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to -\\infty}\\frac{4 x^{3} + 6}{6 x^{2} + 1}", "answer": "-infinity", "type": "choice", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{2 x}{3}$.", "At the specified end, the limit is $-\\infty$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-17-14", "module": 17, "family": 2, "topic": "Radical limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{16 x^{2} + 6}}{6 x}", "answer": "\\frac{2}{3}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $\\frac{2}{3}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.6666666666666666}, {"id": "U1-18-14", "module": 18, "family": 2, "topic": "Exponential end behavior", "subtopic": "Connect", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}\\frac{4 x^{2} + 6}{x^{2} + e^{x}}", "answer": "0", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "An exponential in the denominator dominates polynomial growth.", "The remaining expression approaches 0."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-19-14", "module": 19, "family": 2, "topic": "Domain, holes & restrictions", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the x-coordinate of the vertical asymptote.", "math": "f(x)=\\frac{(x-4)(x+6)}{(x-4)(x+4)}", "answer": "-4", "type": "number", "solutionSteps": ["Cancel x − 4.", "The remaining denominator x + 4 vanishes at −4.", "The remaining numerator is nonzero there."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -4.0}, {"id": "U1-20-14", "module": 20, "family": 2, "topic": "Intercepts & curve sketching", "subtopic": "Connect", "difficulty": "Medium", "question": "Does this graph cross or touch the x-axis at x = 4?", "math": "f(x)=\\left(x - 4\\right)^{2} \\left(x + 6\\right)", "answer": "Touches", "type": "choice", "solutionSteps": ["The factor x − 4 has multiplicity 2.", "The other factor is nonzero at this root.", "Even multiplicity preserves sign, so the graph touches."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-14", "module": 21, "family": 2, "topic": "Average rate of change", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the average rate of change on [3, 5] in km/h.", "math": "", "answer": "4", "type": "number", "solutionSteps": ["The endpoint outputs are 18 and 26.", "The input change is 2.", "Divide the output change by 2 to obtain $4$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": {"headers": ["Time (h)", "Distance (km)"], "rows": [["3", "18"], ["5", "26"]]}, "numericAnswer": 4.0}, {"id": "U1-22-14", "module": 22, "family": 2, "topic": "Estimating instantaneous rates", "subtopic": "Connect", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 6 using the secant on [5.5, 6.5].", "math": "f(x)=4 x^{3}", "answer": "433", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{11}{2}$ and $\\frac{13}{2}$.", "The output change is $433$ and the input change is $1$.", "The secant estimate is $433$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 433.0}, {"id": "U1-23-14", "module": 23, "family": 2, "topic": "Squeeze Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "Near x = 4, p(x) ≤ g(x) ≤ q(x), and both bounding limits are 14. Find the limit of g.", "math": "", "answer": "14", "type": "number", "solutionSteps": ["The required nearby inequality is given.", "Both bounds approach 14.", "Therefore g also approaches 14."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 14.0}, {"id": "U1-24-14", "module": 24, "family": 2, "topic": "Combining limits", "subtopic": "Connect", "difficulty": "Medium", "question": "As x approaches 14, f(x) approaches 4 and g(x) approaches 6. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 14}\\frac{f(x)^2}{g(x)}", "answer": "\\frac{8}{3}", "type": "number", "solutionSteps": ["Use the component limits 4 and 6.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $\\frac{8}{3}$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 2.6666666666666665}, {"id": "U1-25-14", "module": 25, "family": 2, "topic": "Limits of compositions", "subtopic": "Connect", "difficulty": "Medium", "question": "Let f(t) = 4 for t < 6, f(t) = 9 for t > 6, and f(6) = 99. If g(x) = 6 + x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "9", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) > 6.", "The inner output approaches the boundary from above.", "The outer right branch is always 9."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-01-15", "module": 1, "family": 2, "topic": "Understanding a limit", "subtopic": "Connect", "difficulty": "Hard", "question": "Both sides approach 8 at x = 5, and f(5) is undefined. Select all true statements.", "math": "", "answer": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous"], "type": "multi", "solutionSteps": ["Both sides have the same finite limit.", "The undefined point prevents continuity.", "Set the missing value equal to the limit."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Hard"], "options": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous", "The limit must be zero"], "graph": null, "table": null}, {"id": "U1-02-15", "module": 2, "family": 2, "topic": "Reading limits from graphs", "subtopic": "Connect", "difficulty": "Hard", "question": "Classify the discontinuity shown by the graph.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["The approached height is the same on both sides.", "The filled point has a different height.", "Changing that single point removes the discontinuity."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Hard"], "options": ["Removable", "Jump", "Infinite", "Continuous"], "graph": {"type": "hole", "c": 2, "L": 4, "value": 7, "m": 1}, "table": null}, {"id": "U1-03-15", "module": 3, "family": 2, "topic": "One-sided limits", "subtopic": "Connect", "difficulty": "Hard", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<5\\\\x+7&x\\ge 5\\end{cases},\\quad\\lim_{x\\to 5^-}f(x)", "answer": "25", "type": "number", "solutionSteps": ["Use x² from the left.", "Substitute x = 5 into that branch.", "The one-sided limit is 25."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 25.0}, {"id": "U1-04-15", "module": 4, "family": 2, "topic": "Direct substitution", "subtopic": "Connect", "difficulty": "Hard", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 0}\\sqrt{x + 25}", "answer": "5", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 0.", "Simplify to $5$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-05-15", "module": 5, "family": 2, "topic": "Rational & trigonometric limits", "subtopic": "Connect", "difficulty": "Hard", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to -5}\\frac{x^{2} + 5}{x + 7}", "answer": "15", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $-5$ for x.", "Use exact values and simplify to $15$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 15.0}, {"id": "U1-06-15", "module": 6, "family": 2, "topic": "Piecewise limits", "subtopic": "Connect", "difficulty": "Hard", "question": "Find the two-sided limit at x = 5.", "math": "f(x)=\\begin{cases}x^2+4&x<5\\\\9&x=5\\\\x+24&x>5\\end{cases}", "answer": "29", "type": "number", "solutionSteps": ["The left limit is 29.", "The right limit is 29.", "The two-sided limit is 29; the isolated value 9 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 29.0}, {"id": "U1-07-15", "module": 7, "family": 2, "topic": "The continuity test", "subtopic": "Connect", "difficulty": "Hard", "question": "At x = 7, the left limit is 5, the right limit is 7, and f(7) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides disagree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-15", "module": 8, "family": 2, "topic": "Classifying discontinuities", "subtopic": "Connect", "difficulty": "Hard", "question": "At x = 5, the one-sided limits are 7 and 8, but f(5) = 11. Classify the discontinuity.", "math": "", "answer": "Jump", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They differ.", "This is a jump discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-15", "module": 9, "family": 2, "topic": "Factoring indeterminate limits", "subtopic": "Connect", "difficulty": "Hard", "question": "Factor and reduce this expression for inputs in its original domain. Enter the reduced expression in x.", "math": "\\frac{x^2-1}{x^2+2x-3}", "answer": "\\frac{x+1}{x+3}", "type": "expression", "solutionSteps": ["Factor the numerator as (x − 1)(x + 1).", "Factor the denominator as (x − 1)(x + 3).", "Cancel x − 1 only on the original domain, x ≠ 1, −3.", "The reduced rule is (x + 1)/(x + 3)."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "expectedExpression": "(x+1)/(x+3)"}, {"id": "U1-10-15", "module": 10, "family": 2, "topic": "Rationalizing limits", "subtopic": "Connect", "difficulty": "Hard", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{x + 25} - 5}{x}", "answer": "\\frac{1}{10}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{10}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.1}, {"id": "U1-11-15", "module": 11, "family": 2, "topic": "Limits from numerical tables", "subtopic": "Connect", "difficulty": "Hard", "question": "Treating the displayed trends as representative, estimate the two-sided limit at 5.", "math": "", "answer": "DNE", "type": "choice", "solutionSteps": ["The left trend approaches 5.", "The right trend approaches 7.", "Unequal trends suggest DNE."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["DNE", "5", "7"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["4.900", "4.900"], ["4.990", "4.990"], ["4.999", "4.999"], ["5.001", "7.001"], ["5.010", "7.010"], ["5.100", "7.100"]]}}, {"id": "U1-12-15", "module": 12, "family": 2, "topic": "Making a function continuous", "subtopic": "Connect", "difficulty": "Hard", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}Kx&x<5\\\\x^2+7&x\\ge 5\\end{cases}", "answer": "\\frac{32}{5}", "type": "number", "solutionSteps": ["The left limit is 5K.", "The right limit is 32.", "Equating them gives K = $\\frac{32}{5}$."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 6.4}, {"id": "U1-13-15", "module": 13, "family": 2, "topic": "Intermediate Value Theorem", "subtopic": "Connect", "difficulty": "Hard", "question": "For f(x) = x² + 7 on [0, 6], find c with f(c) = 32.", "math": "", "answer": "5", "type": "number", "solutionSteps": ["The target lies between 7 and 43.", "Solve c² = 25.", "Only c = 5 lies in this interval."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-14-15", "module": 14, "family": 2, "topic": "Infinite limits", "subtopic": "Connect", "difficulty": "Hard", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 7^-}\\frac{5}{(x-7)^{2}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 5, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-15", "module": 15, "family": 2, "topic": "Asymptotes & multiplicity", "subtopic": "Connect", "difficulty": "Hard", "question": "After reduction, classify the asymptote at x = 5.", "math": "f(x)=\\frac{x-5}{(x-5)^{3}}", "answer": "Even", "type": "choice", "solutionSteps": ["Cancel one factor x − 5.", "The denominator power becomes 2.", "The remaining asymptote is even."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-15", "module": 16, "family": 2, "topic": "Rational limits at infinity", "subtopic": "Connect", "difficulty": "Hard", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to -\\infty}\\frac{5 x^{3} + 7}{7 x^{2} + 1}", "answer": "-infinity", "type": "choice", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{5 x}{7}$.", "At the specified end, the limit is $-\\infty$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-17-15", "module": 17, "family": 2, "topic": "Radical limits at infinity", "subtopic": "Connect", "difficulty": "Hard", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{25 x^{2} + 7}}{7 x}", "answer": "\\frac{5}{7}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $\\frac{5}{7}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.7142857142857143}, {"id": "U1-18-15", "module": 18, "family": 2, "topic": "Exponential end behavior", "subtopic": "Connect", "difficulty": "Hard", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}\\frac{5 x^{2} + 7}{x^{2} + e^{x}}", "answer": "0", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "An exponential in the denominator dominates polynomial growth.", "The remaining expression approaches 0."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-19-15", "module": 19, "family": 2, "topic": "Domain, holes & restrictions", "subtopic": "Connect", "difficulty": "Hard", "question": "Find the x-coordinate of the vertical asymptote.", "math": "f(x)=\\frac{(x-5)(x+7)}{(x-5)(x+5)}", "answer": "-5", "type": "number", "solutionSteps": ["Cancel x − 5.", "The remaining denominator x + 5 vanishes at −5.", "The remaining numerator is nonzero there."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -5.0}, {"id": "U1-20-15", "module": 20, "family": 2, "topic": "Intercepts & curve sketching", "subtopic": "Connect", "difficulty": "Hard", "question": "Does this graph cross or touch the x-axis at x = 5?", "math": "f(x)=\\left(x - 5\\right)^{2} \\left(x + 7\\right)", "answer": "Touches", "type": "choice", "solutionSteps": ["The factor x − 5 has multiplicity 2.", "The other factor is nonzero at this root.", "Even multiplicity preserves sign, so the graph touches."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Hard"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-15", "module": 21, "family": 2, "topic": "Average rate of change", "subtopic": "Connect", "difficulty": "Hard", "question": "Find the average rate of change on [4, 6] in km/h.", "math": "", "answer": "5", "type": "number", "solutionSteps": ["The endpoint outputs are 27 and 37.", "The input change is 2.", "Divide the output change by 2 to obtain $5$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": {"headers": ["Time (h)", "Distance (km)"], "rows": [["4", "27"], ["6", "37"]]}, "numericAnswer": 5.0}, {"id": "U1-22-15", "module": 22, "family": 2, "topic": "Estimating instantaneous rates", "subtopic": "Connect", "difficulty": "Hard", "question": "Estimate the instantaneous rate at x = 7 using the secant on [6.5, 7.5].", "math": "f(x)=5 x^{3}", "answer": "\\frac{2945}{4}", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{13}{2}$ and $\\frac{15}{2}$.", "The output change is $\\frac{2945}{4}$ and the input change is $1$.", "The secant estimate is $\\frac{2945}{4}$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 736.25}, {"id": "U1-23-15", "module": 23, "family": 2, "topic": "Squeeze Theorem", "subtopic": "Connect", "difficulty": "Hard", "question": "Near x = 5, p(x) ≤ g(x) ≤ q(x), and both bounding limits are 17. Find the limit of g.", "math": "", "answer": "17", "type": "number", "solutionSteps": ["The required nearby inequality is given.", "Both bounds approach 17.", "Therefore g also approaches 17."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 17.0}, {"id": "U1-24-15", "module": 24, "family": 2, "topic": "Combining limits", "subtopic": "Connect", "difficulty": "Hard", "question": "As x approaches 17, f(x) approaches 5 and g(x) approaches 7. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 17}\\frac{f(x)^2}{g(x)}", "answer": "\\frac{25}{7}", "type": "number", "solutionSteps": ["Use the component limits 5 and 7.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $\\frac{25}{7}$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 3.5714285714285716}, {"id": "U1-25-15", "module": 25, "family": 2, "topic": "Limits of compositions", "subtopic": "Connect", "difficulty": "Hard", "question": "Let f(t) = 5 for t < 7, f(t) = 10 for t > 7, and f(7) = 99. If g(x) = 7 + x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "10", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) > 7.", "The inner output approaches the boundary from above.", "The outer right branch is always 10."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-01-16", "module": 1, "family": 3, "topic": "Understanding a limit", "subtopic": "Reason", "difficulty": "Hard", "question": "If the limit at x = 1 equals 4, must f(1) equal 4?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["A limit describes punctured-neighborhood behavior.", "The point value may differ or be undefined.", "Therefore the point value is not determined."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-02-16", "module": 2, "family": 3, "topic": "Reading limits from graphs", "subtopic": "Reason", "difficulty": "Hard", "question": "Read the graph and find the two-sided limit.", "math": "\\lim_{x\\to -2}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left branch approaches 1.", "The right branch approaches 3.", "These unequal heights mean the limit does not exist."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "1", "3", "0"], "graph": {"type": "jump", "c": -2, "L": 1, "R": 3}, "table": null}, {"id": "U1-03-16", "module": 3, "family": 3, "topic": "One-sided limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<1\\\\x+3&x\\ge 1\\end{cases},\\quad\\lim_{x\\to 1^+}f(x)", "answer": "4", "type": "number", "solutionSteps": ["Use x + 3 from the right.", "Substitute x = 1 into that branch.", "The one-sided limit is 4."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-04-16", "module": 4, "family": 3, "topic": "Direct substitution", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 2}3 x + \\left(x - 1\\right)^{3}", "answer": "7", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 2.", "Simplify to $7$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-05-16", "module": 5, "family": 3, "topic": "Rational & trigonometric limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to \\frac{\\pi}{2}}\\frac{\\cos{\\left(x \\right)} + 1}{\\sin{\\left(x \\right)} + 3}", "answer": "\\frac{1}{4}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $\\frac{\\pi}{2}$ for x.", "Use exact values and simplify to $\\frac{1}{4}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.25}, {"id": "U1-06-16", "module": 6, "family": 3, "topic": "Piecewise limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the two-sided limit at x = 1.", "math": "f(x)=\\begin{cases}x^2+6&x<1\\\\6&x=1\\\\x+7&x>1\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 7.", "The right limit is 8.", "The two-sided limit is DNE; the isolated value 6 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "7", "8", "6"], "graph": null, "table": null}, {"id": "U1-07-16", "module": 7, "family": 3, "topic": "The continuity test", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 3, the left limit is 1, the right limit is 1, and f(3) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-16", "module": 8, "family": 3, "topic": "Classifying discontinuities", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 1, the one-sided limits are 3 and 3, but f(1) = 7. Classify the discontinuity.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They agree but differ from the point value.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-16", "module": 9, "family": 3, "topic": "Factoring indeterminate limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Factor and reduce this expression for inputs in its original domain. Enter the reduced expression in x.", "math": "\\frac{x^2-4}{x^2+2x-8}", "answer": "\\frac{x+2}{x+4}", "type": "expression", "solutionSteps": ["Factor the numerator as (x − 2)(x + 2).", "Factor the denominator as (x − 2)(x + 4).", "Cancel x − 2 only on the original domain, x ≠ 2, −4.", "The reduced rule is (x + 2)/(x + 4)."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "expectedExpression": "(x+2)/(x+4)"}, {"id": "U1-10-16", "module": 10, "family": 3, "topic": "Rationalizing limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{2 x + 9} - 3}{x}", "answer": "\\frac{1}{3}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{3}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.3333333333333333}, {"id": "U1-11-16", "module": 11, "family": 3, "topic": "Limits from numerical tables", "subtopic": "Reason", "difficulty": "Hard", "question": "The table omits x = 1. What does it tell you about f(1)?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The values shown are all near the point.", "A function value at a missing input can be assigned independently.", "The table does not determine that point value."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Not determined", "5", "0"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["0.900", "4.800"], ["0.990", "4.980"], ["0.999", "4.998"], ["1.001", "5.002"], ["1.010", "5.020"], ["1.100", "5.200"]]}}, {"id": "U1-12-16", "module": 12, "family": 3, "topic": "Making a function continuous", "subtopic": "Reason", "difficulty": "Hard", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2+K&|x|>1\\\\0&|x|\\le 1\\end{cases}", "answer": "-1", "type": "number", "solutionSteps": ["At both boundaries x = ±1, the outer limit is 1 + K.", "The inner branch and boundary values are zero.", "Set K = -1; this joins both boundaries."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -1.0}, {"id": "U1-13-16", "module": 13, "family": 3, "topic": "Intermediate Value Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "For f(x) = x² on [−1, 1], do endpoint values alone satisfy the IVT test for the target 0?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Both endpoint values are 1.", "Zero is not between these equal endpoint values.", "This IVT test does not guarantee the target, although f(0) = 0 actually attains it."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-16", "module": 14, "family": 3, "topic": "Infinite limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 3^+}\\frac{-1}{(x-3)^{2}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is -1, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-16", "module": 15, "family": 3, "topic": "Asymptotes & multiplicity", "subtopic": "Reason", "difficulty": "Hard", "question": "After reduction, classify the asymptote at x = 1.", "math": "f(x)=\\frac{x-1}{(x-1)^{2}}", "answer": "Odd", "type": "choice", "solutionSteps": ["Cancel one factor x − 1.", "The denominator power becomes 1.", "The remaining asymptote is odd."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-16", "module": 16, "family": 3, "topic": "Rational limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{\\left(x + 1\\right) \\left(x + 3\\right)}{\\left(x - 1\\right) \\left(3 x + 1\\right)}", "answer": "\\frac{1}{3}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{1}{3}$.", "At the specified end, the limit is $\\frac{1}{3}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.3333333333333333}, {"id": "U1-17-16", "module": 17, "family": 3, "topic": "Radical limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{x^{2} + 3}}{3 x}", "answer": "- \\frac{1}{3}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $- \\frac{1}{3}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -0.3333333333333333}, {"id": "U1-18-16", "module": 18, "family": 3, "topic": "Exponential end behavior", "subtopic": "Reason", "difficulty": "Hard", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}e^{x} + \\frac{3 x^{2} + 1}{x^{2} + 1}", "answer": "3", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 3."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-19-16", "module": 19, "family": 3, "topic": "Domain, holes & restrictions", "subtopic": "Reason", "difficulty": "Hard", "question": "After canceling the common factor, is x = 1 restored to the domain of the ORIGINAL function?", "math": "f(x)=\\frac{(x-1)(x+3)}{(x-1)(x+1)}", "answer": "No", "type": "choice", "solutionSteps": ["The original expression still has a zero denominator there.", "An equivalent reduced rule agrees only on the original domain.", "The original restriction persists."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-20-16", "module": 20, "family": 3, "topic": "Intercepts & curve sketching", "subtopic": "Reason", "difficulty": "Hard", "question": "Does this graph cross or touch the x-axis at x = 1?", "math": "f(x)=\\frac{\\left(x - 1\\right)^{3}}{\\left(x + 3\\right)^{2}}", "answer": "Crosses", "type": "choice", "solutionSteps": ["The denominator is nonzero at the root.", "The numerator root has odd multiplicity 3.", "The sign reverses, so the graph crosses."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Hard"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-16", "module": 21, "family": 3, "topic": "Average rate of change", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the average rate of change on [0, 2].", "math": "f(x)=x^{2} - x", "answer": "1", "type": "number", "solutionSteps": ["The endpoint outputs are 0 and 2.", "The input change is 2.", "Divide the output change by 2 to obtain $1$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-22-16", "module": 22, "family": 3, "topic": "Estimating instantaneous rates", "subtopic": "Reason", "difficulty": "Hard", "question": "Which interval is more local for estimating the instantaneous rate at x = 1?", "math": "", "answer": "[0.9, 1.1]", "type": "choice", "solutionSteps": ["Use a short interval containing the target input.", "Nearby secant slopes better reflect local behavior.", "Choose [0.9, 1.1]."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["[0.9, 1.1]", "[-1, 3]", "[4, 5]"], "graph": null, "table": null}, {"id": "U1-23-16", "module": 23, "family": 3, "topic": "Squeeze Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "Near x = 1, p(x) ≤ g(x) ≤ q(x), but the bounding limits are 1 and 3. What is the limit of g?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The two bounding limits differ.", "The matching-limit hypothesis is missing.", "The limit cannot be determined from this information."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "1", "3", "DNE"], "graph": null, "table": null}, {"id": "U1-24-16", "module": 24, "family": 3, "topic": "Combining limits", "subtopic": "Reason", "difficulty": "Hard", "question": "As x approaches 5, f(x) approaches 1 and g(x) approaches 3. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 5}\\frac{f(x)-1}{g(x)-3}", "answer": "Not determined", "type": "choice", "solutionSteps": ["Use the component limits 1 and 3.", "The quotient gives 0/0, which is indeterminate.", "More information is needed."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "0", "1", "DNE"], "graph": null, "table": null}, {"id": "U1-25-16", "module": 25, "family": 3, "topic": "Limits of compositions", "subtopic": "Reason", "difficulty": "Hard", "question": "The inner limit is 1. The outer function has left limit 3, right limit 6, and point value 99 at 1. Without more information about the inner function, what is the composition limit?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The outer function is discontinuous at the inner limit.", "The inner outputs could approach from either side or hit the boundary.", "Their approach behavior is needed; the limit is not determined."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "3", "6", "99"], "graph": null, "table": null}, {"id": "U1-01-17", "module": 1, "family": 3, "topic": "Understanding a limit", "subtopic": "Reason", "difficulty": "Hard", "question": "If the limit at x = 2 equals 5, must f(2) equal 5?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["A limit describes punctured-neighborhood behavior.", "The point value may differ or be undefined.", "Therefore the point value is not determined."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-02-17", "module": 2, "family": 3, "topic": "Reading limits from graphs", "subtopic": "Reason", "difficulty": "Hard", "question": "Read the graph and find the two-sided limit.", "math": "\\lim_{x\\to -1}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left branch approaches 2.", "The right branch approaches 4.", "These unequal heights mean the limit does not exist."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "2", "4", "0"], "graph": {"type": "jump", "c": -1, "L": 2, "R": 4}, "table": null}, {"id": "U1-03-17", "module": 3, "family": 3, "topic": "One-sided limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<2\\\\x+4&x\\ge 2\\end{cases},\\quad\\lim_{x\\to 2^+}f(x)", "answer": "6", "type": "number", "solutionSteps": ["Use x + 4 from the right.", "Substitute x = 2 into that branch.", "The one-sided limit is 6."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-04-17", "module": 4, "family": 3, "topic": "Direct substitution", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 3}4 x + \\left(x - 2\\right)^{3}", "answer": "13", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 3.", "Simplify to $13$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 13.0}, {"id": "U1-05-17", "module": 5, "family": 3, "topic": "Rational & trigonometric limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to \\frac{\\pi}{2}}\\frac{\\cos{\\left(x \\right)} + 2}{\\sin{\\left(x \\right)} + 4}", "answer": "\\frac{2}{5}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $\\frac{\\pi}{2}$ for x.", "Use exact values and simplify to $\\frac{2}{5}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.4}, {"id": "U1-06-17", "module": 6, "family": 3, "topic": "Piecewise limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the two-sided limit at x = 2.", "math": "f(x)=\\begin{cases}x^2+6&x<2\\\\7&x=2\\\\x+9&x>2\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 10.", "The right limit is 11.", "The two-sided limit is DNE; the isolated value 7 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "10", "11", "7"], "graph": null, "table": null}, {"id": "U1-07-17", "module": 7, "family": 3, "topic": "The continuity test", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 4, the left limit is 2, the right limit is 2, and f(4) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-17", "module": 8, "family": 3, "topic": "Classifying discontinuities", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 2, the one-sided limits are 4 and 4, but f(2) = 8. Classify the discontinuity.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They agree but differ from the point value.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-17", "module": 9, "family": 3, "topic": "Factoring indeterminate limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Factor and reduce this expression for inputs in its original domain. Enter the reduced expression in x.", "math": "\\frac{x^2-9}{x^2+2x-15}", "answer": "\\frac{x+3}{x+5}", "type": "expression", "solutionSteps": ["Factor the numerator as (x − 3)(x + 3).", "Factor the denominator as (x − 3)(x + 5).", "Cancel x − 3 only on the original domain, x ≠ 3, −5.", "The reduced rule is (x + 3)/(x + 5)."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "expectedExpression": "(x+3)/(x+5)"}, {"id": "U1-10-17", "module": 10, "family": 3, "topic": "Rationalizing limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{3 x + 16} - 4}{x}", "answer": "\\frac{3}{8}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{3}{8}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.375}, {"id": "U1-11-17", "module": 11, "family": 3, "topic": "Limits from numerical tables", "subtopic": "Reason", "difficulty": "Hard", "question": "The table omits x = 2. What does it tell you about f(2)?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The values shown are all near the point.", "A function value at a missing input can be assigned independently.", "The table does not determine that point value."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Not determined", "8", "0"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["1.900", "7.800"], ["1.990", "7.980"], ["1.999", "7.998"], ["2.001", "8.002"], ["2.010", "8.020"], ["2.100", "8.200"]]}}, {"id": "U1-12-17", "module": 12, "family": 3, "topic": "Making a function continuous", "subtopic": "Reason", "difficulty": "Hard", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2+K&|x|>2\\\\0&|x|\\le 2\\end{cases}", "answer": "-4", "type": "number", "solutionSteps": ["At both boundaries x = ±2, the outer limit is 4 + K.", "The inner branch and boundary values are zero.", "Set K = -4; this joins both boundaries."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -4.0}, {"id": "U1-13-17", "module": 13, "family": 3, "topic": "Intermediate Value Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "For f(x) = x² on [−2, 2], do endpoint values alone satisfy the IVT test for the target 0?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Both endpoint values are 4.", "Zero is not between these equal endpoint values.", "This IVT test does not guarantee the target, although f(0) = 0 actually attains it."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-17", "module": 14, "family": 3, "topic": "Infinite limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 4^+}\\frac{-2}{(x-4)^{2}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is -2, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-17", "module": 15, "family": 3, "topic": "Asymptotes & multiplicity", "subtopic": "Reason", "difficulty": "Hard", "question": "After reduction, classify the asymptote at x = 2.", "math": "f(x)=\\frac{x-2}{(x-2)^{2}}", "answer": "Odd", "type": "choice", "solutionSteps": ["Cancel one factor x − 2.", "The denominator power becomes 1.", "The remaining asymptote is odd."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-17", "module": 16, "family": 3, "topic": "Rational limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{\\left(x + 4\\right) \\left(2 x + 1\\right)}{\\left(x - 2\\right) \\left(4 x + 1\\right)}", "answer": "\\frac{1}{2}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{1}{2}$.", "At the specified end, the limit is $\\frac{1}{2}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.5}, {"id": "U1-17-17", "module": 17, "family": 3, "topic": "Radical limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{4 x^{2} + 4}}{4 x}", "answer": "- \\frac{1}{2}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $- \\frac{1}{2}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -0.5}, {"id": "U1-18-17", "module": 18, "family": 3, "topic": "Exponential end behavior", "subtopic": "Reason", "difficulty": "Hard", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}2 e^{x} + \\frac{4 x^{2} + 1}{x^{2} + 1}", "answer": "4", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 4."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-19-17", "module": 19, "family": 3, "topic": "Domain, holes & restrictions", "subtopic": "Reason", "difficulty": "Hard", "question": "After canceling the common factor, is x = 2 restored to the domain of the ORIGINAL function?", "math": "f(x)=\\frac{(x-2)(x+4)}{(x-2)(x+2)}", "answer": "No", "type": "choice", "solutionSteps": ["The original expression still has a zero denominator there.", "An equivalent reduced rule agrees only on the original domain.", "The original restriction persists."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-20-17", "module": 20, "family": 3, "topic": "Intercepts & curve sketching", "subtopic": "Reason", "difficulty": "Hard", "question": "Does this graph cross or touch the x-axis at x = 2?", "math": "f(x)=\\frac{\\left(x - 2\\right)^{3}}{\\left(x + 4\\right)^{2}}", "answer": "Crosses", "type": "choice", "solutionSteps": ["The denominator is nonzero at the root.", "The numerator root has odd multiplicity 3.", "The sign reverses, so the graph crosses."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Hard"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-17", "module": 21, "family": 3, "topic": "Average rate of change", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the average rate of change on [1, 3].", "math": "f(x)=x^{2} - 2 x", "answer": "2", "type": "number", "solutionSteps": ["The endpoint outputs are -1 and 3.", "The input change is 2.", "Divide the output change by 2 to obtain $2$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 2.0}, {"id": "U1-22-17", "module": 22, "family": 3, "topic": "Estimating instantaneous rates", "subtopic": "Reason", "difficulty": "Hard", "question": "Which interval is more local for estimating the instantaneous rate at x = 2?", "math": "", "answer": "[1.9, 2.1]", "type": "choice", "solutionSteps": ["Use a short interval containing the target input.", "Nearby secant slopes better reflect local behavior.", "Choose [1.9, 2.1]."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["[1.9, 2.1]", "[0, 4]", "[5, 6]"], "graph": null, "table": null}, {"id": "U1-23-17", "module": 23, "family": 3, "topic": "Squeeze Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "Near x = 2, p(x) ≤ g(x) ≤ q(x), but the bounding limits are 2 and 4. What is the limit of g?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The two bounding limits differ.", "The matching-limit hypothesis is missing.", "The limit cannot be determined from this information."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "2", "4", "DNE"], "graph": null, "table": null}, {"id": "U1-24-17", "module": 24, "family": 3, "topic": "Combining limits", "subtopic": "Reason", "difficulty": "Hard", "question": "As x approaches 8, f(x) approaches 2 and g(x) approaches 4. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 8}\\frac{f(x)-2}{g(x)-4}", "answer": "Not determined", "type": "choice", "solutionSteps": ["Use the component limits 2 and 4.", "The quotient gives 0/0, which is indeterminate.", "More information is needed."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "0", "1", "DNE"], "graph": null, "table": null}, {"id": "U1-25-17", "module": 25, "family": 3, "topic": "Limits of compositions", "subtopic": "Reason", "difficulty": "Hard", "question": "The inner limit is 2. The outer function has left limit 4, right limit 7, and point value 99 at 2. Without more information about the inner function, what is the composition limit?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The outer function is discontinuous at the inner limit.", "The inner outputs could approach from either side or hit the boundary.", "Their approach behavior is needed; the limit is not determined."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "4", "7", "99"], "graph": null, "table": null}, {"id": "U1-01-18", "module": 1, "family": 3, "topic": "Understanding a limit", "subtopic": "Reason", "difficulty": "Hard", "question": "If the limit at x = 3 equals 6, must f(3) equal 6?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["A limit describes punctured-neighborhood behavior.", "The point value may differ or be undefined.", "Therefore the point value is not determined."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-02-18", "module": 2, "family": 3, "topic": "Reading limits from graphs", "subtopic": "Reason", "difficulty": "Hard", "question": "Read the graph and find the two-sided limit.", "math": "\\lim_{x\\to 0}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left branch approaches 3.", "The right branch approaches 5.", "These unequal heights mean the limit does not exist."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "3", "5", "0"], "graph": {"type": "jump", "c": 0, "L": 3, "R": 5}, "table": null}, {"id": "U1-03-18", "module": 3, "family": 3, "topic": "One-sided limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<3\\\\x+5&x\\ge 3\\end{cases},\\quad\\lim_{x\\to 3^+}f(x)", "answer": "8", "type": "number", "solutionSteps": ["Use x + 5 from the right.", "Substitute x = 3 into that branch.", "The one-sided limit is 8."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-04-18", "module": 4, "family": 3, "topic": "Direct substitution", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 4}5 x + \\left(x - 3\\right)^{3}", "answer": "21", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 4.", "Simplify to $21$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 21.0}, {"id": "U1-05-18", "module": 5, "family": 3, "topic": "Rational & trigonometric limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to \\frac{\\pi}{2}}\\frac{\\cos{\\left(x \\right)} + 3}{\\sin{\\left(x \\right)} + 5}", "answer": "\\frac{1}{2}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $\\frac{\\pi}{2}$ for x.", "Use exact values and simplify to $\\frac{1}{2}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.5}, {"id": "U1-06-18", "module": 6, "family": 3, "topic": "Piecewise limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the two-sided limit at x = 3.", "math": "f(x)=\\begin{cases}x^2+6&x<3\\\\8&x=3\\\\x+13&x>3\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 15.", "The right limit is 16.", "The two-sided limit is DNE; the isolated value 8 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "15", "16", "8"], "graph": null, "table": null}, {"id": "U1-07-18", "module": 7, "family": 3, "topic": "The continuity test", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 5, the left limit is 3, the right limit is 3, and f(5) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-18", "module": 8, "family": 3, "topic": "Classifying discontinuities", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 3, the one-sided limits are 5 and 5, but f(3) = 9. Classify the discontinuity.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They agree but differ from the point value.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-18", "module": 9, "family": 3, "topic": "Factoring indeterminate limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Factor and reduce this expression for inputs in its original domain. Enter the reduced expression in x.", "math": "\\frac{x^2-16}{x^2+2x-24}", "answer": "\\frac{x+4}{x+6}", "type": "expression", "solutionSteps": ["Factor the numerator as (x − 4)(x + 4).", "Factor the denominator as (x − 4)(x + 6).", "Cancel x − 4 only on the original domain, x ≠ 4, −6.", "The reduced rule is (x + 4)/(x + 6)."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "expectedExpression": "(x+4)/(x+6)"}, {"id": "U1-10-18", "module": 10, "family": 3, "topic": "Rationalizing limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{4 x + 25} - 5}{x}", "answer": "\\frac{2}{5}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{2}{5}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.4}, {"id": "U1-11-18", "module": 11, "family": 3, "topic": "Limits from numerical tables", "subtopic": "Reason", "difficulty": "Hard", "question": "The table omits x = 3. What does it tell you about f(3)?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The values shown are all near the point.", "A function value at a missing input can be assigned independently.", "The table does not determine that point value."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Not determined", "11", "0"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["2.900", "10.800"], ["2.990", "10.980"], ["2.999", "10.998"], ["3.001", "11.002"], ["3.010", "11.020"], ["3.100", "11.200"]]}}, {"id": "U1-12-18", "module": 12, "family": 3, "topic": "Making a function continuous", "subtopic": "Reason", "difficulty": "Hard", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2+K&|x|>3\\\\0&|x|\\le 3\\end{cases}", "answer": "-9", "type": "number", "solutionSteps": ["At both boundaries x = ±3, the outer limit is 9 + K.", "The inner branch and boundary values are zero.", "Set K = -9; this joins both boundaries."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -9.0}, {"id": "U1-13-18", "module": 13, "family": 3, "topic": "Intermediate Value Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "For f(x) = x² on [−3, 3], do endpoint values alone satisfy the IVT test for the target 0?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Both endpoint values are 9.", "Zero is not between these equal endpoint values.", "This IVT test does not guarantee the target, although f(0) = 0 actually attains it."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-18", "module": 14, "family": 3, "topic": "Infinite limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 5^+}\\frac{-3}{(x-5)^{2}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is -3, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-18", "module": 15, "family": 3, "topic": "Asymptotes & multiplicity", "subtopic": "Reason", "difficulty": "Hard", "question": "After reduction, classify the asymptote at x = 3.", "math": "f(x)=\\frac{x-3}{(x-3)^{2}}", "answer": "Odd", "type": "choice", "solutionSteps": ["Cancel one factor x − 3.", "The denominator power becomes 1.", "The remaining asymptote is odd."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-18", "module": 16, "family": 3, "topic": "Rational limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{\\left(x + 5\\right) \\left(3 x + 1\\right)}{\\left(x - 3\\right) \\left(5 x + 1\\right)}", "answer": "\\frac{3}{5}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{3}{5}$.", "At the specified end, the limit is $\\frac{3}{5}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.6}, {"id": "U1-17-18", "module": 17, "family": 3, "topic": "Radical limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{9 x^{2} + 5}}{5 x}", "answer": "- \\frac{3}{5}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $- \\frac{3}{5}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -0.6}, {"id": "U1-18-18", "module": 18, "family": 3, "topic": "Exponential end behavior", "subtopic": "Reason", "difficulty": "Hard", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}3 e^{x} + \\frac{5 x^{2} + 1}{x^{2} + 1}", "answer": "5", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 5."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-19-18", "module": 19, "family": 3, "topic": "Domain, holes & restrictions", "subtopic": "Reason", "difficulty": "Hard", "question": "After canceling the common factor, is x = 3 restored to the domain of the ORIGINAL function?", "math": "f(x)=\\frac{(x-3)(x+5)}{(x-3)(x+3)}", "answer": "No", "type": "choice", "solutionSteps": ["The original expression still has a zero denominator there.", "An equivalent reduced rule agrees only on the original domain.", "The original restriction persists."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-20-18", "module": 20, "family": 3, "topic": "Intercepts & curve sketching", "subtopic": "Reason", "difficulty": "Hard", "question": "Does this graph cross or touch the x-axis at x = 3?", "math": "f(x)=\\frac{\\left(x - 3\\right)^{3}}{\\left(x + 5\\right)^{2}}", "answer": "Crosses", "type": "choice", "solutionSteps": ["The denominator is nonzero at the root.", "The numerator root has odd multiplicity 3.", "The sign reverses, so the graph crosses."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Hard"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-18", "module": 21, "family": 3, "topic": "Average rate of change", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the average rate of change on [2, 4].", "math": "f(x)=x^{2} - 3 x", "answer": "3", "type": "number", "solutionSteps": ["The endpoint outputs are -2 and 4.", "The input change is 2.", "Divide the output change by 2 to obtain $3$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-22-18", "module": 22, "family": 3, "topic": "Estimating instantaneous rates", "subtopic": "Reason", "difficulty": "Hard", "question": "Which interval is more local for estimating the instantaneous rate at x = 3?", "math": "", "answer": "[2.9, 3.1]", "type": "choice", "solutionSteps": ["Use a short interval containing the target input.", "Nearby secant slopes better reflect local behavior.", "Choose [2.9, 3.1]."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["[2.9, 3.1]", "[1, 5]", "[6, 7]"], "graph": null, "table": null}, {"id": "U1-23-18", "module": 23, "family": 3, "topic": "Squeeze Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "Near x = 3, p(x) ≤ g(x) ≤ q(x), but the bounding limits are 3 and 5. What is the limit of g?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The two bounding limits differ.", "The matching-limit hypothesis is missing.", "The limit cannot be determined from this information."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "3", "5", "DNE"], "graph": null, "table": null}, {"id": "U1-24-18", "module": 24, "family": 3, "topic": "Combining limits", "subtopic": "Reason", "difficulty": "Hard", "question": "As x approaches 11, f(x) approaches 3 and g(x) approaches 5. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 11}\\frac{f(x)-3}{g(x)-5}", "answer": "Not determined", "type": "choice", "solutionSteps": ["Use the component limits 3 and 5.", "The quotient gives 0/0, which is indeterminate.", "More information is needed."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "0", "1", "DNE"], "graph": null, "table": null}, {"id": "U1-25-18", "module": 25, "family": 3, "topic": "Limits of compositions", "subtopic": "Reason", "difficulty": "Hard", "question": "The inner limit is 3. The outer function has left limit 5, right limit 8, and point value 99 at 3. Without more information about the inner function, what is the composition limit?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The outer function is discontinuous at the inner limit.", "The inner outputs could approach from either side or hit the boundary.", "Their approach behavior is needed; the limit is not determined."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "5", "8", "99"], "graph": null, "table": null}, {"id": "U1-01-19", "module": 1, "family": 3, "topic": "Understanding a limit", "subtopic": "Reason", "difficulty": "Hard", "question": "If the limit at x = 4 equals 7, must f(4) equal 7?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["A limit describes punctured-neighborhood behavior.", "The point value may differ or be undefined.", "Therefore the point value is not determined."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-02-19", "module": 2, "family": 3, "topic": "Reading limits from graphs", "subtopic": "Reason", "difficulty": "Hard", "question": "Read the graph and find the two-sided limit.", "math": "\\lim_{x\\to 1}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left branch approaches 4.", "The right branch approaches 6.", "These unequal heights mean the limit does not exist."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "4", "6", "0"], "graph": {"type": "jump", "c": 1, "L": 4, "R": 6}, "table": null}, {"id": "U1-03-19", "module": 3, "family": 3, "topic": "One-sided limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<4\\\\x+6&x\\ge 4\\end{cases},\\quad\\lim_{x\\to 4^+}f(x)", "answer": "10", "type": "number", "solutionSteps": ["Use x + 6 from the right.", "Substitute x = 4 into that branch.", "The one-sided limit is 10."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-04-19", "module": 4, "family": 3, "topic": "Direct substitution", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 5}6 x + \\left(x - 4\\right)^{3}", "answer": "31", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 5.", "Simplify to $31$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 31.0}, {"id": "U1-05-19", "module": 5, "family": 3, "topic": "Rational & trigonometric limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to \\frac{\\pi}{2}}\\frac{\\cos{\\left(x \\right)} + 4}{\\sin{\\left(x \\right)} + 6}", "answer": "\\frac{4}{7}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $\\frac{\\pi}{2}$ for x.", "Use exact values and simplify to $\\frac{4}{7}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.5714285714285714}, {"id": "U1-06-19", "module": 6, "family": 3, "topic": "Piecewise limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the two-sided limit at x = 4.", "math": "f(x)=\\begin{cases}x^2+6&x<4\\\\9&x=4\\\\x+19&x>4\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 22.", "The right limit is 23.", "The two-sided limit is DNE; the isolated value 9 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "22", "23", "9"], "graph": null, "table": null}, {"id": "U1-07-19", "module": 7, "family": 3, "topic": "The continuity test", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 6, the left limit is 4, the right limit is 4, and f(6) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-19", "module": 8, "family": 3, "topic": "Classifying discontinuities", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 4, the one-sided limits are 6 and 6, but f(4) = 10. Classify the discontinuity.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They agree but differ from the point value.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-19", "module": 9, "family": 3, "topic": "Factoring indeterminate limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Factor and reduce this expression for inputs in its original domain. Enter the reduced expression in x.", "math": "\\frac{x^2-25}{x^2+2x-35}", "answer": "\\frac{x+5}{x+7}", "type": "expression", "solutionSteps": ["Factor the numerator as (x − 5)(x + 5).", "Factor the denominator as (x − 5)(x + 7).", "Cancel x − 5 only on the original domain, x ≠ 5, −7.", "The reduced rule is (x + 5)/(x + 7)."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "expectedExpression": "(x+5)/(x+7)"}, {"id": "U1-10-19", "module": 10, "family": 3, "topic": "Rationalizing limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{5 x + 36} - 6}{x}", "answer": "\\frac{5}{12}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{5}{12}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.4166666666666667}, {"id": "U1-11-19", "module": 11, "family": 3, "topic": "Limits from numerical tables", "subtopic": "Reason", "difficulty": "Hard", "question": "The table omits x = 4. What does it tell you about f(4)?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The values shown are all near the point.", "A function value at a missing input can be assigned independently.", "The table does not determine that point value."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Not determined", "14", "0"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["3.900", "13.800"], ["3.990", "13.980"], ["3.999", "13.998"], ["4.001", "14.002"], ["4.010", "14.020"], ["4.100", "14.200"]]}}, {"id": "U1-12-19", "module": 12, "family": 3, "topic": "Making a function continuous", "subtopic": "Reason", "difficulty": "Hard", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2+K&|x|>4\\\\0&|x|\\le 4\\end{cases}", "answer": "-16", "type": "number", "solutionSteps": ["At both boundaries x = ±4, the outer limit is 16 + K.", "The inner branch and boundary values are zero.", "Set K = -16; this joins both boundaries."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -16.0}, {"id": "U1-13-19", "module": 13, "family": 3, "topic": "Intermediate Value Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "For f(x) = x² on [−4, 4], do endpoint values alone satisfy the IVT test for the target 0?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Both endpoint values are 16.", "Zero is not between these equal endpoint values.", "This IVT test does not guarantee the target, although f(0) = 0 actually attains it."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-19", "module": 14, "family": 3, "topic": "Infinite limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 6^+}\\frac{-4}{(x-6)^{2}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is -4, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-19", "module": 15, "family": 3, "topic": "Asymptotes & multiplicity", "subtopic": "Reason", "difficulty": "Hard", "question": "After reduction, classify the asymptote at x = 4.", "math": "f(x)=\\frac{x-4}{(x-4)^{2}}", "answer": "Odd", "type": "choice", "solutionSteps": ["Cancel one factor x − 4.", "The denominator power becomes 1.", "The remaining asymptote is odd."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-19", "module": 16, "family": 3, "topic": "Rational limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{\\left(x + 6\\right) \\left(4 x + 1\\right)}{\\left(x - 4\\right) \\left(6 x + 1\\right)}", "answer": "\\frac{2}{3}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{2}{3}$.", "At the specified end, the limit is $\\frac{2}{3}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.6666666666666666}, {"id": "U1-17-19", "module": 17, "family": 3, "topic": "Radical limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{16 x^{2} + 6}}{6 x}", "answer": "- \\frac{2}{3}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $- \\frac{2}{3}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -0.6666666666666666}, {"id": "U1-18-19", "module": 18, "family": 3, "topic": "Exponential end behavior", "subtopic": "Reason", "difficulty": "Hard", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}4 e^{x} + \\frac{6 x^{2} + 1}{x^{2} + 1}", "answer": "6", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 6."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-19-19", "module": 19, "family": 3, "topic": "Domain, holes & restrictions", "subtopic": "Reason", "difficulty": "Hard", "question": "After canceling the common factor, is x = 4 restored to the domain of the ORIGINAL function?", "math": "f(x)=\\frac{(x-4)(x+6)}{(x-4)(x+4)}", "answer": "No", "type": "choice", "solutionSteps": ["The original expression still has a zero denominator there.", "An equivalent reduced rule agrees only on the original domain.", "The original restriction persists."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-20-19", "module": 20, "family": 3, "topic": "Intercepts & curve sketching", "subtopic": "Reason", "difficulty": "Hard", "question": "Does this graph cross or touch the x-axis at x = 4?", "math": "f(x)=\\frac{\\left(x - 4\\right)^{3}}{\\left(x + 6\\right)^{2}}", "answer": "Crosses", "type": "choice", "solutionSteps": ["The denominator is nonzero at the root.", "The numerator root has odd multiplicity 3.", "The sign reverses, so the graph crosses."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Hard"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-19", "module": 21, "family": 3, "topic": "Average rate of change", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the average rate of change on [3, 5].", "math": "f(x)=x^{2} - 4 x", "answer": "4", "type": "number", "solutionSteps": ["The endpoint outputs are -3 and 5.", "The input change is 2.", "Divide the output change by 2 to obtain $4$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-22-19", "module": 22, "family": 3, "topic": "Estimating instantaneous rates", "subtopic": "Reason", "difficulty": "Hard", "question": "Which interval is more local for estimating the instantaneous rate at x = 4?", "math": "", "answer": "[3.9, 4.1]", "type": "choice", "solutionSteps": ["Use a short interval containing the target input.", "Nearby secant slopes better reflect local behavior.", "Choose [3.9, 4.1]."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["[3.9, 4.1]", "[2, 6]", "[7, 8]"], "graph": null, "table": null}, {"id": "U1-23-19", "module": 23, "family": 3, "topic": "Squeeze Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "Near x = 4, p(x) ≤ g(x) ≤ q(x), but the bounding limits are 4 and 6. What is the limit of g?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The two bounding limits differ.", "The matching-limit hypothesis is missing.", "The limit cannot be determined from this information."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "4", "6", "DNE"], "graph": null, "table": null}, {"id": "U1-24-19", "module": 24, "family": 3, "topic": "Combining limits", "subtopic": "Reason", "difficulty": "Hard", "question": "As x approaches 14, f(x) approaches 4 and g(x) approaches 6. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 14}\\frac{f(x)-4}{g(x)-6}", "answer": "Not determined", "type": "choice", "solutionSteps": ["Use the component limits 4 and 6.", "The quotient gives 0/0, which is indeterminate.", "More information is needed."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "0", "1", "DNE"], "graph": null, "table": null}, {"id": "U1-25-19", "module": 25, "family": 3, "topic": "Limits of compositions", "subtopic": "Reason", "difficulty": "Hard", "question": "The inner limit is 4. The outer function has left limit 6, right limit 9, and point value 99 at 4. Without more information about the inner function, what is the composition limit?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The outer function is discontinuous at the inner limit.", "The inner outputs could approach from either side or hit the boundary.", "Their approach behavior is needed; the limit is not determined."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "6", "9", "99"], "graph": null, "table": null}, {"id": "U1-01-21", "module": 1, "family": 0, "topic": "Understanding a limit", "subtopic": "Recognize", "difficulty": "Easy", "question": "Near x = 6, both sides of f(x) approach 9, but f(6) = 13. Find the limit.", "math": "\\lim_{x\\to 6}f(x)", "answer": "9", "type": "number", "solutionSteps": ["Nearby values from both sides approach 9.", "The value f(6) = 13 affects the point, not the nearby trend.", "The limit is 9."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-02-21", "module": 2, "family": 0, "topic": "Reading limits from graphs", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the graph to find the two-sided limit.", "math": "\\lim_{x\\to 3}f(x)", "answer": "5", "type": "number", "solutionSteps": ["Both branches approach the open point at (3, 5).", "The filled point is the function value, not the limit.", "The limit is 5."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": {"type": "hole", "c": 3, "L": 5, "value": 8, "m": 1}, "table": null, "numericAnswer": 5.0}, {"id": "U1-03-21", "module": 3, "family": 0, "topic": "One-sided limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 8^-}\\frac{6|x-8|}{x-8}", "answer": "-6", "type": "number", "solutionSteps": ["On this side, x − 8 is negative.", "Replace the absolute value with the negative of its argument.", "Cancel the nonzero factor nearby to get -6."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -6.0}, {"id": "U1-04-21", "module": 4, "family": 0, "topic": "Direct substitution", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 8}6 x + 8", "answer": "56", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 8.", "Simplify to $56$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 56.0}, {"id": "U1-05-21", "module": 5, "family": 0, "topic": "Rational & trigonometric limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 6}\\frac{x + 6}{x^{2} + 8}", "answer": "\\frac{3}{11}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $6$ for x.", "Use exact values and simplify to $\\frac{3}{11}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.2727272727272727}, {"id": "U1-06-21", "module": 6, "family": 0, "topic": "Piecewise limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the two-sided limit at x = 6.", "math": "f(x)=\\begin{cases}x^2+0&x<6\\\\8&x=6\\\\x+30&x>6\\end{cases}", "answer": "36", "type": "number", "solutionSteps": ["The left limit is 36.", "The right limit is 36.", "The two-sided limit is 36; the isolated value 8 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 36.0}, {"id": "U1-07-21", "module": 7, "family": 0, "topic": "The continuity test", "subtopic": "Recognize", "difficulty": "Easy", "question": "At x = 8, the left limit is 6, the right limit is 6, and f(8) is 6. Is f continuous there?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value matches the common limit."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-21", "module": 8, "family": 0, "topic": "Classifying discontinuities", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the discontinuity at x = 6 for this function.", "math": "\\frac{x^{2} - 36}{x - 6}", "answer": "Removable", "type": "choice", "solutionSteps": ["Factor the numerator and cancel x − 6.", "The nearby behavior is the finite value 12.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-21", "module": 9, "family": 0, "topic": "Factoring indeterminate limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 6}\\frac{x^{2} - 36}{x - 6}", "answer": "12", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 6 for nearby x.", "The reduced expression is $x + 6$.", "Substitute x = 6 to obtain $12$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-10-21", "module": 10, "family": 0, "topic": "Rationalizing limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 36}\\frac{\\sqrt{x} - 6}{x - 36}", "answer": "\\frac{1}{12}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{12}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.08333333333333333}, {"id": "U1-11-21", "module": 11, "family": 0, "topic": "Limits from numerical tables", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the limit as x approaches 6 from the table.", "math": "", "answer": "20", "type": "number", "solutionSteps": ["As inputs approach 6 from the left, outputs approach 20.", "The right-side outputs also approach 20.", "The table suggests a limit of 20."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["5.900", "19.800"], ["5.990", "19.980"], ["5.999", "19.998"], ["6.001", "20.002"], ["6.010", "20.020"], ["6.100", "20.200"]]}, "numericAnswer": 20.0}, {"id": "U1-12-21", "module": 12, "family": 0, "topic": "Making a function continuous", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}\\frac{x^2-36}{x-6}&x\\ne 6\\\\K&x=6\\end{cases}", "answer": "12", "type": "number", "solutionSteps": ["Factor and cancel x − 6.", "The nearby expression is x + 6, with limit 12.", "Set K = 12."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-13-21", "module": 13, "family": 0, "topic": "Intermediate Value Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "For f(x) = x² on [0, 8], does IVT guarantee an interior point with f(c) = 36?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["A polynomial is continuous on the whole interval.", "The endpoint values are 0 and 64.", "The target 36 is strictly between them."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-21", "module": 14, "family": 0, "topic": "Infinite limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 8^-}\\frac{6}{(x-8)^{1}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is 6, which is nonzero.", "The denominator approaches zero negatively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": {"type": "rational", "c": 8, "L": 0, "a": 6, "power": 1, "offset": 0}, "table": null}, {"id": "U1-15-21", "module": 15, "family": 0, "topic": "Asymptotes & multiplicity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the vertical asymptote at x = 6.", "math": "f(x)=\\frac{8}{(x-6)^{2}}", "answer": "Even", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 2.", "The asymptote has even multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-21", "module": 16, "family": 0, "topic": "Rational limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{6 x^{2} + 8}{8 x^{2} + 1}", "answer": "\\frac{3}{4}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{3}{4}$.", "At the specified end, the limit is $\\frac{3}{4}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.75}, {"id": "U1-17-21", "module": 17, "family": 0, "topic": "Radical limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{36 x^{2} + 8}}{x}", "answer": "6", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $6$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-18-21", "module": 18, "family": 0, "topic": "Exponential end behavior", "subtopic": "Recognize", "difficulty": "Easy", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}6 e^{x} + 8", "answer": "8", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 8."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-19-21", "module": 19, "family": 0, "topic": "Domain, holes & restrictions", "subtopic": "Recognize", "difficulty": "Easy", "question": "Select every input excluded from the domain.", "math": "f(x)=\\frac{(x-6)(x+8)}{(x-6)(x+6)}", "answer": ["6", "-6"], "type": "multi", "solutionSteps": ["The original denominator vanishes at ±6.", "Both values are excluded even if a factor later cancels."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Easy"], "options": ["6", "-6", "0", "8"], "graph": null, "table": null}, {"id": "U1-20-21", "module": 20, "family": 0, "topic": "Intercepts & curve sketching", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the x-coordinate of the x-intercept.", "math": "f(x)=\\frac{x - 6}{x + 8}", "answer": "6", "type": "number", "solutionSteps": ["Set the numerator x − 6 equal to zero.", "At x = 6, the denominator is 14, nonzero.", "The x-intercept is (6, 0)."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-21-21", "module": 21, "family": 0, "topic": "Average rate of change", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the average rate of change on [5, 7].", "math": "f(x)=x^{2} + 6", "answer": "12", "type": "number", "solutionSteps": ["The endpoint outputs are 31 and 55.", "The input change is 2.", "Divide the output change by 2 to obtain $12$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-22-21", "module": 22, "family": 0, "topic": "Estimating instantaneous rates", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the instantaneous rate at x = 8 using the secant on [7.9, 8.1].", "math": "f(x)=6 x^{2} + 8 x", "answer": "104", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{79}{10}$ and $\\frac{81}{10}$.", "The output change is $\\frac{104}{5}$ and the input change is $\\frac{1}{5}$.", "The secant estimate is $104$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 104.0}, {"id": "U1-23-21", "module": 23, "family": 0, "topic": "Squeeze Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}6x^{2}\\sin(1/x)+8", "answer": "8", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 8, both bounds approach 8.", "The Squeeze Theorem gives 8."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-24-21", "module": 24, "family": 0, "topic": "Combining limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x approaches 20, f(x) approaches 6 and g(x) approaches 8. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 20}2f(x)+3g(x)", "answer": "36", "type": "number", "solutionSteps": ["Use the component limits 6 and 8.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $36$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 36.0}, {"id": "U1-25-21", "module": 25, "family": 0, "topic": "Limits of compositions", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x → 8, g(x) → 6. If f(t) = t² + 8, find the limit of f(g(x)).", "math": "", "answer": "44", "type": "number", "solutionSteps": ["The inner output approaches 6.", "The outer polynomial is continuous.", "Evaluate f(6) = 44."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 44.0}, {"id": "U1-01-22", "module": 1, "family": 0, "topic": "Understanding a limit", "subtopic": "Recognize", "difficulty": "Easy", "question": "Near x = 7, both sides of f(x) approach 10, but f(7) = 14. Find the limit.", "math": "\\lim_{x\\to 7}f(x)", "answer": "10", "type": "number", "solutionSteps": ["Nearby values from both sides approach 10.", "The value f(7) = 14 affects the point, not the nearby trend.", "The limit is 10."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-02-22", "module": 2, "family": 0, "topic": "Reading limits from graphs", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the graph to find the two-sided limit.", "math": "\\lim_{x\\to 4}f(x)", "answer": "6", "type": "number", "solutionSteps": ["Both branches approach the open point at (4, 6).", "The filled point is the function value, not the limit.", "The limit is 6."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": {"type": "hole", "c": 4, "L": 6, "value": 9, "m": 1}, "table": null, "numericAnswer": 6.0}, {"id": "U1-03-22", "module": 3, "family": 0, "topic": "One-sided limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 9^-}\\frac{7|x-9|}{x-9}", "answer": "-7", "type": "number", "solutionSteps": ["On this side, x − 9 is negative.", "Replace the absolute value with the negative of its argument.", "Cancel the nonzero factor nearby to get -7."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -7.0}, {"id": "U1-04-22", "module": 4, "family": 0, "topic": "Direct substitution", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 9}7 x + 9", "answer": "72", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 9.", "Simplify to $72$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 72.0}, {"id": "U1-05-22", "module": 5, "family": 0, "topic": "Rational & trigonometric limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 7}\\frac{x + 7}{x^{2} + 9}", "answer": "\\frac{7}{29}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $7$ for x.", "Use exact values and simplify to $\\frac{7}{29}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.2413793103448276}, {"id": "U1-06-22", "module": 6, "family": 0, "topic": "Piecewise limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the two-sided limit at x = 7.", "math": "f(x)=\\begin{cases}x^2+0&x<7\\\\9&x=7\\\\x+42&x>7\\end{cases}", "answer": "49", "type": "number", "solutionSteps": ["The left limit is 49.", "The right limit is 49.", "The two-sided limit is 49; the isolated value 9 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 49.0}, {"id": "U1-07-22", "module": 7, "family": 0, "topic": "The continuity test", "subtopic": "Recognize", "difficulty": "Easy", "question": "At x = 9, the left limit is 7, the right limit is 7, and f(9) is 7. Is f continuous there?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value matches the common limit."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-22", "module": 8, "family": 0, "topic": "Classifying discontinuities", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the discontinuity at x = 7 for this function.", "math": "\\frac{x^{2} - 49}{x - 7}", "answer": "Removable", "type": "choice", "solutionSteps": ["Factor the numerator and cancel x − 7.", "The nearby behavior is the finite value 14.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-22", "module": 9, "family": 0, "topic": "Factoring indeterminate limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 7}\\frac{x^{2} - 49}{x - 7}", "answer": "14", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 7 for nearby x.", "The reduced expression is $x + 7$.", "Substitute x = 7 to obtain $14$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 14.0}, {"id": "U1-10-22", "module": 10, "family": 0, "topic": "Rationalizing limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 49}\\frac{\\sqrt{x} - 7}{x - 49}", "answer": "\\frac{1}{14}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{14}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.07142857142857142}, {"id": "U1-11-22", "module": 11, "family": 0, "topic": "Limits from numerical tables", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the limit as x approaches 7 from the table.", "math": "", "answer": "23", "type": "number", "solutionSteps": ["As inputs approach 7 from the left, outputs approach 23.", "The right-side outputs also approach 23.", "The table suggests a limit of 23."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["6.900", "22.800"], ["6.990", "22.980"], ["6.999", "22.998"], ["7.001", "23.002"], ["7.010", "23.020"], ["7.100", "23.200"]]}, "numericAnswer": 23.0}, {"id": "U1-12-22", "module": 12, "family": 0, "topic": "Making a function continuous", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}\\frac{x^2-49}{x-7}&x\\ne 7\\\\K&x=7\\end{cases}", "answer": "14", "type": "number", "solutionSteps": ["Factor and cancel x − 7.", "The nearby expression is x + 7, with limit 14.", "Set K = 14."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 14.0}, {"id": "U1-13-22", "module": 13, "family": 0, "topic": "Intermediate Value Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "For f(x) = x² on [0, 9], does IVT guarantee an interior point with f(c) = 49?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["A polynomial is continuous on the whole interval.", "The endpoint values are 0 and 81.", "The target 49 is strictly between them."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-22", "module": 14, "family": 0, "topic": "Infinite limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 9^-}\\frac{7}{(x-9)^{1}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is 7, which is nonzero.", "The denominator approaches zero negatively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": {"type": "rational", "c": 9, "L": 0, "a": 7, "power": 1, "offset": 0}, "table": null}, {"id": "U1-15-22", "module": 15, "family": 0, "topic": "Asymptotes & multiplicity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the vertical asymptote at x = 7.", "math": "f(x)=\\frac{9}{(x-7)^{2}}", "answer": "Even", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 2.", "The asymptote has even multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-22", "module": 16, "family": 0, "topic": "Rational limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{7 x^{2} + 9}{9 x^{2} + 1}", "answer": "\\frac{7}{9}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{7}{9}$.", "At the specified end, the limit is $\\frac{7}{9}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.7777777777777778}, {"id": "U1-17-22", "module": 17, "family": 0, "topic": "Radical limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{49 x^{2} + 9}}{x}", "answer": "7", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $7$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-18-22", "module": 18, "family": 0, "topic": "Exponential end behavior", "subtopic": "Recognize", "difficulty": "Easy", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}7 e^{x} + 9", "answer": "9", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 9."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-19-22", "module": 19, "family": 0, "topic": "Domain, holes & restrictions", "subtopic": "Recognize", "difficulty": "Easy", "question": "Select every input excluded from the domain.", "math": "f(x)=\\frac{(x-7)(x+9)}{(x-7)(x+7)}", "answer": ["7", "-7"], "type": "multi", "solutionSteps": ["The original denominator vanishes at ±7.", "Both values are excluded even if a factor later cancels."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Easy"], "options": ["7", "-7", "0", "9"], "graph": null, "table": null}, {"id": "U1-20-22", "module": 20, "family": 0, "topic": "Intercepts & curve sketching", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the x-coordinate of the x-intercept.", "math": "f(x)=\\frac{x - 7}{x + 9}", "answer": "7", "type": "number", "solutionSteps": ["Set the numerator x − 7 equal to zero.", "At x = 7, the denominator is 16, nonzero.", "The x-intercept is (7, 0)."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-21-22", "module": 21, "family": 0, "topic": "Average rate of change", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the average rate of change on [6, 8].", "math": "f(x)=x^{2} + 7", "answer": "14", "type": "number", "solutionSteps": ["The endpoint outputs are 43 and 71.", "The input change is 2.", "Divide the output change by 2 to obtain $14$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 14.0}, {"id": "U1-22-22", "module": 22, "family": 0, "topic": "Estimating instantaneous rates", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the instantaneous rate at x = 9 using the secant on [8.9, 9.1].", "math": "f(x)=7 x^{2} + 9 x", "answer": "135", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{89}{10}$ and $\\frac{91}{10}$.", "The output change is $27$ and the input change is $\\frac{1}{5}$.", "The secant estimate is $135$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 135.0}, {"id": "U1-23-22", "module": 23, "family": 0, "topic": "Squeeze Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}7x^{2}\\sin(1/x)+9", "answer": "9", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 9, both bounds approach 9.", "The Squeeze Theorem gives 9."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-24-22", "module": 24, "family": 0, "topic": "Combining limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x approaches 23, f(x) approaches 7 and g(x) approaches 9. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 23}2f(x)+3g(x)", "answer": "41", "type": "number", "solutionSteps": ["Use the component limits 7 and 9.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $41$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 41.0}, {"id": "U1-25-22", "module": 25, "family": 0, "topic": "Limits of compositions", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x → 9, g(x) → 7. If f(t) = t² + 9, find the limit of f(g(x)).", "math": "", "answer": "58", "type": "number", "solutionSteps": ["The inner output approaches 7.", "The outer polynomial is continuous.", "Evaluate f(7) = 58."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 58.0}, {"id": "U1-01-23", "module": 1, "family": 0, "topic": "Understanding a limit", "subtopic": "Recognize", "difficulty": "Easy", "question": "Near x = 8, both sides of f(x) approach 11, but f(8) = 15. Find the limit.", "math": "\\lim_{x\\to 8}f(x)", "answer": "11", "type": "number", "solutionSteps": ["Nearby values from both sides approach 11.", "The value f(8) = 15 affects the point, not the nearby trend.", "The limit is 11."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 11.0}, {"id": "U1-02-23", "module": 2, "family": 0, "topic": "Reading limits from graphs", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the graph to find the two-sided limit.", "math": "\\lim_{x\\to 5}f(x)", "answer": "7", "type": "number", "solutionSteps": ["Both branches approach the open point at (5, 7).", "The filled point is the function value, not the limit.", "The limit is 7."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": {"type": "hole", "c": 5, "L": 7, "value": 10, "m": 1}, "table": null, "numericAnswer": 7.0}, {"id": "U1-03-23", "module": 3, "family": 0, "topic": "One-sided limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 10^-}\\frac{8|x-10|}{x-10}", "answer": "-8", "type": "number", "solutionSteps": ["On this side, x − 10 is negative.", "Replace the absolute value with the negative of its argument.", "Cancel the nonzero factor nearby to get -8."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -8.0}, {"id": "U1-04-23", "module": 4, "family": 0, "topic": "Direct substitution", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 10}8 x + 10", "answer": "90", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 10.", "Simplify to $90$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 90.0}, {"id": "U1-05-23", "module": 5, "family": 0, "topic": "Rational & trigonometric limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 8}\\frac{x + 8}{x^{2} + 10}", "answer": "\\frac{8}{37}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $8$ for x.", "Use exact values and simplify to $\\frac{8}{37}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.21621621621621623}, {"id": "U1-06-23", "module": 6, "family": 0, "topic": "Piecewise limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the two-sided limit at x = 8.", "math": "f(x)=\\begin{cases}x^2+0&x<8\\\\10&x=8\\\\x+56&x>8\\end{cases}", "answer": "64", "type": "number", "solutionSteps": ["The left limit is 64.", "The right limit is 64.", "The two-sided limit is 64; the isolated value 10 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 64.0}, {"id": "U1-07-23", "module": 7, "family": 0, "topic": "The continuity test", "subtopic": "Recognize", "difficulty": "Easy", "question": "At x = 10, the left limit is 8, the right limit is 8, and f(10) is 8. Is f continuous there?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value matches the common limit."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-23", "module": 8, "family": 0, "topic": "Classifying discontinuities", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the discontinuity at x = 8 for this function.", "math": "\\frac{x^{2} - 64}{x - 8}", "answer": "Removable", "type": "choice", "solutionSteps": ["Factor the numerator and cancel x − 8.", "The nearby behavior is the finite value 16.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-23", "module": 9, "family": 0, "topic": "Factoring indeterminate limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 8}\\frac{x^{2} - 64}{x - 8}", "answer": "16", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 8 for nearby x.", "The reduced expression is $x + 8$.", "Substitute x = 8 to obtain $16$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 16.0}, {"id": "U1-10-23", "module": 10, "family": 0, "topic": "Rationalizing limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 64}\\frac{\\sqrt{x} - 8}{x - 64}", "answer": "\\frac{1}{16}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{16}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0625}, {"id": "U1-11-23", "module": 11, "family": 0, "topic": "Limits from numerical tables", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the limit as x approaches 8 from the table.", "math": "", "answer": "26", "type": "number", "solutionSteps": ["As inputs approach 8 from the left, outputs approach 26.", "The right-side outputs also approach 26.", "The table suggests a limit of 26."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["7.900", "25.800"], ["7.990", "25.980"], ["7.999", "25.998"], ["8.001", "26.002"], ["8.010", "26.020"], ["8.100", "26.200"]]}, "numericAnswer": 26.0}, {"id": "U1-12-23", "module": 12, "family": 0, "topic": "Making a function continuous", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}\\frac{x^2-64}{x-8}&x\\ne 8\\\\K&x=8\\end{cases}", "answer": "16", "type": "number", "solutionSteps": ["Factor and cancel x − 8.", "The nearby expression is x + 8, with limit 16.", "Set K = 16."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 16.0}, {"id": "U1-13-23", "module": 13, "family": 0, "topic": "Intermediate Value Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "For f(x) = x² on [0, 10], does IVT guarantee an interior point with f(c) = 64?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["A polynomial is continuous on the whole interval.", "The endpoint values are 0 and 100.", "The target 64 is strictly between them."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-23", "module": 14, "family": 0, "topic": "Infinite limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 10^-}\\frac{8}{(x-10)^{1}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is 8, which is nonzero.", "The denominator approaches zero negatively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": {"type": "rational", "c": 10, "L": 0, "a": 8, "power": 1, "offset": 0}, "table": null}, {"id": "U1-15-23", "module": 15, "family": 0, "topic": "Asymptotes & multiplicity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the vertical asymptote at x = 8.", "math": "f(x)=\\frac{10}{(x-8)^{2}}", "answer": "Even", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 2.", "The asymptote has even multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-23", "module": 16, "family": 0, "topic": "Rational limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{8 x^{2} + 10}{10 x^{2} + 1}", "answer": "\\frac{4}{5}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{4}{5}$.", "At the specified end, the limit is $\\frac{4}{5}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.8}, {"id": "U1-17-23", "module": 17, "family": 0, "topic": "Radical limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{64 x^{2} + 10}}{x}", "answer": "8", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $8$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-18-23", "module": 18, "family": 0, "topic": "Exponential end behavior", "subtopic": "Recognize", "difficulty": "Easy", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}8 e^{x} + 10", "answer": "10", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 10."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-19-23", "module": 19, "family": 0, "topic": "Domain, holes & restrictions", "subtopic": "Recognize", "difficulty": "Easy", "question": "Select every input excluded from the domain.", "math": "f(x)=\\frac{(x-8)(x+10)}{(x-8)(x+8)}", "answer": ["8", "-8"], "type": "multi", "solutionSteps": ["The original denominator vanishes at ±8.", "Both values are excluded even if a factor later cancels."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Easy"], "options": ["8", "-8", "0", "10"], "graph": null, "table": null}, {"id": "U1-20-23", "module": 20, "family": 0, "topic": "Intercepts & curve sketching", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the x-coordinate of the x-intercept.", "math": "f(x)=\\frac{x - 8}{x + 10}", "answer": "8", "type": "number", "solutionSteps": ["Set the numerator x − 8 equal to zero.", "At x = 8, the denominator is 18, nonzero.", "The x-intercept is (8, 0)."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-21-23", "module": 21, "family": 0, "topic": "Average rate of change", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the average rate of change on [7, 9].", "math": "f(x)=x^{2} + 8", "answer": "16", "type": "number", "solutionSteps": ["The endpoint outputs are 57 and 89.", "The input change is 2.", "Divide the output change by 2 to obtain $16$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 16.0}, {"id": "U1-22-23", "module": 22, "family": 0, "topic": "Estimating instantaneous rates", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the instantaneous rate at x = 10 using the secant on [9.9, 10.1].", "math": "f(x)=8 x^{2} + 10 x", "answer": "170", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{99}{10}$ and $\\frac{101}{10}$.", "The output change is $34$ and the input change is $\\frac{1}{5}$.", "The secant estimate is $170$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 170.0}, {"id": "U1-23-23", "module": 23, "family": 0, "topic": "Squeeze Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}8x^{2}\\sin(1/x)+10", "answer": "10", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 10, both bounds approach 10.", "The Squeeze Theorem gives 10."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-24-23", "module": 24, "family": 0, "topic": "Combining limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x approaches 26, f(x) approaches 8 and g(x) approaches 10. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 26}2f(x)+3g(x)", "answer": "46", "type": "number", "solutionSteps": ["Use the component limits 8 and 10.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $46$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 46.0}, {"id": "U1-25-23", "module": 25, "family": 0, "topic": "Limits of compositions", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x → 10, g(x) → 8. If f(t) = t² + 10, find the limit of f(g(x)).", "math": "", "answer": "74", "type": "number", "solutionSteps": ["The inner output approaches 8.", "The outer polynomial is continuous.", "Evaluate f(8) = 74."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 74.0}, {"id": "U1-01-24", "module": 1, "family": 0, "topic": "Understanding a limit", "subtopic": "Recognize", "difficulty": "Easy", "question": "Near x = 9, both sides of f(x) approach 12, but f(9) = 16. Find the limit.", "math": "\\lim_{x\\to 9}f(x)", "answer": "12", "type": "number", "solutionSteps": ["Nearby values from both sides approach 12.", "The value f(9) = 16 affects the point, not the nearby trend.", "The limit is 12."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-02-24", "module": 2, "family": 0, "topic": "Reading limits from graphs", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the graph to find the two-sided limit.", "math": "\\lim_{x\\to 6}f(x)", "answer": "8", "type": "number", "solutionSteps": ["Both branches approach the open point at (6, 8).", "The filled point is the function value, not the limit.", "The limit is 8."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": {"type": "hole", "c": 6, "L": 8, "value": 11, "m": 1}, "table": null, "numericAnswer": 8.0}, {"id": "U1-03-24", "module": 3, "family": 0, "topic": "One-sided limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 11^-}\\frac{9|x-11|}{x-11}", "answer": "-9", "type": "number", "solutionSteps": ["On this side, x − 11 is negative.", "Replace the absolute value with the negative of its argument.", "Cancel the nonzero factor nearby to get -9."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -9.0}, {"id": "U1-04-24", "module": 4, "family": 0, "topic": "Direct substitution", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 11}9 x + 11", "answer": "110", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 11.", "Simplify to $110$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 110.0}, {"id": "U1-05-24", "module": 5, "family": 0, "topic": "Rational & trigonometric limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 9}\\frac{x + 9}{x^{2} + 11}", "answer": "\\frac{9}{46}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $9$ for x.", "Use exact values and simplify to $\\frac{9}{46}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.1956521739130435}, {"id": "U1-06-24", "module": 6, "family": 0, "topic": "Piecewise limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the two-sided limit at x = 9.", "math": "f(x)=\\begin{cases}x^2+0&x<9\\\\11&x=9\\\\x+72&x>9\\end{cases}", "answer": "81", "type": "number", "solutionSteps": ["The left limit is 81.", "The right limit is 81.", "The two-sided limit is 81; the isolated value 11 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 81.0}, {"id": "U1-07-24", "module": 7, "family": 0, "topic": "The continuity test", "subtopic": "Recognize", "difficulty": "Easy", "question": "At x = 11, the left limit is 9, the right limit is 9, and f(11) is 9. Is f continuous there?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value matches the common limit."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-24", "module": 8, "family": 0, "topic": "Classifying discontinuities", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the discontinuity at x = 9 for this function.", "math": "\\frac{x^{2} - 81}{x - 9}", "answer": "Removable", "type": "choice", "solutionSteps": ["Factor the numerator and cancel x − 9.", "The nearby behavior is the finite value 18.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-24", "module": 9, "family": 0, "topic": "Factoring indeterminate limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 9}\\frac{x^{2} - 81}{x - 9}", "answer": "18", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 9 for nearby x.", "The reduced expression is $x + 9$.", "Substitute x = 9 to obtain $18$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 18.0}, {"id": "U1-10-24", "module": 10, "family": 0, "topic": "Rationalizing limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 81}\\frac{\\sqrt{x} - 9}{x - 81}", "answer": "\\frac{1}{18}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{18}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.05555555555555555}, {"id": "U1-11-24", "module": 11, "family": 0, "topic": "Limits from numerical tables", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the limit as x approaches 9 from the table.", "math": "", "answer": "29", "type": "number", "solutionSteps": ["As inputs approach 9 from the left, outputs approach 29.", "The right-side outputs also approach 29.", "The table suggests a limit of 29."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["8.900", "28.800"], ["8.990", "28.980"], ["8.999", "28.998"], ["9.001", "29.002"], ["9.010", "29.020"], ["9.100", "29.200"]]}, "numericAnswer": 29.0}, {"id": "U1-12-24", "module": 12, "family": 0, "topic": "Making a function continuous", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}\\frac{x^2-81}{x-9}&x\\ne 9\\\\K&x=9\\end{cases}", "answer": "18", "type": "number", "solutionSteps": ["Factor and cancel x − 9.", "The nearby expression is x + 9, with limit 18.", "Set K = 18."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 18.0}, {"id": "U1-13-24", "module": 13, "family": 0, "topic": "Intermediate Value Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "For f(x) = x² on [0, 11], does IVT guarantee an interior point with f(c) = 81?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["A polynomial is continuous on the whole interval.", "The endpoint values are 0 and 121.", "The target 81 is strictly between them."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-24", "module": 14, "family": 0, "topic": "Infinite limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 11^-}\\frac{9}{(x-11)^{1}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is 9, which is nonzero.", "The denominator approaches zero negatively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": {"type": "rational", "c": 11, "L": 0, "a": 9, "power": 1, "offset": 0}, "table": null}, {"id": "U1-15-24", "module": 15, "family": 0, "topic": "Asymptotes & multiplicity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the vertical asymptote at x = 9.", "math": "f(x)=\\frac{11}{(x-9)^{2}}", "answer": "Even", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 2.", "The asymptote has even multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-24", "module": 16, "family": 0, "topic": "Rational limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{9 x^{2} + 11}{11 x^{2} + 1}", "answer": "\\frac{9}{11}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{9}{11}$.", "At the specified end, the limit is $\\frac{9}{11}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.8181818181818182}, {"id": "U1-17-24", "module": 17, "family": 0, "topic": "Radical limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{81 x^{2} + 11}}{x}", "answer": "9", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $9$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-18-24", "module": 18, "family": 0, "topic": "Exponential end behavior", "subtopic": "Recognize", "difficulty": "Easy", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}9 e^{x} + 11", "answer": "11", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 11."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 11.0}, {"id": "U1-19-24", "module": 19, "family": 0, "topic": "Domain, holes & restrictions", "subtopic": "Recognize", "difficulty": "Easy", "question": "Select every input excluded from the domain.", "math": "f(x)=\\frac{(x-9)(x+11)}{(x-9)(x+9)}", "answer": ["9", "-9"], "type": "multi", "solutionSteps": ["The original denominator vanishes at ±9.", "Both values are excluded even if a factor later cancels."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Easy"], "options": ["9", "-9", "0", "11"], "graph": null, "table": null}, {"id": "U1-20-24", "module": 20, "family": 0, "topic": "Intercepts & curve sketching", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the x-coordinate of the x-intercept.", "math": "f(x)=\\frac{x - 9}{x + 11}", "answer": "9", "type": "number", "solutionSteps": ["Set the numerator x − 9 equal to zero.", "At x = 9, the denominator is 20, nonzero.", "The x-intercept is (9, 0)."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-21-24", "module": 21, "family": 0, "topic": "Average rate of change", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the average rate of change on [8, 10].", "math": "f(x)=x^{2} + 9", "answer": "18", "type": "number", "solutionSteps": ["The endpoint outputs are 73 and 109.", "The input change is 2.", "Divide the output change by 2 to obtain $18$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 18.0}, {"id": "U1-22-24", "module": 22, "family": 0, "topic": "Estimating instantaneous rates", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the instantaneous rate at x = 11 using the secant on [10.9, 11.1].", "math": "f(x)=9 x^{2} + 11 x", "answer": "209", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{109}{10}$ and $\\frac{111}{10}$.", "The output change is $\\frac{209}{5}$ and the input change is $\\frac{1}{5}$.", "The secant estimate is $209$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 209.0}, {"id": "U1-23-24", "module": 23, "family": 0, "topic": "Squeeze Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}9x^{2}\\sin(1/x)+11", "answer": "11", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 11, both bounds approach 11.", "The Squeeze Theorem gives 11."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 11.0}, {"id": "U1-24-24", "module": 24, "family": 0, "topic": "Combining limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x approaches 29, f(x) approaches 9 and g(x) approaches 11. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 29}2f(x)+3g(x)", "answer": "51", "type": "number", "solutionSteps": ["Use the component limits 9 and 11.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $51$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 51.0}, {"id": "U1-25-24", "module": 25, "family": 0, "topic": "Limits of compositions", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x → 11, g(x) → 9. If f(t) = t² + 11, find the limit of f(g(x)).", "math": "", "answer": "92", "type": "number", "solutionSteps": ["The inner output approaches 9.", "The outer polynomial is continuous.", "Evaluate f(9) = 92."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 92.0}, {"id": "U1-01-25", "module": 1, "family": 0, "topic": "Understanding a limit", "subtopic": "Recognize", "difficulty": "Easy", "question": "Near x = 10, both sides of f(x) approach 13, but f(10) = 17. Find the limit.", "math": "\\lim_{x\\to 10}f(x)", "answer": "13", "type": "number", "solutionSteps": ["Nearby values from both sides approach 13.", "The value f(10) = 17 affects the point, not the nearby trend.", "The limit is 13."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 13.0}, {"id": "U1-02-25", "module": 2, "family": 0, "topic": "Reading limits from graphs", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the graph to find the two-sided limit.", "math": "\\lim_{x\\to 7}f(x)", "answer": "9", "type": "number", "solutionSteps": ["Both branches approach the open point at (7, 9).", "The filled point is the function value, not the limit.", "The limit is 9."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": {"type": "hole", "c": 7, "L": 9, "value": 12, "m": 1}, "table": null, "numericAnswer": 9.0}, {"id": "U1-03-25", "module": 3, "family": 0, "topic": "One-sided limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 12^-}\\frac{10|x-12|}{x-12}", "answer": "-10", "type": "number", "solutionSteps": ["On this side, x − 12 is negative.", "Replace the absolute value with the negative of its argument.", "Cancel the nonzero factor nearby to get -10."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -10.0}, {"id": "U1-04-25", "module": 4, "family": 0, "topic": "Direct substitution", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 12}10 x + 12", "answer": "132", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 12.", "Simplify to $132$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 132.0}, {"id": "U1-05-25", "module": 5, "family": 0, "topic": "Rational & trigonometric limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 10}\\frac{x + 10}{x^{2} + 12}", "answer": "\\frac{5}{28}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $10$ for x.", "Use exact values and simplify to $\\frac{5}{28}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.17857142857142858}, {"id": "U1-06-25", "module": 6, "family": 0, "topic": "Piecewise limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the two-sided limit at x = 10.", "math": "f(x)=\\begin{cases}x^2+0&x<10\\\\12&x=10\\\\x+90&x>10\\end{cases}", "answer": "100", "type": "number", "solutionSteps": ["The left limit is 100.", "The right limit is 100.", "The two-sided limit is 100; the isolated value 12 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 100.0}, {"id": "U1-07-25", "module": 7, "family": 0, "topic": "The continuity test", "subtopic": "Recognize", "difficulty": "Easy", "question": "At x = 12, the left limit is 10, the right limit is 10, and f(12) is 10. Is f continuous there?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value matches the common limit."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-25", "module": 8, "family": 0, "topic": "Classifying discontinuities", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the discontinuity at x = 10 for this function.", "math": "\\frac{x^{2} - 100}{x - 10}", "answer": "Removable", "type": "choice", "solutionSteps": ["Factor the numerator and cancel x − 10.", "The nearby behavior is the finite value 20.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-25", "module": 9, "family": 0, "topic": "Factoring indeterminate limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 10}\\frac{x^{2} - 100}{x - 10}", "answer": "20", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 10 for nearby x.", "The reduced expression is $x + 10$.", "Substitute x = 10 to obtain $20$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 20.0}, {"id": "U1-10-25", "module": 10, "family": 0, "topic": "Rationalizing limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 100}\\frac{\\sqrt{x} - 10}{x - 100}", "answer": "\\frac{1}{20}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{20}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.05}, {"id": "U1-11-25", "module": 11, "family": 0, "topic": "Limits from numerical tables", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the limit as x approaches 10 from the table.", "math": "", "answer": "32", "type": "number", "solutionSteps": ["As inputs approach 10 from the left, outputs approach 32.", "The right-side outputs also approach 32.", "The table suggests a limit of 32."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["9.900", "31.800"], ["9.990", "31.980"], ["9.999", "31.998"], ["10.001", "32.002"], ["10.010", "32.020"], ["10.100", "32.200"]]}, "numericAnswer": 32.0}, {"id": "U1-12-25", "module": 12, "family": 0, "topic": "Making a function continuous", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}\\frac{x^2-100}{x-10}&x\\ne 10\\\\K&x=10\\end{cases}", "answer": "20", "type": "number", "solutionSteps": ["Factor and cancel x − 10.", "The nearby expression is x + 10, with limit 20.", "Set K = 20."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 20.0}, {"id": "U1-13-25", "module": 13, "family": 0, "topic": "Intermediate Value Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "For f(x) = x² on [0, 12], does IVT guarantee an interior point with f(c) = 100?", "math": "", "answer": "Yes", "type": "choice", "solutionSteps": ["A polynomial is continuous on the whole interval.", "The endpoint values are 0 and 144.", "The target 100 is strictly between them."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-25", "module": 14, "family": 0, "topic": "Infinite limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 12^-}\\frac{10}{(x-12)^{1}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is 10, which is nonzero.", "The denominator approaches zero negatively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": {"type": "rational", "c": 12, "L": 0, "a": 10, "power": 1, "offset": 0}, "table": null}, {"id": "U1-15-25", "module": 15, "family": 0, "topic": "Asymptotes & multiplicity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Classify the vertical asymptote at x = 10.", "math": "f(x)=\\frac{12}{(x-10)^{2}}", "answer": "Even", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 2.", "The asymptote has even multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-25", "module": 16, "family": 0, "topic": "Rational limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{10 x^{2} + 12}{12 x^{2} + 1}", "answer": "\\frac{5}{6}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{5}{6}$.", "At the specified end, the limit is $\\frac{5}{6}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.8333333333333334}, {"id": "U1-17-25", "module": 17, "family": 0, "topic": "Radical limits at infinity", "subtopic": "Recognize", "difficulty": "Easy", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{100 x^{2} + 12}}{x}", "answer": "10", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $10$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-18-25", "module": 18, "family": 0, "topic": "Exponential end behavior", "subtopic": "Recognize", "difficulty": "Easy", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}10 e^{x} + 12", "answer": "12", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 12."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-19-25", "module": 19, "family": 0, "topic": "Domain, holes & restrictions", "subtopic": "Recognize", "difficulty": "Easy", "question": "Select every input excluded from the domain.", "math": "f(x)=\\frac{(x-10)(x+12)}{(x-10)(x+10)}", "answer": ["10", "-10"], "type": "multi", "solutionSteps": ["The original denominator vanishes at ±10.", "Both values are excluded even if a factor later cancels."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Easy"], "options": ["10", "-10", "0", "12"], "graph": null, "table": null}, {"id": "U1-20-25", "module": 20, "family": 0, "topic": "Intercepts & curve sketching", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the x-coordinate of the x-intercept.", "math": "f(x)=\\frac{x - 10}{x + 12}", "answer": "10", "type": "number", "solutionSteps": ["Set the numerator x − 10 equal to zero.", "At x = 10, the denominator is 22, nonzero.", "The x-intercept is (10, 0)."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-21-25", "module": 21, "family": 0, "topic": "Average rate of change", "subtopic": "Recognize", "difficulty": "Easy", "question": "Find the average rate of change on [9, 11].", "math": "f(x)=x^{2} + 10", "answer": "20", "type": "number", "solutionSteps": ["The endpoint outputs are 91 and 131.", "The input change is 2.", "Divide the output change by 2 to obtain $20$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 20.0}, {"id": "U1-22-25", "module": 22, "family": 0, "topic": "Estimating instantaneous rates", "subtopic": "Recognize", "difficulty": "Easy", "question": "Estimate the instantaneous rate at x = 12 using the secant on [11.9, 12.1].", "math": "f(x)=10 x^{2} + 12 x", "answer": "252", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{119}{10}$ and $\\frac{121}{10}$.", "The output change is $\\frac{252}{5}$ and the input change is $\\frac{1}{5}$.", "The secant estimate is $252$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 252.0}, {"id": "U1-23-25", "module": 23, "family": 0, "topic": "Squeeze Theorem", "subtopic": "Recognize", "difficulty": "Easy", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}10x^{2}\\sin(1/x)+12", "answer": "12", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 12, both bounds approach 12.", "The Squeeze Theorem gives 12."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-24-25", "module": 24, "family": 0, "topic": "Combining limits", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x approaches 32, f(x) approaches 10 and g(x) approaches 12. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 32}2f(x)+3g(x)", "answer": "56", "type": "number", "solutionSteps": ["Use the component limits 10 and 12.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $56$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 56.0}, {"id": "U1-25-25", "module": 25, "family": 0, "topic": "Limits of compositions", "subtopic": "Recognize", "difficulty": "Easy", "question": "As x → 12, g(x) → 10. If f(t) = t² + 12, find the limit of f(g(x)).", "math": "", "answer": "112", "type": "number", "solutionSteps": ["The inner output approaches 10.", "The outer polynomial is continuous.", "Evaluate f(10) = 112."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 112.0}, {"id": "U1-01-26", "module": 1, "family": 1, "topic": "Understanding a limit", "subtopic": "Apply", "difficulty": "Easy", "question": "The left limit is 6 and the right limit is 8. Find the two-sided limit.", "math": "\\lim_{x\\to 9}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left side approaches 6.", "The right side approaches 8.", "The sides differ, so the two-sided limit does not exist."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Easy"], "options": ["DNE", "6", "8", "9"], "graph": null, "table": null}, {"id": "U1-02-26", "module": 2, "family": 1, "topic": "Reading limits from graphs", "subtopic": "Apply", "difficulty": "Easy", "question": "Use the filled point to find f(3).", "math": "", "answer": "8", "type": "number", "solutionSteps": ["Locate x = 3.", "The closed point has height 8.", "f(3) = 8."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": {"type": "hole", "c": 3, "L": 5, "value": 8, "m": 1}, "table": null, "numericAnswer": 8.0}, {"id": "U1-03-26", "module": 3, "family": 1, "topic": "One-sided limits", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 8^+}\\frac{6|x-8|}{x-8}", "answer": "6", "type": "number", "solutionSteps": ["On this side, x − 8 is positive.", "Replace the absolute value with its argument.", "Cancel the nonzero factor nearby to get 6."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-04-26", "module": 4, "family": 1, "topic": "Direct substitution", "subtopic": "Apply", "difficulty": "Easy", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to -6}x^{2} - 6 x + 8", "answer": "80", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = -6.", "Simplify to $80$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 80.0}, {"id": "U1-05-26", "module": 5, "family": 1, "topic": "Rational & trigonometric limits", "subtopic": "Apply", "difficulty": "Easy", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 0}\\sin{\\left(x \\right)} + 6 \\cos{\\left(x \\right)}", "answer": "6", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $0$ for x.", "Use exact values and simplify to $6$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-06-26", "module": 6, "family": 1, "topic": "Piecewise limits", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the two-sided limit at x = 6.", "math": "f(x)=\\begin{cases}x^2+2&x<6\\\\9&x=6\\\\x+33&x>6\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 38.", "The right limit is 39.", "The two-sided limit is DNE; the isolated value 9 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Easy"], "options": ["DNE", "38", "39", "9"], "graph": null, "table": null}, {"id": "U1-07-26", "module": 7, "family": 1, "topic": "The continuity test", "subtopic": "Apply", "difficulty": "Easy", "question": "At x = 8, the left limit is 6, the right limit is 6, and f(8) is 8. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-26", "module": 8, "family": 1, "topic": "Classifying discontinuities", "subtopic": "Apply", "difficulty": "Easy", "question": "Classify the discontinuity at x = 6 for this function.", "math": "\\frac{1}{\\left(x - 6\\right)^{2}}", "answer": "Infinite", "type": "choice", "solutionSteps": ["The squared denominator approaches zero positively.", "The nearby behavior is unbounded.", "This is a infinite discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-26", "module": 9, "family": 1, "topic": "Factoring indeterminate limits", "subtopic": "Apply", "difficulty": "Easy", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 6}\\frac{x^{3} - 216}{x - 6}", "answer": "108", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 6 for nearby x.", "The reduced expression is $x^{2} + 6 x + 36$.", "Substitute x = 6 to obtain $108$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 108.0}, {"id": "U1-10-26", "module": 10, "family": 1, "topic": "Rationalizing limits", "subtopic": "Apply", "difficulty": "Easy", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 36}\\frac{x - 36}{\\sqrt{x} - 6}", "answer": "12", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $12$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-11-26", "module": 11, "family": 1, "topic": "Limits from numerical tables", "subtopic": "Apply", "difficulty": "Easy", "question": "Does this finite table prove the limit at x = 6 with absolute certainty?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Only finitely many values are shown.", "Unsampled values could behave differently.", "The table provides evidence, not a proof."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["5.900", "19.800"], ["5.990", "19.980"], ["5.999", "19.998"], ["6.001", "20.002"], ["6.010", "20.020"], ["6.100", "20.200"]]}}, {"id": "U1-12-26", "module": 12, "family": 1, "topic": "Making a function continuous", "subtopic": "Apply", "difficulty": "Easy", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2&x<6\\\\x+K&x\\ge 6\\end{cases}", "answer": "30", "type": "number", "solutionSteps": ["The left limit is 36.", "The right limit and point value are 6 + K.", "Solve 6 + K = 36, giving K = 30."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 30.0}, {"id": "U1-13-26", "module": 13, "family": 1, "topic": "Intermediate Value Theorem", "subtopic": "Apply", "difficulty": "Easy", "question": "For f(x) = 1/(x − 6) on [5, 7], does IVT apply across the entire interval?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["The denominator is zero at 6.", "This point lies inside the interval.", "Continuity on the full closed interval fails."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Easy"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-26", "module": 14, "family": 1, "topic": "Infinite limits", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 8^+}\\frac{6}{(x-8)^{1}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 6, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": {"type": "rational", "c": 8, "L": 0, "a": 6, "power": 1, "offset": 0}, "table": null}, {"id": "U1-15-26", "module": 15, "family": 1, "topic": "Asymptotes & multiplicity", "subtopic": "Apply", "difficulty": "Easy", "question": "Classify the vertical asymptote at x = 6.", "math": "f(x)=\\frac{8}{(x-6)^{3}}", "answer": "Odd", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 3.", "The asymptote has odd multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Easy"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-26", "module": 16, "family": 1, "topic": "Rational limits at infinity", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{6 x + 8}{x^{2} + 1}", "answer": "0", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{6}{x}$.", "At the specified end, the limit is $0$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-17-26", "module": 17, "family": 1, "topic": "Radical limits at infinity", "subtopic": "Apply", "difficulty": "Easy", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{36 x^{2} + 8}}{x}", "answer": "-6", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $-6$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -6.0}, {"id": "U1-18-26", "module": 18, "family": 1, "topic": "Exponential end behavior", "subtopic": "Apply", "difficulty": "Easy", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}6 + e^{- x}", "answer": "6", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 6."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-19-26", "module": 19, "family": 1, "topic": "Domain, holes & restrictions", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the y-coordinate of the hole at x = 6.", "math": "f(x)=\\frac{(x-6)(x+8)}{(x-6)(x+6)}", "answer": "\\frac{7}{6}", "type": "number", "solutionSteps": ["Cancel x − 6.", "Evaluate (x + 8)/(x + 6) at x = 6.", "The hole has height $\\frac{7}{6}$."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 1.1666666666666667}, {"id": "U1-20-26", "module": 20, "family": 1, "topic": "Intercepts & curve sketching", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the y-coordinate of the y-intercept.", "math": "f(x)=\\frac{x - 6}{x + 8}", "answer": "- \\frac{3}{4}", "type": "number", "solutionSteps": ["Set x = 0.", "The numerator is −6 and denominator is 8.", "The y-intercept has height $- \\frac{3}{4}$."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": -0.75}, {"id": "U1-21-26", "module": 21, "family": 1, "topic": "Average rate of change", "subtopic": "Apply", "difficulty": "Easy", "question": "Find the average rate of change on [5, 7].", "math": "f(x)=6 x^{3} - 8 x", "answer": "646", "type": "number", "solutionSteps": ["The endpoint outputs are 710 and 2002.", "The input change is 2.", "Divide the output change by 2 to obtain $646$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 646.0}, {"id": "U1-22-26", "module": 22, "family": 1, "topic": "Estimating instantaneous rates", "subtopic": "Apply", "difficulty": "Easy", "question": "Estimate the instantaneous rate at x = 8 using the secant on [7.99, 8.01].", "math": "f(x)=6 x^{2} + 8 x", "answer": "104", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{799}{100}$ and $\\frac{801}{100}$.", "The output change is $\\frac{52}{25}$ and the input change is $\\frac{1}{50}$.", "The secant estimate is $104$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 104.0}, {"id": "U1-23-26", "module": 23, "family": 1, "topic": "Squeeze Theorem", "subtopic": "Apply", "difficulty": "Easy", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}6x^{4}\\sin(1/x)+8", "answer": "8", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 8, both bounds approach 8.", "The Squeeze Theorem gives 8."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-24-26", "module": 24, "family": 1, "topic": "Combining limits", "subtopic": "Apply", "difficulty": "Easy", "question": "As x approaches 20, f(x) approaches 6 and g(x) approaches 8. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 20}f(x)g(x)", "answer": "48", "type": "number", "solutionSteps": ["Use the component limits 6 and 8.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $48$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 48.0}, {"id": "U1-25-26", "module": 25, "family": 1, "topic": "Limits of compositions", "subtopic": "Apply", "difficulty": "Easy", "question": "Let f(t) = 6 for t < 8, f(t) = 11 for t > 8, and f(8) = 99. If g(x) = 8 − x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "6", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) < 8.", "The inner output approaches the boundary from below.", "The outer left branch is always 6."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Easy"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-01-27", "module": 1, "family": 1, "topic": "Understanding a limit", "subtopic": "Apply", "difficulty": "Medium", "question": "The left limit is 7 and the right limit is 9. Find the two-sided limit.", "math": "\\lim_{x\\to 10}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left side approaches 7.", "The right side approaches 9.", "The sides differ, so the two-sided limit does not exist."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "7", "9", "10"], "graph": null, "table": null}, {"id": "U1-02-27", "module": 2, "family": 1, "topic": "Reading limits from graphs", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the filled point to find f(4).", "math": "", "answer": "9", "type": "number", "solutionSteps": ["Locate x = 4.", "The closed point has height 9.", "f(4) = 9."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": {"type": "hole", "c": 4, "L": 6, "value": 9, "m": 1}, "table": null, "numericAnswer": 9.0}, {"id": "U1-03-27", "module": 3, "family": 1, "topic": "One-sided limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 9^+}\\frac{7|x-9|}{x-9}", "answer": "7", "type": "number", "solutionSteps": ["On this side, x − 9 is positive.", "Replace the absolute value with its argument.", "Cancel the nonzero factor nearby to get 7."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-04-27", "module": 4, "family": 1, "topic": "Direct substitution", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to -7}x^{2} - 7 x + 9", "answer": "107", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = -7.", "Simplify to $107$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 107.0}, {"id": "U1-05-27", "module": 5, "family": 1, "topic": "Rational & trigonometric limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 0}\\sin{\\left(x \\right)} + 7 \\cos{\\left(x \\right)}", "answer": "7", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $0$ for x.", "Use exact values and simplify to $7$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-06-27", "module": 6, "family": 1, "topic": "Piecewise limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the two-sided limit at x = 7.", "math": "f(x)=\\begin{cases}x^2+2&x<7\\\\10&x=7\\\\x+45&x>7\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 51.", "The right limit is 52.", "The two-sided limit is DNE; the isolated value 10 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "51", "52", "10"], "graph": null, "table": null}, {"id": "U1-07-27", "module": 7, "family": 1, "topic": "The continuity test", "subtopic": "Apply", "difficulty": "Medium", "question": "At x = 9, the left limit is 7, the right limit is 7, and f(9) is 9. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-27", "module": 8, "family": 1, "topic": "Classifying discontinuities", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the discontinuity at x = 7 for this function.", "math": "\\frac{1}{\\left(x - 7\\right)^{2}}", "answer": "Infinite", "type": "choice", "solutionSteps": ["The squared denominator approaches zero positively.", "The nearby behavior is unbounded.", "This is a infinite discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-27", "module": 9, "family": 1, "topic": "Factoring indeterminate limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 7}\\frac{x^{3} - 343}{x - 7}", "answer": "147", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 7 for nearby x.", "The reduced expression is $x^{2} + 7 x + 49$.", "Substitute x = 7 to obtain $147$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 147.0}, {"id": "U1-10-27", "module": 10, "family": 1, "topic": "Rationalizing limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 49}\\frac{x - 49}{\\sqrt{x} - 7}", "answer": "14", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $14$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 14.0}, {"id": "U1-11-27", "module": 11, "family": 1, "topic": "Limits from numerical tables", "subtopic": "Apply", "difficulty": "Medium", "question": "Does this finite table prove the limit at x = 7 with absolute certainty?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Only finitely many values are shown.", "Unsampled values could behave differently.", "The table provides evidence, not a proof."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["6.900", "22.800"], ["6.990", "22.980"], ["6.999", "22.998"], ["7.001", "23.002"], ["7.010", "23.020"], ["7.100", "23.200"]]}}, {"id": "U1-12-27", "module": 12, "family": 1, "topic": "Making a function continuous", "subtopic": "Apply", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2&x<7\\\\x+K&x\\ge 7\\end{cases}", "answer": "42", "type": "number", "solutionSteps": ["The left limit is 49.", "The right limit and point value are 7 + K.", "Solve 7 + K = 49, giving K = 42."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 42.0}, {"id": "U1-13-27", "module": 13, "family": 1, "topic": "Intermediate Value Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "For f(x) = 1/(x − 7) on [6, 8], does IVT apply across the entire interval?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["The denominator is zero at 7.", "This point lies inside the interval.", "Continuity on the full closed interval fails."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-27", "module": 14, "family": 1, "topic": "Infinite limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 9^+}\\frac{7}{(x-9)^{1}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 7, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-27", "module": 15, "family": 1, "topic": "Asymptotes & multiplicity", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the vertical asymptote at x = 7.", "math": "f(x)=\\frac{9}{(x-7)^{3}}", "answer": "Odd", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 3.", "The asymptote has odd multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-27", "module": 16, "family": 1, "topic": "Rational limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{7 x + 9}{x^{2} + 1}", "answer": "0", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{7}{x}$.", "At the specified end, the limit is $0$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-17-27", "module": 17, "family": 1, "topic": "Radical limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{49 x^{2} + 9}}{x}", "answer": "-7", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $-7$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -7.0}, {"id": "U1-18-27", "module": 18, "family": 1, "topic": "Exponential end behavior", "subtopic": "Apply", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}7 + e^{- x}", "answer": "7", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 7."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-19-27", "module": 19, "family": 1, "topic": "Domain, holes & restrictions", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the hole at x = 7.", "math": "f(x)=\\frac{(x-7)(x+9)}{(x-7)(x+7)}", "answer": "\\frac{8}{7}", "type": "number", "solutionSteps": ["Cancel x − 7.", "Evaluate (x + 9)/(x + 7) at x = 7.", "The hole has height $\\frac{8}{7}$."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.1428571428571428}, {"id": "U1-20-27", "module": 20, "family": 1, "topic": "Intercepts & curve sketching", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the y-intercept.", "math": "f(x)=\\frac{x - 7}{x + 9}", "answer": "- \\frac{7}{9}", "type": "number", "solutionSteps": ["Set x = 0.", "The numerator is −7 and denominator is 9.", "The y-intercept has height $- \\frac{7}{9}$."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -0.7777777777777778}, {"id": "U1-21-27", "module": 21, "family": 1, "topic": "Average rate of change", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the average rate of change on [6, 8].", "math": "f(x)=7 x^{3} - 9 x", "answer": "1027", "type": "number", "solutionSteps": ["The endpoint outputs are 1458 and 3512.", "The input change is 2.", "Divide the output change by 2 to obtain $1027$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1027.0}, {"id": "U1-22-27", "module": 22, "family": 1, "topic": "Estimating instantaneous rates", "subtopic": "Apply", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 9 using the secant on [8.99, 9.01].", "math": "f(x)=7 x^{2} + 9 x", "answer": "135", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{899}{100}$ and $\\frac{901}{100}$.", "The output change is $\\frac{27}{10}$ and the input change is $\\frac{1}{50}$.", "The secant estimate is $135$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 135.0}, {"id": "U1-23-27", "module": 23, "family": 1, "topic": "Squeeze Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}7x^{4}\\sin(1/x)+9", "answer": "9", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 9, both bounds approach 9.", "The Squeeze Theorem gives 9."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-24-27", "module": 24, "family": 1, "topic": "Combining limits", "subtopic": "Apply", "difficulty": "Medium", "question": "As x approaches 23, f(x) approaches 7 and g(x) approaches 9. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 23}f(x)g(x)", "answer": "63", "type": "number", "solutionSteps": ["Use the component limits 7 and 9.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $63$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 63.0}, {"id": "U1-25-27", "module": 25, "family": 1, "topic": "Limits of compositions", "subtopic": "Apply", "difficulty": "Medium", "question": "Let f(t) = 7 for t < 9, f(t) = 12 for t > 9, and f(9) = 99. If g(x) = 9 − x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "7", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) < 9.", "The inner output approaches the boundary from below.", "The outer left branch is always 7."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-01-28", "module": 1, "family": 1, "topic": "Understanding a limit", "subtopic": "Apply", "difficulty": "Medium", "question": "The left limit is 8 and the right limit is 10. Find the two-sided limit.", "math": "\\lim_{x\\to 11}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left side approaches 8.", "The right side approaches 10.", "The sides differ, so the two-sided limit does not exist."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "8", "10", "11"], "graph": null, "table": null}, {"id": "U1-02-28", "module": 2, "family": 1, "topic": "Reading limits from graphs", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the filled point to find f(5).", "math": "", "answer": "10", "type": "number", "solutionSteps": ["Locate x = 5.", "The closed point has height 10.", "f(5) = 10."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": {"type": "hole", "c": 5, "L": 7, "value": 10, "m": 1}, "table": null, "numericAnswer": 10.0}, {"id": "U1-03-28", "module": 3, "family": 1, "topic": "One-sided limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 10^+}\\frac{8|x-10|}{x-10}", "answer": "8", "type": "number", "solutionSteps": ["On this side, x − 10 is positive.", "Replace the absolute value with its argument.", "Cancel the nonzero factor nearby to get 8."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-04-28", "module": 4, "family": 1, "topic": "Direct substitution", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to -8}x^{2} - 8 x + 10", "answer": "138", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = -8.", "Simplify to $138$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 138.0}, {"id": "U1-05-28", "module": 5, "family": 1, "topic": "Rational & trigonometric limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 0}\\sin{\\left(x \\right)} + 8 \\cos{\\left(x \\right)}", "answer": "8", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $0$ for x.", "Use exact values and simplify to $8$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-06-28", "module": 6, "family": 1, "topic": "Piecewise limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the two-sided limit at x = 8.", "math": "f(x)=\\begin{cases}x^2+2&x<8\\\\11&x=8\\\\x+59&x>8\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 66.", "The right limit is 67.", "The two-sided limit is DNE; the isolated value 11 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "66", "67", "11"], "graph": null, "table": null}, {"id": "U1-07-28", "module": 7, "family": 1, "topic": "The continuity test", "subtopic": "Apply", "difficulty": "Medium", "question": "At x = 10, the left limit is 8, the right limit is 8, and f(10) is 10. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-28", "module": 8, "family": 1, "topic": "Classifying discontinuities", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the discontinuity at x = 8 for this function.", "math": "\\frac{1}{\\left(x - 8\\right)^{2}}", "answer": "Infinite", "type": "choice", "solutionSteps": ["The squared denominator approaches zero positively.", "The nearby behavior is unbounded.", "This is a infinite discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-28", "module": 9, "family": 1, "topic": "Factoring indeterminate limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 8}\\frac{x^{3} - 512}{x - 8}", "answer": "192", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 8 for nearby x.", "The reduced expression is $x^{2} + 8 x + 64$.", "Substitute x = 8 to obtain $192$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 192.0}, {"id": "U1-10-28", "module": 10, "family": 1, "topic": "Rationalizing limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 64}\\frac{x - 64}{\\sqrt{x} - 8}", "answer": "16", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $16$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 16.0}, {"id": "U1-11-28", "module": 11, "family": 1, "topic": "Limits from numerical tables", "subtopic": "Apply", "difficulty": "Medium", "question": "Does this finite table prove the limit at x = 8 with absolute certainty?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Only finitely many values are shown.", "Unsampled values could behave differently.", "The table provides evidence, not a proof."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["7.900", "25.800"], ["7.990", "25.980"], ["7.999", "25.998"], ["8.001", "26.002"], ["8.010", "26.020"], ["8.100", "26.200"]]}}, {"id": "U1-12-28", "module": 12, "family": 1, "topic": "Making a function continuous", "subtopic": "Apply", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2&x<8\\\\x+K&x\\ge 8\\end{cases}", "answer": "56", "type": "number", "solutionSteps": ["The left limit is 64.", "The right limit and point value are 8 + K.", "Solve 8 + K = 64, giving K = 56."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 56.0}, {"id": "U1-13-28", "module": 13, "family": 1, "topic": "Intermediate Value Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "For f(x) = 1/(x − 8) on [7, 9], does IVT apply across the entire interval?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["The denominator is zero at 8.", "This point lies inside the interval.", "Continuity on the full closed interval fails."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-28", "module": 14, "family": 1, "topic": "Infinite limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 10^+}\\frac{8}{(x-10)^{1}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 8, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-28", "module": 15, "family": 1, "topic": "Asymptotes & multiplicity", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the vertical asymptote at x = 8.", "math": "f(x)=\\frac{10}{(x-8)^{3}}", "answer": "Odd", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 3.", "The asymptote has odd multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-28", "module": 16, "family": 1, "topic": "Rational limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{8 x + 10}{x^{2} + 1}", "answer": "0", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{8}{x}$.", "At the specified end, the limit is $0$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-17-28", "module": 17, "family": 1, "topic": "Radical limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{64 x^{2} + 10}}{x}", "answer": "-8", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $-8$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -8.0}, {"id": "U1-18-28", "module": 18, "family": 1, "topic": "Exponential end behavior", "subtopic": "Apply", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}8 + e^{- x}", "answer": "8", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 8."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-19-28", "module": 19, "family": 1, "topic": "Domain, holes & restrictions", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the hole at x = 8.", "math": "f(x)=\\frac{(x-8)(x+10)}{(x-8)(x+8)}", "answer": "\\frac{9}{8}", "type": "number", "solutionSteps": ["Cancel x − 8.", "Evaluate (x + 10)/(x + 8) at x = 8.", "The hole has height $\\frac{9}{8}$."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.125}, {"id": "U1-20-28", "module": 20, "family": 1, "topic": "Intercepts & curve sketching", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the y-intercept.", "math": "f(x)=\\frac{x - 8}{x + 10}", "answer": "- \\frac{4}{5}", "type": "number", "solutionSteps": ["Set x = 0.", "The numerator is −8 and denominator is 10.", "The y-intercept has height $- \\frac{4}{5}$."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -0.8}, {"id": "U1-21-28", "module": 21, "family": 1, "topic": "Average rate of change", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the average rate of change on [7, 9].", "math": "f(x)=8 x^{3} - 10 x", "answer": "1534", "type": "number", "solutionSteps": ["The endpoint outputs are 2674 and 5742.", "The input change is 2.", "Divide the output change by 2 to obtain $1534$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1534.0}, {"id": "U1-22-28", "module": 22, "family": 1, "topic": "Estimating instantaneous rates", "subtopic": "Apply", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 10 using the secant on [9.99, 10.01].", "math": "f(x)=8 x^{2} + 10 x", "answer": "170", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{999}{100}$ and $\\frac{1001}{100}$.", "The output change is $\\frac{17}{5}$ and the input change is $\\frac{1}{50}$.", "The secant estimate is $170$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 170.0}, {"id": "U1-23-28", "module": 23, "family": 1, "topic": "Squeeze Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}8x^{4}\\sin(1/x)+10", "answer": "10", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 10, both bounds approach 10.", "The Squeeze Theorem gives 10."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-24-28", "module": 24, "family": 1, "topic": "Combining limits", "subtopic": "Apply", "difficulty": "Medium", "question": "As x approaches 26, f(x) approaches 8 and g(x) approaches 10. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 26}f(x)g(x)", "answer": "80", "type": "number", "solutionSteps": ["Use the component limits 8 and 10.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $80$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 80.0}, {"id": "U1-25-28", "module": 25, "family": 1, "topic": "Limits of compositions", "subtopic": "Apply", "difficulty": "Medium", "question": "Let f(t) = 8 for t < 10, f(t) = 13 for t > 10, and f(10) = 99. If g(x) = 10 − x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "8", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) < 10.", "The inner output approaches the boundary from below.", "The outer left branch is always 8."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-01-29", "module": 1, "family": 1, "topic": "Understanding a limit", "subtopic": "Apply", "difficulty": "Medium", "question": "The left limit is 9 and the right limit is 11. Find the two-sided limit.", "math": "\\lim_{x\\to 12}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left side approaches 9.", "The right side approaches 11.", "The sides differ, so the two-sided limit does not exist."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "9", "11", "12"], "graph": null, "table": null}, {"id": "U1-02-29", "module": 2, "family": 1, "topic": "Reading limits from graphs", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the filled point to find f(6).", "math": "", "answer": "11", "type": "number", "solutionSteps": ["Locate x = 6.", "The closed point has height 11.", "f(6) = 11."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": {"type": "hole", "c": 6, "L": 8, "value": 11, "m": 1}, "table": null, "numericAnswer": 11.0}, {"id": "U1-03-29", "module": 3, "family": 1, "topic": "One-sided limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 11^+}\\frac{9|x-11|}{x-11}", "answer": "9", "type": "number", "solutionSteps": ["On this side, x − 11 is positive.", "Replace the absolute value with its argument.", "Cancel the nonzero factor nearby to get 9."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-04-29", "module": 4, "family": 1, "topic": "Direct substitution", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to -9}x^{2} - 9 x + 11", "answer": "173", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = -9.", "Simplify to $173$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 173.0}, {"id": "U1-05-29", "module": 5, "family": 1, "topic": "Rational & trigonometric limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 0}\\sin{\\left(x \\right)} + 9 \\cos{\\left(x \\right)}", "answer": "9", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $0$ for x.", "Use exact values and simplify to $9$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-06-29", "module": 6, "family": 1, "topic": "Piecewise limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the two-sided limit at x = 9.", "math": "f(x)=\\begin{cases}x^2+2&x<9\\\\12&x=9\\\\x+75&x>9\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 83.", "The right limit is 84.", "The two-sided limit is DNE; the isolated value 12 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "83", "84", "12"], "graph": null, "table": null}, {"id": "U1-07-29", "module": 7, "family": 1, "topic": "The continuity test", "subtopic": "Apply", "difficulty": "Medium", "question": "At x = 11, the left limit is 9, the right limit is 9, and f(11) is 11. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-29", "module": 8, "family": 1, "topic": "Classifying discontinuities", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the discontinuity at x = 9 for this function.", "math": "\\frac{1}{\\left(x - 9\\right)^{2}}", "answer": "Infinite", "type": "choice", "solutionSteps": ["The squared denominator approaches zero positively.", "The nearby behavior is unbounded.", "This is a infinite discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-29", "module": 9, "family": 1, "topic": "Factoring indeterminate limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 9}\\frac{x^{3} - 729}{x - 9}", "answer": "243", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 9 for nearby x.", "The reduced expression is $x^{2} + 9 x + 81$.", "Substitute x = 9 to obtain $243$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 243.0}, {"id": "U1-10-29", "module": 10, "family": 1, "topic": "Rationalizing limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 81}\\frac{x - 81}{\\sqrt{x} - 9}", "answer": "18", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $18$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 18.0}, {"id": "U1-11-29", "module": 11, "family": 1, "topic": "Limits from numerical tables", "subtopic": "Apply", "difficulty": "Medium", "question": "Does this finite table prove the limit at x = 9 with absolute certainty?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Only finitely many values are shown.", "Unsampled values could behave differently.", "The table provides evidence, not a proof."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["8.900", "28.800"], ["8.990", "28.980"], ["8.999", "28.998"], ["9.001", "29.002"], ["9.010", "29.020"], ["9.100", "29.200"]]}}, {"id": "U1-12-29", "module": 12, "family": 1, "topic": "Making a function continuous", "subtopic": "Apply", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2&x<9\\\\x+K&x\\ge 9\\end{cases}", "answer": "72", "type": "number", "solutionSteps": ["The left limit is 81.", "The right limit and point value are 9 + K.", "Solve 9 + K = 81, giving K = 72."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 72.0}, {"id": "U1-13-29", "module": 13, "family": 1, "topic": "Intermediate Value Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "For f(x) = 1/(x − 9) on [8, 10], does IVT apply across the entire interval?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["The denominator is zero at 9.", "This point lies inside the interval.", "Continuity on the full closed interval fails."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-29", "module": 14, "family": 1, "topic": "Infinite limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 11^+}\\frac{9}{(x-11)^{1}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 9, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-29", "module": 15, "family": 1, "topic": "Asymptotes & multiplicity", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the vertical asymptote at x = 9.", "math": "f(x)=\\frac{11}{(x-9)^{3}}", "answer": "Odd", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 3.", "The asymptote has odd multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-29", "module": 16, "family": 1, "topic": "Rational limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{9 x + 11}{x^{2} + 1}", "answer": "0", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{9}{x}$.", "At the specified end, the limit is $0$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-17-29", "module": 17, "family": 1, "topic": "Radical limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{81 x^{2} + 11}}{x}", "answer": "-9", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $-9$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -9.0}, {"id": "U1-18-29", "module": 18, "family": 1, "topic": "Exponential end behavior", "subtopic": "Apply", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}9 + e^{- x}", "answer": "9", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 9."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-19-29", "module": 19, "family": 1, "topic": "Domain, holes & restrictions", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the hole at x = 9.", "math": "f(x)=\\frac{(x-9)(x+11)}{(x-9)(x+9)}", "answer": "\\frac{10}{9}", "type": "number", "solutionSteps": ["Cancel x − 9.", "Evaluate (x + 11)/(x + 9) at x = 9.", "The hole has height $\\frac{10}{9}$."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.1111111111111112}, {"id": "U1-20-29", "module": 20, "family": 1, "topic": "Intercepts & curve sketching", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the y-intercept.", "math": "f(x)=\\frac{x - 9}{x + 11}", "answer": "- \\frac{9}{11}", "type": "number", "solutionSteps": ["Set x = 0.", "The numerator is −9 and denominator is 11.", "The y-intercept has height $- \\frac{9}{11}$."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -0.8181818181818182}, {"id": "U1-21-29", "module": 21, "family": 1, "topic": "Average rate of change", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the average rate of change on [8, 10].", "math": "f(x)=9 x^{3} - 11 x", "answer": "2185", "type": "number", "solutionSteps": ["The endpoint outputs are 4520 and 8890.", "The input change is 2.", "Divide the output change by 2 to obtain $2185$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 2185.0}, {"id": "U1-22-29", "module": 22, "family": 1, "topic": "Estimating instantaneous rates", "subtopic": "Apply", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 11 using the secant on [10.99, 11.01].", "math": "f(x)=9 x^{2} + 11 x", "answer": "209", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{1099}{100}$ and $\\frac{1101}{100}$.", "The output change is $\\frac{209}{50}$ and the input change is $\\frac{1}{50}$.", "The secant estimate is $209$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 209.0}, {"id": "U1-23-29", "module": 23, "family": 1, "topic": "Squeeze Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}9x^{4}\\sin(1/x)+11", "answer": "11", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 11, both bounds approach 11.", "The Squeeze Theorem gives 11."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 11.0}, {"id": "U1-24-29", "module": 24, "family": 1, "topic": "Combining limits", "subtopic": "Apply", "difficulty": "Medium", "question": "As x approaches 29, f(x) approaches 9 and g(x) approaches 11. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 29}f(x)g(x)", "answer": "99", "type": "number", "solutionSteps": ["Use the component limits 9 and 11.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $99$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 99.0}, {"id": "U1-25-29", "module": 25, "family": 1, "topic": "Limits of compositions", "subtopic": "Apply", "difficulty": "Medium", "question": "Let f(t) = 9 for t < 11, f(t) = 14 for t > 11, and f(11) = 99. If g(x) = 11 − x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "9", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) < 11.", "The inner output approaches the boundary from below.", "The outer left branch is always 9."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-01-30", "module": 1, "family": 1, "topic": "Understanding a limit", "subtopic": "Apply", "difficulty": "Medium", "question": "The left limit is 10 and the right limit is 12. Find the two-sided limit.", "math": "\\lim_{x\\to 13}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left side approaches 10.", "The right side approaches 12.", "The sides differ, so the two-sided limit does not exist."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "10", "12", "13"], "graph": null, "table": null}, {"id": "U1-02-30", "module": 2, "family": 1, "topic": "Reading limits from graphs", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the filled point to find f(7).", "math": "", "answer": "12", "type": "number", "solutionSteps": ["Locate x = 7.", "The closed point has height 12.", "f(7) = 12."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": {"type": "hole", "c": 7, "L": 9, "value": 12, "m": 1}, "table": null, "numericAnswer": 12.0}, {"id": "U1-03-30", "module": 3, "family": 1, "topic": "One-sided limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the indicated one-sided limit.", "math": "\\lim_{x\\to 12^+}\\frac{10|x-12|}{x-12}", "answer": "10", "type": "number", "solutionSteps": ["On this side, x − 12 is positive.", "Replace the absolute value with its argument.", "Cancel the nonzero factor nearby to get 10."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-04-30", "module": 4, "family": 1, "topic": "Direct substitution", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to -10}x^{2} - 10 x + 12", "answer": "212", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = -10.", "Simplify to $212$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 212.0}, {"id": "U1-05-30", "module": 5, "family": 1, "topic": "Rational & trigonometric limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to 0}\\sin{\\left(x \\right)} + 10 \\cos{\\left(x \\right)}", "answer": "10", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $0$ for x.", "Use exact values and simplify to $10$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-06-30", "module": 6, "family": 1, "topic": "Piecewise limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the two-sided limit at x = 10.", "math": "f(x)=\\begin{cases}x^2+2&x<10\\\\13&x=10\\\\x+93&x>10\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 102.", "The right limit is 103.", "The two-sided limit is DNE; the isolated value 13 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": ["DNE", "102", "103", "13"], "graph": null, "table": null}, {"id": "U1-07-30", "module": 7, "family": 1, "topic": "The continuity test", "subtopic": "Apply", "difficulty": "Medium", "question": "At x = 12, the left limit is 10, the right limit is 10, and f(12) is 12. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-30", "module": 8, "family": 1, "topic": "Classifying discontinuities", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the discontinuity at x = 10 for this function.", "math": "\\frac{1}{\\left(x - 10\\right)^{2}}", "answer": "Infinite", "type": "choice", "solutionSteps": ["The squared denominator approaches zero positively.", "The nearby behavior is unbounded.", "This is a infinite discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-30", "module": 9, "family": 1, "topic": "Factoring indeterminate limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 10}\\frac{x^{3} - 1000}{x - 10}", "answer": "300", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 10 for nearby x.", "The reduced expression is $x^{2} + 10 x + 100$.", "Substitute x = 10 to obtain $300$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 300.0}, {"id": "U1-10-30", "module": 10, "family": 1, "topic": "Rationalizing limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 100}\\frac{x - 100}{\\sqrt{x} - 10}", "answer": "20", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $20$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 20.0}, {"id": "U1-11-30", "module": 11, "family": 1, "topic": "Limits from numerical tables", "subtopic": "Apply", "difficulty": "Medium", "question": "Does this finite table prove the limit at x = 10 with absolute certainty?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Only finitely many values are shown.", "Unsampled values could behave differently.", "The table provides evidence, not a proof."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["9.900", "31.800"], ["9.990", "31.980"], ["9.999", "31.998"], ["10.001", "32.002"], ["10.010", "32.020"], ["10.100", "32.200"]]}}, {"id": "U1-12-30", "module": 12, "family": 1, "topic": "Making a function continuous", "subtopic": "Apply", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2&x<10\\\\x+K&x\\ge 10\\end{cases}", "answer": "90", "type": "number", "solutionSteps": ["The left limit is 100.", "The right limit and point value are 10 + K.", "Solve 10 + K = 100, giving K = 90."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 90.0}, {"id": "U1-13-30", "module": 13, "family": 1, "topic": "Intermediate Value Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "For f(x) = 1/(x − 10) on [9, 11], does IVT apply across the entire interval?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["The denominator is zero at 10.", "This point lies inside the interval.", "Continuity on the full closed interval fails."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-30", "module": 14, "family": 1, "topic": "Infinite limits", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 12^+}\\frac{10}{(x-12)^{1}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 10, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-30", "module": 15, "family": 1, "topic": "Asymptotes & multiplicity", "subtopic": "Apply", "difficulty": "Medium", "question": "Classify the vertical asymptote at x = 10.", "math": "f(x)=\\frac{12}{(x-10)^{3}}", "answer": "Odd", "type": "choice", "solutionSteps": ["No denominator factor cancels.", "The remaining factor has power 3.", "The asymptote has odd multiplicity."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-30", "module": 16, "family": 1, "topic": "Rational limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{10 x + 12}{x^{2} + 1}", "answer": "0", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{10}{x}$.", "At the specified end, the limit is $0$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-17-30", "module": 17, "family": 1, "topic": "Radical limits at infinity", "subtopic": "Apply", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{100 x^{2} + 12}}{x}", "answer": "-10", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $-10$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -10.0}, {"id": "U1-18-30", "module": 18, "family": 1, "topic": "Exponential end behavior", "subtopic": "Apply", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}10 + e^{- x}", "answer": "10", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 10."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-19-30", "module": 19, "family": 1, "topic": "Domain, holes & restrictions", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the hole at x = 10.", "math": "f(x)=\\frac{(x-10)(x+12)}{(x-10)(x+10)}", "answer": "\\frac{11}{10}", "type": "number", "solutionSteps": ["Cancel x − 10.", "Evaluate (x + 12)/(x + 10) at x = 10.", "The hole has height $\\frac{11}{10}$."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1.1}, {"id": "U1-20-30", "module": 20, "family": 1, "topic": "Intercepts & curve sketching", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the y-coordinate of the y-intercept.", "math": "f(x)=\\frac{x - 10}{x + 12}", "answer": "- \\frac{5}{6}", "type": "number", "solutionSteps": ["Set x = 0.", "The numerator is −10 and denominator is 12.", "The y-intercept has height $- \\frac{5}{6}$."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -0.8333333333333334}, {"id": "U1-21-30", "module": 21, "family": 1, "topic": "Average rate of change", "subtopic": "Apply", "difficulty": "Medium", "question": "Find the average rate of change on [9, 11].", "math": "f(x)=10 x^{3} - 12 x", "answer": "2998", "type": "number", "solutionSteps": ["The endpoint outputs are 7182 and 13178.", "The input change is 2.", "Divide the output change by 2 to obtain $2998$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 2998.0}, {"id": "U1-22-30", "module": 22, "family": 1, "topic": "Estimating instantaneous rates", "subtopic": "Apply", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 12 using the secant on [11.99, 12.01].", "math": "f(x)=10 x^{2} + 12 x", "answer": "252", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{1199}{100}$ and $\\frac{1201}{100}$.", "The output change is $\\frac{126}{25}$ and the input change is $\\frac{1}{50}$.", "The secant estimate is $252$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 252.0}, {"id": "U1-23-30", "module": 23, "family": 1, "topic": "Squeeze Theorem", "subtopic": "Apply", "difficulty": "Medium", "question": "Use the Squeeze Theorem to evaluate.", "math": "\\lim_{x\\to 0}10x^{4}\\sin(1/x)+12", "answer": "12", "type": "number", "solutionSteps": ["Use −1 ≤ sin(1/x) ≤ 1.", "After multiplying by the nonnegative vanishing factor and adding 12, both bounds approach 12.", "The Squeeze Theorem gives 12."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-24-30", "module": 24, "family": 1, "topic": "Combining limits", "subtopic": "Apply", "difficulty": "Medium", "question": "As x approaches 32, f(x) approaches 10 and g(x) approaches 12. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 32}f(x)g(x)", "answer": "120", "type": "number", "solutionSteps": ["Use the component limits 10 and 12.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $120$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 120.0}, {"id": "U1-25-30", "module": 25, "family": 1, "topic": "Limits of compositions", "subtopic": "Apply", "difficulty": "Medium", "question": "Let f(t) = 10 for t < 12, f(t) = 15 for t > 12, and f(12) = 99. If g(x) = 12 − x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "10", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) < 12.", "The inner output approaches the boundary from below.", "The outer left branch is always 10."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-01-31", "module": 1, "family": 2, "topic": "Understanding a limit", "subtopic": "Connect", "difficulty": "Medium", "question": "Both sides approach 9 at x = 6, and f(6) is undefined. Select all true statements.", "math": "", "answer": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous"], "type": "multi", "solutionSteps": ["Both sides have the same finite limit.", "The undefined point prevents continuity.", "Set the missing value equal to the limit."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous", "The limit must be zero"], "graph": null, "table": null}, {"id": "U1-02-31", "module": 2, "family": 2, "topic": "Reading limits from graphs", "subtopic": "Connect", "difficulty": "Medium", "question": "Classify the discontinuity shown by the graph.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["The approached height is the same on both sides.", "The filled point has a different height.", "Changing that single point removes the discontinuity."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": ["Removable", "Jump", "Infinite", "Continuous"], "graph": {"type": "hole", "c": 3, "L": 5, "value": 8, "m": 1}, "table": null}, {"id": "U1-03-31", "module": 3, "family": 2, "topic": "One-sided limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<6\\\\x+8&x\\ge 6\\end{cases},\\quad\\lim_{x\\to 6^-}f(x)", "answer": "36", "type": "number", "solutionSteps": ["Use x² from the left.", "Substitute x = 6 into that branch.", "The one-sided limit is 36."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 36.0}, {"id": "U1-04-31", "module": 4, "family": 2, "topic": "Direct substitution", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 0}\\sqrt{x + 36}", "answer": "6", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 0.", "Simplify to $6$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-05-31", "module": 5, "family": 2, "topic": "Rational & trigonometric limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to -6}\\frac{x^{2} + 6}{x + 8}", "answer": "21", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $-6$ for x.", "Use exact values and simplify to $21$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 21.0}, {"id": "U1-06-31", "module": 6, "family": 2, "topic": "Piecewise limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the two-sided limit at x = 6.", "math": "f(x)=\\begin{cases}x^2+4&x<6\\\\10&x=6\\\\x+34&x>6\\end{cases}", "answer": "40", "type": "number", "solutionSteps": ["The left limit is 40.", "The right limit is 40.", "The two-sided limit is 40; the isolated value 10 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 40.0}, {"id": "U1-07-31", "module": 7, "family": 2, "topic": "The continuity test", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 8, the left limit is 6, the right limit is 8, and f(8) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides disagree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-31", "module": 8, "family": 2, "topic": "Classifying discontinuities", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 6, the one-sided limits are 8 and 9, but f(6) = 12. Classify the discontinuity.", "math": "", "answer": "Jump", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They differ.", "This is a jump discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-31", "module": 9, "family": 2, "topic": "Factoring indeterminate limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 6}\\frac{x^{2} + 2 x - 48}{x - 6}", "answer": "14", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 6 for nearby x.", "The reduced expression is $x + 8$.", "Substitute x = 6 to obtain $14$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 14.0}, {"id": "U1-10-31", "module": 10, "family": 2, "topic": "Rationalizing limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{x + 36} - 6}{x}", "answer": "\\frac{1}{12}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{12}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.08333333333333333}, {"id": "U1-11-31", "module": 11, "family": 2, "topic": "Limits from numerical tables", "subtopic": "Connect", "difficulty": "Medium", "question": "Treating the displayed trends as representative, estimate the two-sided limit at 6.", "math": "", "answer": "DNE", "type": "choice", "solutionSteps": ["The left trend approaches 6.", "The right trend approaches 8.", "Unequal trends suggest DNE."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["DNE", "6", "8"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["5.900", "5.900"], ["5.990", "5.990"], ["5.999", "5.999"], ["6.001", "8.001"], ["6.010", "8.010"], ["6.100", "8.100"]]}}, {"id": "U1-12-31", "module": 12, "family": 2, "topic": "Making a function continuous", "subtopic": "Connect", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}Kx&x<6\\\\x^2+8&x\\ge 6\\end{cases}", "answer": "\\frac{22}{3}", "type": "number", "solutionSteps": ["The left limit is 6K.", "The right limit is 44.", "Equating them gives K = $\\frac{22}{3}$."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 7.333333333333333}, {"id": "U1-13-31", "module": 13, "family": 2, "topic": "Intermediate Value Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "For f(x) = x² + 8 on [0, 7], find c with f(c) = 44.", "math": "", "answer": "6", "type": "number", "solutionSteps": ["The target lies between 8 and 57.", "Solve c² = 36.", "Only c = 6 lies in this interval."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-14-31", "module": 14, "family": 2, "topic": "Infinite limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 8^-}\\frac{6}{(x-8)^{2}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 6, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-31", "module": 15, "family": 2, "topic": "Asymptotes & multiplicity", "subtopic": "Connect", "difficulty": "Medium", "question": "After reduction, classify the asymptote at x = 6.", "math": "f(x)=\\frac{x-6}{(x-6)^{3}}", "answer": "Even", "type": "choice", "solutionSteps": ["Cancel one factor x − 6.", "The denominator power becomes 2.", "The remaining asymptote is even."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-31", "module": 16, "family": 2, "topic": "Rational limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to -\\infty}\\frac{6 x^{3} + 8}{8 x^{2} + 1}", "answer": "-infinity", "type": "choice", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{3 x}{4}$.", "At the specified end, the limit is $-\\infty$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-17-31", "module": 17, "family": 2, "topic": "Radical limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{36 x^{2} + 8}}{8 x}", "answer": "\\frac{3}{4}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $\\frac{3}{4}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.75}, {"id": "U1-18-31", "module": 18, "family": 2, "topic": "Exponential end behavior", "subtopic": "Connect", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}\\frac{6 x^{2} + 8}{x^{2} + e^{x}}", "answer": "0", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "An exponential in the denominator dominates polynomial growth.", "The remaining expression approaches 0."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-19-31", "module": 19, "family": 2, "topic": "Domain, holes & restrictions", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the x-coordinate of the vertical asymptote.", "math": "f(x)=\\frac{(x-6)(x+8)}{(x-6)(x+6)}", "answer": "-6", "type": "number", "solutionSteps": ["Cancel x − 6.", "The remaining denominator x + 6 vanishes at −6.", "The remaining numerator is nonzero there."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -6.0}, {"id": "U1-20-31", "module": 20, "family": 2, "topic": "Intercepts & curve sketching", "subtopic": "Connect", "difficulty": "Medium", "question": "Does this graph cross or touch the x-axis at x = 6?", "math": "f(x)=\\left(x - 6\\right)^{2} \\left(x + 8\\right)", "answer": "Touches", "type": "choice", "solutionSteps": ["The factor x − 6 has multiplicity 2.", "The other factor is nonzero at this root.", "Even multiplicity preserves sign, so the graph touches."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-31", "module": 21, "family": 2, "topic": "Average rate of change", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the average rate of change on [5, 7] in km/h.", "math": "", "answer": "6", "type": "number", "solutionSteps": ["The endpoint outputs are 38 and 50.", "The input change is 2.", "Divide the output change by 2 to obtain $6$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": {"headers": ["Time (h)", "Distance (km)"], "rows": [["5", "38"], ["7", "50"]]}, "numericAnswer": 6.0}, {"id": "U1-22-31", "module": 22, "family": 2, "topic": "Estimating instantaneous rates", "subtopic": "Connect", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 8 using the secant on [7.5, 8.5].", "math": "f(x)=6 x^{3}", "answer": "\\frac{2307}{2}", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{15}{2}$ and $\\frac{17}{2}$.", "The output change is $\\frac{2307}{2}$ and the input change is $1$.", "The secant estimate is $\\frac{2307}{2}$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1153.5}, {"id": "U1-23-31", "module": 23, "family": 2, "topic": "Squeeze Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "Near x = 6, p(x) ≤ g(x) ≤ q(x), and both bounding limits are 20. Find the limit of g.", "math": "", "answer": "20", "type": "number", "solutionSteps": ["The required nearby inequality is given.", "Both bounds approach 20.", "Therefore g also approaches 20."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 20.0}, {"id": "U1-24-31", "module": 24, "family": 2, "topic": "Combining limits", "subtopic": "Connect", "difficulty": "Medium", "question": "As x approaches 20, f(x) approaches 6 and g(x) approaches 8. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 20}\\frac{f(x)^2}{g(x)}", "answer": "\\frac{9}{2}", "type": "number", "solutionSteps": ["Use the component limits 6 and 8.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $\\frac{9}{2}$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 4.5}, {"id": "U1-25-31", "module": 25, "family": 2, "topic": "Limits of compositions", "subtopic": "Connect", "difficulty": "Medium", "question": "Let f(t) = 6 for t < 8, f(t) = 11 for t > 8, and f(8) = 99. If g(x) = 8 + x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "11", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) > 8.", "The inner output approaches the boundary from above.", "The outer right branch is always 11."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 11.0}, {"id": "U1-01-32", "module": 1, "family": 2, "topic": "Understanding a limit", "subtopic": "Connect", "difficulty": "Medium", "question": "Both sides approach 10 at x = 7, and f(7) is undefined. Select all true statements.", "math": "", "answer": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous"], "type": "multi", "solutionSteps": ["Both sides have the same finite limit.", "The undefined point prevents continuity.", "Set the missing value equal to the limit."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous", "The limit must be zero"], "graph": null, "table": null}, {"id": "U1-02-32", "module": 2, "family": 2, "topic": "Reading limits from graphs", "subtopic": "Connect", "difficulty": "Medium", "question": "Classify the discontinuity shown by the graph.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["The approached height is the same on both sides.", "The filled point has a different height.", "Changing that single point removes the discontinuity."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": ["Removable", "Jump", "Infinite", "Continuous"], "graph": {"type": "hole", "c": 4, "L": 6, "value": 9, "m": 1}, "table": null}, {"id": "U1-03-32", "module": 3, "family": 2, "topic": "One-sided limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<7\\\\x+9&x\\ge 7\\end{cases},\\quad\\lim_{x\\to 7^-}f(x)", "answer": "49", "type": "number", "solutionSteps": ["Use x² from the left.", "Substitute x = 7 into that branch.", "The one-sided limit is 49."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 49.0}, {"id": "U1-04-32", "module": 4, "family": 2, "topic": "Direct substitution", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 0}\\sqrt{x + 49}", "answer": "7", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 0.", "Simplify to $7$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-05-32", "module": 5, "family": 2, "topic": "Rational & trigonometric limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to -7}\\frac{x^{2} + 7}{x + 9}", "answer": "28", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $-7$ for x.", "Use exact values and simplify to $28$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 28.0}, {"id": "U1-06-32", "module": 6, "family": 2, "topic": "Piecewise limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the two-sided limit at x = 7.", "math": "f(x)=\\begin{cases}x^2+4&x<7\\\\11&x=7\\\\x+46&x>7\\end{cases}", "answer": "53", "type": "number", "solutionSteps": ["The left limit is 53.", "The right limit is 53.", "The two-sided limit is 53; the isolated value 11 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 53.0}, {"id": "U1-07-32", "module": 7, "family": 2, "topic": "The continuity test", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 9, the left limit is 7, the right limit is 9, and f(9) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides disagree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-32", "module": 8, "family": 2, "topic": "Classifying discontinuities", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 7, the one-sided limits are 9 and 10, but f(7) = 13. Classify the discontinuity.", "math": "", "answer": "Jump", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They differ.", "This is a jump discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-32", "module": 9, "family": 2, "topic": "Factoring indeterminate limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 7}\\frac{x^{2} + 2 x - 63}{x - 7}", "answer": "16", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 7 for nearby x.", "The reduced expression is $x + 9$.", "Substitute x = 7 to obtain $16$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 16.0}, {"id": "U1-10-32", "module": 10, "family": 2, "topic": "Rationalizing limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{x + 49} - 7}{x}", "answer": "\\frac{1}{14}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{14}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.07142857142857142}, {"id": "U1-11-32", "module": 11, "family": 2, "topic": "Limits from numerical tables", "subtopic": "Connect", "difficulty": "Medium", "question": "Treating the displayed trends as representative, estimate the two-sided limit at 7.", "math": "", "answer": "DNE", "type": "choice", "solutionSteps": ["The left trend approaches 7.", "The right trend approaches 9.", "Unequal trends suggest DNE."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["DNE", "7", "9"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["6.900", "6.900"], ["6.990", "6.990"], ["6.999", "6.999"], ["7.001", "9.001"], ["7.010", "9.010"], ["7.100", "9.100"]]}}, {"id": "U1-12-32", "module": 12, "family": 2, "topic": "Making a function continuous", "subtopic": "Connect", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}Kx&x<7\\\\x^2+9&x\\ge 7\\end{cases}", "answer": "\\frac{58}{7}", "type": "number", "solutionSteps": ["The left limit is 7K.", "The right limit is 58.", "Equating them gives K = $\\frac{58}{7}$."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 8.285714285714286}, {"id": "U1-13-32", "module": 13, "family": 2, "topic": "Intermediate Value Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "For f(x) = x² + 9 on [0, 8], find c with f(c) = 58.", "math": "", "answer": "7", "type": "number", "solutionSteps": ["The target lies between 9 and 73.", "Solve c² = 49.", "Only c = 7 lies in this interval."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-14-32", "module": 14, "family": 2, "topic": "Infinite limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 9^-}\\frac{7}{(x-9)^{2}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 7, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-32", "module": 15, "family": 2, "topic": "Asymptotes & multiplicity", "subtopic": "Connect", "difficulty": "Medium", "question": "After reduction, classify the asymptote at x = 7.", "math": "f(x)=\\frac{x-7}{(x-7)^{3}}", "answer": "Even", "type": "choice", "solutionSteps": ["Cancel one factor x − 7.", "The denominator power becomes 2.", "The remaining asymptote is even."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-32", "module": 16, "family": 2, "topic": "Rational limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to -\\infty}\\frac{7 x^{3} + 9}{9 x^{2} + 1}", "answer": "-infinity", "type": "choice", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{7 x}{9}$.", "At the specified end, the limit is $-\\infty$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-17-32", "module": 17, "family": 2, "topic": "Radical limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{49 x^{2} + 9}}{9 x}", "answer": "\\frac{7}{9}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $\\frac{7}{9}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.7777777777777778}, {"id": "U1-18-32", "module": 18, "family": 2, "topic": "Exponential end behavior", "subtopic": "Connect", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}\\frac{7 x^{2} + 9}{x^{2} + e^{x}}", "answer": "0", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "An exponential in the denominator dominates polynomial growth.", "The remaining expression approaches 0."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-19-32", "module": 19, "family": 2, "topic": "Domain, holes & restrictions", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the x-coordinate of the vertical asymptote.", "math": "f(x)=\\frac{(x-7)(x+9)}{(x-7)(x+7)}", "answer": "-7", "type": "number", "solutionSteps": ["Cancel x − 7.", "The remaining denominator x + 7 vanishes at −7.", "The remaining numerator is nonzero there."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -7.0}, {"id": "U1-20-32", "module": 20, "family": 2, "topic": "Intercepts & curve sketching", "subtopic": "Connect", "difficulty": "Medium", "question": "Does this graph cross or touch the x-axis at x = 7?", "math": "f(x)=\\left(x - 7\\right)^{2} \\left(x + 9\\right)", "answer": "Touches", "type": "choice", "solutionSteps": ["The factor x − 7 has multiplicity 2.", "The other factor is nonzero at this root.", "Even multiplicity preserves sign, so the graph touches."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-32", "module": 21, "family": 2, "topic": "Average rate of change", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the average rate of change on [6, 8] in km/h.", "math": "", "answer": "7", "type": "number", "solutionSteps": ["The endpoint outputs are 51 and 65.", "The input change is 2.", "Divide the output change by 2 to obtain $7$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": {"headers": ["Time (h)", "Distance (km)"], "rows": [["6", "51"], ["8", "65"]]}, "numericAnswer": 7.0}, {"id": "U1-22-32", "module": 22, "family": 2, "topic": "Estimating instantaneous rates", "subtopic": "Connect", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 9 using the secant on [8.5, 9.5].", "math": "f(x)=7 x^{3}", "answer": "\\frac{6811}{4}", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{17}{2}$ and $\\frac{19}{2}$.", "The output change is $\\frac{6811}{4}$ and the input change is $1$.", "The secant estimate is $\\frac{6811}{4}$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 1702.75}, {"id": "U1-23-32", "module": 23, "family": 2, "topic": "Squeeze Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "Near x = 7, p(x) ≤ g(x) ≤ q(x), and both bounding limits are 23. Find the limit of g.", "math": "", "answer": "23", "type": "number", "solutionSteps": ["The required nearby inequality is given.", "Both bounds approach 23.", "Therefore g also approaches 23."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 23.0}, {"id": "U1-24-32", "module": 24, "family": 2, "topic": "Combining limits", "subtopic": "Connect", "difficulty": "Medium", "question": "As x approaches 23, f(x) approaches 7 and g(x) approaches 9. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 23}\\frac{f(x)^2}{g(x)}", "answer": "\\frac{49}{9}", "type": "number", "solutionSteps": ["Use the component limits 7 and 9.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $\\frac{49}{9}$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 5.444444444444445}, {"id": "U1-25-32", "module": 25, "family": 2, "topic": "Limits of compositions", "subtopic": "Connect", "difficulty": "Medium", "question": "Let f(t) = 7 for t < 9, f(t) = 12 for t > 9, and f(9) = 99. If g(x) = 9 + x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "12", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) > 9.", "The inner output approaches the boundary from above.", "The outer right branch is always 12."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-01-33", "module": 1, "family": 2, "topic": "Understanding a limit", "subtopic": "Connect", "difficulty": "Medium", "question": "Both sides approach 11 at x = 8, and f(8) is undefined. Select all true statements.", "math": "", "answer": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous"], "type": "multi", "solutionSteps": ["Both sides have the same finite limit.", "The undefined point prevents continuity.", "Set the missing value equal to the limit."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous", "The limit must be zero"], "graph": null, "table": null}, {"id": "U1-02-33", "module": 2, "family": 2, "topic": "Reading limits from graphs", "subtopic": "Connect", "difficulty": "Medium", "question": "Classify the discontinuity shown by the graph.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["The approached height is the same on both sides.", "The filled point has a different height.", "Changing that single point removes the discontinuity."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": ["Removable", "Jump", "Infinite", "Continuous"], "graph": {"type": "hole", "c": 5, "L": 7, "value": 10, "m": 1}, "table": null}, {"id": "U1-03-33", "module": 3, "family": 2, "topic": "One-sided limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<8\\\\x+10&x\\ge 8\\end{cases},\\quad\\lim_{x\\to 8^-}f(x)", "answer": "64", "type": "number", "solutionSteps": ["Use x² from the left.", "Substitute x = 8 into that branch.", "The one-sided limit is 64."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 64.0}, {"id": "U1-04-33", "module": 4, "family": 2, "topic": "Direct substitution", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 0}\\sqrt{x + 64}", "answer": "8", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 0.", "Simplify to $8$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-05-33", "module": 5, "family": 2, "topic": "Rational & trigonometric limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to -8}\\frac{x^{2} + 8}{x + 10}", "answer": "36", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $-8$ for x.", "Use exact values and simplify to $36$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 36.0}, {"id": "U1-06-33", "module": 6, "family": 2, "topic": "Piecewise limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the two-sided limit at x = 8.", "math": "f(x)=\\begin{cases}x^2+4&x<8\\\\12&x=8\\\\x+60&x>8\\end{cases}", "answer": "68", "type": "number", "solutionSteps": ["The left limit is 68.", "The right limit is 68.", "The two-sided limit is 68; the isolated value 12 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 68.0}, {"id": "U1-07-33", "module": 7, "family": 2, "topic": "The continuity test", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 10, the left limit is 8, the right limit is 10, and f(10) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides disagree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-33", "module": 8, "family": 2, "topic": "Classifying discontinuities", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 8, the one-sided limits are 10 and 11, but f(8) = 14. Classify the discontinuity.", "math": "", "answer": "Jump", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They differ.", "This is a jump discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-33", "module": 9, "family": 2, "topic": "Factoring indeterminate limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 8}\\frac{x^{2} + 2 x - 80}{x - 8}", "answer": "18", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 8 for nearby x.", "The reduced expression is $x + 10$.", "Substitute x = 8 to obtain $18$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 18.0}, {"id": "U1-10-33", "module": 10, "family": 2, "topic": "Rationalizing limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{x + 64} - 8}{x}", "answer": "\\frac{1}{16}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{16}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0625}, {"id": "U1-11-33", "module": 11, "family": 2, "topic": "Limits from numerical tables", "subtopic": "Connect", "difficulty": "Medium", "question": "Treating the displayed trends as representative, estimate the two-sided limit at 8.", "math": "", "answer": "DNE", "type": "choice", "solutionSteps": ["The left trend approaches 8.", "The right trend approaches 10.", "Unequal trends suggest DNE."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["DNE", "8", "10"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["7.900", "7.900"], ["7.990", "7.990"], ["7.999", "7.999"], ["8.001", "10.001"], ["8.010", "10.010"], ["8.100", "10.100"]]}}, {"id": "U1-12-33", "module": 12, "family": 2, "topic": "Making a function continuous", "subtopic": "Connect", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}Kx&x<8\\\\x^2+10&x\\ge 8\\end{cases}", "answer": "\\frac{37}{4}", "type": "number", "solutionSteps": ["The left limit is 8K.", "The right limit is 74.", "Equating them gives K = $\\frac{37}{4}$."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 9.25}, {"id": "U1-13-33", "module": 13, "family": 2, "topic": "Intermediate Value Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "For f(x) = x² + 10 on [0, 9], find c with f(c) = 74.", "math": "", "answer": "8", "type": "number", "solutionSteps": ["The target lies between 10 and 91.", "Solve c² = 64.", "Only c = 8 lies in this interval."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-14-33", "module": 14, "family": 2, "topic": "Infinite limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 10^-}\\frac{8}{(x-10)^{2}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 8, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-33", "module": 15, "family": 2, "topic": "Asymptotes & multiplicity", "subtopic": "Connect", "difficulty": "Medium", "question": "After reduction, classify the asymptote at x = 8.", "math": "f(x)=\\frac{x-8}{(x-8)^{3}}", "answer": "Even", "type": "choice", "solutionSteps": ["Cancel one factor x − 8.", "The denominator power becomes 2.", "The remaining asymptote is even."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-33", "module": 16, "family": 2, "topic": "Rational limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to -\\infty}\\frac{8 x^{3} + 10}{10 x^{2} + 1}", "answer": "-infinity", "type": "choice", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{4 x}{5}$.", "At the specified end, the limit is $-\\infty$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-17-33", "module": 17, "family": 2, "topic": "Radical limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{64 x^{2} + 10}}{10 x}", "answer": "\\frac{4}{5}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $\\frac{4}{5}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.8}, {"id": "U1-18-33", "module": 18, "family": 2, "topic": "Exponential end behavior", "subtopic": "Connect", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}\\frac{8 x^{2} + 10}{x^{2} + e^{x}}", "answer": "0", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "An exponential in the denominator dominates polynomial growth.", "The remaining expression approaches 0."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-19-33", "module": 19, "family": 2, "topic": "Domain, holes & restrictions", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the x-coordinate of the vertical asymptote.", "math": "f(x)=\\frac{(x-8)(x+10)}{(x-8)(x+8)}", "answer": "-8", "type": "number", "solutionSteps": ["Cancel x − 8.", "The remaining denominator x + 8 vanishes at −8.", "The remaining numerator is nonzero there."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -8.0}, {"id": "U1-20-33", "module": 20, "family": 2, "topic": "Intercepts & curve sketching", "subtopic": "Connect", "difficulty": "Medium", "question": "Does this graph cross or touch the x-axis at x = 8?", "math": "f(x)=\\left(x - 8\\right)^{2} \\left(x + 10\\right)", "answer": "Touches", "type": "choice", "solutionSteps": ["The factor x − 8 has multiplicity 2.", "The other factor is nonzero at this root.", "Even multiplicity preserves sign, so the graph touches."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-33", "module": 21, "family": 2, "topic": "Average rate of change", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the average rate of change on [7, 9] in km/h.", "math": "", "answer": "8", "type": "number", "solutionSteps": ["The endpoint outputs are 66 and 82.", "The input change is 2.", "Divide the output change by 2 to obtain $8$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": {"headers": ["Time (h)", "Distance (km)"], "rows": [["7", "66"], ["9", "82"]]}, "numericAnswer": 8.0}, {"id": "U1-22-33", "module": 22, "family": 2, "topic": "Estimating instantaneous rates", "subtopic": "Connect", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 10 using the secant on [9.5, 10.5].", "math": "f(x)=8 x^{3}", "answer": "2402", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{19}{2}$ and $\\frac{21}{2}$.", "The output change is $2402$ and the input change is $1$.", "The secant estimate is $2402$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 2402.0}, {"id": "U1-23-33", "module": 23, "family": 2, "topic": "Squeeze Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "Near x = 8, p(x) ≤ g(x) ≤ q(x), and both bounding limits are 26. Find the limit of g.", "math": "", "answer": "26", "type": "number", "solutionSteps": ["The required nearby inequality is given.", "Both bounds approach 26.", "Therefore g also approaches 26."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 26.0}, {"id": "U1-24-33", "module": 24, "family": 2, "topic": "Combining limits", "subtopic": "Connect", "difficulty": "Medium", "question": "As x approaches 26, f(x) approaches 8 and g(x) approaches 10. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 26}\\frac{f(x)^2}{g(x)}", "answer": "\\frac{32}{5}", "type": "number", "solutionSteps": ["Use the component limits 8 and 10.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $\\frac{32}{5}$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 6.4}, {"id": "U1-25-33", "module": 25, "family": 2, "topic": "Limits of compositions", "subtopic": "Connect", "difficulty": "Medium", "question": "Let f(t) = 8 for t < 10, f(t) = 13 for t > 10, and f(10) = 99. If g(x) = 10 + x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "13", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) > 10.", "The inner output approaches the boundary from above.", "The outer right branch is always 13."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 13.0}, {"id": "U1-01-34", "module": 1, "family": 2, "topic": "Understanding a limit", "subtopic": "Connect", "difficulty": "Medium", "question": "Both sides approach 12 at x = 9, and f(9) is undefined. Select all true statements.", "math": "", "answer": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous"], "type": "multi", "solutionSteps": ["Both sides have the same finite limit.", "The undefined point prevents continuity.", "Set the missing value equal to the limit."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Medium"], "options": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous", "The limit must be zero"], "graph": null, "table": null}, {"id": "U1-02-34", "module": 2, "family": 2, "topic": "Reading limits from graphs", "subtopic": "Connect", "difficulty": "Medium", "question": "Classify the discontinuity shown by the graph.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["The approached height is the same on both sides.", "The filled point has a different height.", "Changing that single point removes the discontinuity."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Medium"], "options": ["Removable", "Jump", "Infinite", "Continuous"], "graph": {"type": "hole", "c": 6, "L": 8, "value": 11, "m": 1}, "table": null}, {"id": "U1-03-34", "module": 3, "family": 2, "topic": "One-sided limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<9\\\\x+11&x\\ge 9\\end{cases},\\quad\\lim_{x\\to 9^-}f(x)", "answer": "81", "type": "number", "solutionSteps": ["Use x² from the left.", "Substitute x = 9 into that branch.", "The one-sided limit is 81."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 81.0}, {"id": "U1-04-34", "module": 4, "family": 2, "topic": "Direct substitution", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 0}\\sqrt{x + 81}", "answer": "9", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 0.", "Simplify to $9$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-05-34", "module": 5, "family": 2, "topic": "Rational & trigonometric limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to -9}\\frac{x^{2} + 9}{x + 11}", "answer": "45", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $-9$ for x.", "Use exact values and simplify to $45$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 45.0}, {"id": "U1-06-34", "module": 6, "family": 2, "topic": "Piecewise limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the two-sided limit at x = 9.", "math": "f(x)=\\begin{cases}x^2+4&x<9\\\\13&x=9\\\\x+76&x>9\\end{cases}", "answer": "85", "type": "number", "solutionSteps": ["The left limit is 85.", "The right limit is 85.", "The two-sided limit is 85; the isolated value 13 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 85.0}, {"id": "U1-07-34", "module": 7, "family": 2, "topic": "The continuity test", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 11, the left limit is 9, the right limit is 11, and f(11) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides disagree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Medium"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-34", "module": 8, "family": 2, "topic": "Classifying discontinuities", "subtopic": "Connect", "difficulty": "Medium", "question": "At x = 9, the one-sided limits are 11 and 12, but f(9) = 15. Classify the discontinuity.", "math": "", "answer": "Jump", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They differ.", "This is a jump discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-34", "module": 9, "family": 2, "topic": "Factoring indeterminate limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 9}\\frac{x^{2} + 2 x - 99}{x - 9}", "answer": "20", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 9 for nearby x.", "The reduced expression is $x + 11$.", "Substitute x = 9 to obtain $20$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 20.0}, {"id": "U1-10-34", "module": 10, "family": 2, "topic": "Rationalizing limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{x + 81} - 9}{x}", "answer": "\\frac{1}{18}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{18}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.05555555555555555}, {"id": "U1-11-34", "module": 11, "family": 2, "topic": "Limits from numerical tables", "subtopic": "Connect", "difficulty": "Medium", "question": "Treating the displayed trends as representative, estimate the two-sided limit at 9.", "math": "", "answer": "DNE", "type": "choice", "solutionSteps": ["The left trend approaches 9.", "The right trend approaches 11.", "Unequal trends suggest DNE."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Medium"], "options": ["DNE", "9", "11"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["8.900", "8.900"], ["8.990", "8.990"], ["8.999", "8.999"], ["9.001", "11.001"], ["9.010", "11.010"], ["9.100", "11.100"]]}}, {"id": "U1-12-34", "module": 12, "family": 2, "topic": "Making a function continuous", "subtopic": "Connect", "difficulty": "Medium", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}Kx&x<9\\\\x^2+11&x\\ge 9\\end{cases}", "answer": "\\frac{92}{9}", "type": "number", "solutionSteps": ["The left limit is 9K.", "The right limit is 92.", "Equating them gives K = $\\frac{92}{9}$."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 10.222222222222221}, {"id": "U1-13-34", "module": 13, "family": 2, "topic": "Intermediate Value Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "For f(x) = x² + 11 on [0, 10], find c with f(c) = 92.", "math": "", "answer": "9", "type": "number", "solutionSteps": ["The target lies between 11 and 111.", "Solve c² = 81.", "Only c = 9 lies in this interval."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-14-34", "module": 14, "family": 2, "topic": "Infinite limits", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 11^-}\\frac{9}{(x-11)^{2}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 9, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-34", "module": 15, "family": 2, "topic": "Asymptotes & multiplicity", "subtopic": "Connect", "difficulty": "Medium", "question": "After reduction, classify the asymptote at x = 9.", "math": "f(x)=\\frac{x-9}{(x-9)^{3}}", "answer": "Even", "type": "choice", "solutionSteps": ["Cancel one factor x − 9.", "The denominator power becomes 2.", "The remaining asymptote is even."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-34", "module": 16, "family": 2, "topic": "Rational limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to -\\infty}\\frac{9 x^{3} + 11}{11 x^{2} + 1}", "answer": "-infinity", "type": "choice", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{9 x}{11}$.", "At the specified end, the limit is $-\\infty$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-17-34", "module": 17, "family": 2, "topic": "Radical limits at infinity", "subtopic": "Connect", "difficulty": "Medium", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{81 x^{2} + 11}}{11 x}", "answer": "\\frac{9}{11}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $\\frac{9}{11}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.8181818181818182}, {"id": "U1-18-34", "module": 18, "family": 2, "topic": "Exponential end behavior", "subtopic": "Connect", "difficulty": "Medium", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}\\frac{9 x^{2} + 11}{x^{2} + e^{x}}", "answer": "0", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "An exponential in the denominator dominates polynomial growth.", "The remaining expression approaches 0."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-19-34", "module": 19, "family": 2, "topic": "Domain, holes & restrictions", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the x-coordinate of the vertical asymptote.", "math": "f(x)=\\frac{(x-9)(x+11)}{(x-9)(x+9)}", "answer": "-9", "type": "number", "solutionSteps": ["Cancel x − 9.", "The remaining denominator x + 9 vanishes at −9.", "The remaining numerator is nonzero there."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": -9.0}, {"id": "U1-20-34", "module": 20, "family": 2, "topic": "Intercepts & curve sketching", "subtopic": "Connect", "difficulty": "Medium", "question": "Does this graph cross or touch the x-axis at x = 9?", "math": "f(x)=\\left(x - 9\\right)^{2} \\left(x + 11\\right)", "answer": "Touches", "type": "choice", "solutionSteps": ["The factor x − 9 has multiplicity 2.", "The other factor is nonzero at this root.", "Even multiplicity preserves sign, so the graph touches."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Medium"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-34", "module": 21, "family": 2, "topic": "Average rate of change", "subtopic": "Connect", "difficulty": "Medium", "question": "Find the average rate of change on [8, 10] in km/h.", "math": "", "answer": "9", "type": "number", "solutionSteps": ["The endpoint outputs are 83 and 101.", "The input change is 2.", "Divide the output change by 2 to obtain $9$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": {"headers": ["Time (h)", "Distance (km)"], "rows": [["8", "83"], ["10", "101"]]}, "numericAnswer": 9.0}, {"id": "U1-22-34", "module": 22, "family": 2, "topic": "Estimating instantaneous rates", "subtopic": "Connect", "difficulty": "Medium", "question": "Estimate the instantaneous rate at x = 11 using the secant on [10.5, 11.5].", "math": "f(x)=9 x^{3}", "answer": "\\frac{13077}{4}", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{21}{2}$ and $\\frac{23}{2}$.", "The output change is $\\frac{13077}{4}$ and the input change is $1$.", "The secant estimate is $\\frac{13077}{4}$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 3269.25}, {"id": "U1-23-34", "module": 23, "family": 2, "topic": "Squeeze Theorem", "subtopic": "Connect", "difficulty": "Medium", "question": "Near x = 9, p(x) ≤ g(x) ≤ q(x), and both bounding limits are 29. Find the limit of g.", "math": "", "answer": "29", "type": "number", "solutionSteps": ["The required nearby inequality is given.", "Both bounds approach 29.", "Therefore g also approaches 29."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 29.0}, {"id": "U1-24-34", "module": 24, "family": 2, "topic": "Combining limits", "subtopic": "Connect", "difficulty": "Medium", "question": "As x approaches 29, f(x) approaches 9 and g(x) approaches 11. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 29}\\frac{f(x)^2}{g(x)}", "answer": "\\frac{81}{11}", "type": "number", "solutionSteps": ["Use the component limits 9 and 11.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $\\frac{81}{11}$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 7.363636363636363}, {"id": "U1-25-34", "module": 25, "family": 2, "topic": "Limits of compositions", "subtopic": "Connect", "difficulty": "Medium", "question": "Let f(t) = 9 for t < 11, f(t) = 14 for t > 11, and f(11) = 99. If g(x) = 11 + x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "14", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) > 11.", "The inner output approaches the boundary from above.", "The outer right branch is always 14."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Medium"], "options": null, "graph": null, "table": null, "numericAnswer": 14.0}, {"id": "U1-01-35", "module": 1, "family": 2, "topic": "Understanding a limit", "subtopic": "Connect", "difficulty": "Hard", "question": "Both sides approach 13 at x = 10, and f(10) is undefined. Select all true statements.", "math": "", "answer": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous"], "type": "multi", "solutionSteps": ["Both sides have the same finite limit.", "The undefined point prevents continuity.", "Set the missing value equal to the limit."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Hard"], "options": ["The limit exists", "The function is discontinuous", "Defining the missing value can make it continuous", "The limit must be zero"], "graph": null, "table": null}, {"id": "U1-02-35", "module": 2, "family": 2, "topic": "Reading limits from graphs", "subtopic": "Connect", "difficulty": "Hard", "question": "Classify the discontinuity shown by the graph.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["The approached height is the same on both sides.", "The filled point has a different height.", "Changing that single point removes the discontinuity."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Hard"], "options": ["Removable", "Jump", "Infinite", "Continuous"], "graph": {"type": "hole", "c": 7, "L": 9, "value": 12, "m": 1}, "table": null}, {"id": "U1-03-35", "module": 3, "family": 2, "topic": "One-sided limits", "subtopic": "Connect", "difficulty": "Hard", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<10\\\\x+12&x\\ge 10\\end{cases},\\quad\\lim_{x\\to 10^-}f(x)", "answer": "100", "type": "number", "solutionSteps": ["Use x² from the left.", "Substitute x = 10 into that branch.", "The one-sided limit is 100."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 100.0}, {"id": "U1-04-35", "module": 4, "family": 2, "topic": "Direct substitution", "subtopic": "Connect", "difficulty": "Hard", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 0}\\sqrt{x + 100}", "answer": "10", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 0.", "Simplify to $10$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-05-35", "module": 5, "family": 2, "topic": "Rational & trigonometric limits", "subtopic": "Connect", "difficulty": "Hard", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to -10}\\frac{x^{2} + 10}{x + 12}", "answer": "55", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $-10$ for x.", "Use exact values and simplify to $55$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 55.0}, {"id": "U1-06-35", "module": 6, "family": 2, "topic": "Piecewise limits", "subtopic": "Connect", "difficulty": "Hard", "question": "Find the two-sided limit at x = 10.", "math": "f(x)=\\begin{cases}x^2+4&x<10\\\\14&x=10\\\\x+94&x>10\\end{cases}", "answer": "104", "type": "number", "solutionSteps": ["The left limit is 104.", "The right limit is 104.", "The two-sided limit is 104; the isolated value 14 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 104.0}, {"id": "U1-07-35", "module": 7, "family": 2, "topic": "The continuity test", "subtopic": "Connect", "difficulty": "Hard", "question": "At x = 12, the left limit is 10, the right limit is 12, and f(12) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides disagree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-35", "module": 8, "family": 2, "topic": "Classifying discontinuities", "subtopic": "Connect", "difficulty": "Hard", "question": "At x = 10, the one-sided limits are 12 and 13, but f(10) = 16. Classify the discontinuity.", "math": "", "answer": "Jump", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They differ.", "This is a jump discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-35", "module": 9, "family": 2, "topic": "Factoring indeterminate limits", "subtopic": "Connect", "difficulty": "Hard", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 10}\\frac{x^{2} + 2 x - 120}{x - 10}", "answer": "22", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 10 for nearby x.", "The reduced expression is $x + 12$.", "Substitute x = 10 to obtain $22$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 22.0}, {"id": "U1-10-35", "module": 10, "family": 2, "topic": "Rationalizing limits", "subtopic": "Connect", "difficulty": "Hard", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{x + 100} - 10}{x}", "answer": "\\frac{1}{20}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{1}{20}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.05}, {"id": "U1-11-35", "module": 11, "family": 2, "topic": "Limits from numerical tables", "subtopic": "Connect", "difficulty": "Hard", "question": "Treating the displayed trends as representative, estimate the two-sided limit at 10.", "math": "", "answer": "DNE", "type": "choice", "solutionSteps": ["The left trend approaches 10.", "The right trend approaches 12.", "Unequal trends suggest DNE."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["DNE", "10", "12"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["9.900", "9.900"], ["9.990", "9.990"], ["9.999", "9.999"], ["10.001", "12.001"], ["10.010", "12.010"], ["10.100", "12.100"]]}}, {"id": "U1-12-35", "module": 12, "family": 2, "topic": "Making a function continuous", "subtopic": "Connect", "difficulty": "Hard", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}Kx&x<10\\\\x^2+12&x\\ge 10\\end{cases}", "answer": "\\frac{56}{5}", "type": "number", "solutionSteps": ["The left limit is 10K.", "The right limit is 112.", "Equating them gives K = $\\frac{56}{5}$."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 11.2}, {"id": "U1-13-35", "module": 13, "family": 2, "topic": "Intermediate Value Theorem", "subtopic": "Connect", "difficulty": "Hard", "question": "For f(x) = x² + 12 on [0, 11], find c with f(c) = 112.", "math": "", "answer": "10", "type": "number", "solutionSteps": ["The target lies between 12 and 133.", "Solve c² = 100.", "Only c = 10 lies in this interval."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-14-35", "module": 14, "family": 2, "topic": "Infinite limits", "subtopic": "Connect", "difficulty": "Hard", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 12^-}\\frac{10}{(x-12)^{2}}", "answer": "infinity", "type": "choice", "solutionSteps": ["The numerator is 10, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-35", "module": 15, "family": 2, "topic": "Asymptotes & multiplicity", "subtopic": "Connect", "difficulty": "Hard", "question": "After reduction, classify the asymptote at x = 10.", "math": "f(x)=\\frac{x-10}{(x-10)^{3}}", "answer": "Even", "type": "choice", "solutionSteps": ["Cancel one factor x − 10.", "The denominator power becomes 2.", "The remaining asymptote is even."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-35", "module": 16, "family": 2, "topic": "Rational limits at infinity", "subtopic": "Connect", "difficulty": "Hard", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to -\\infty}\\frac{10 x^{3} + 12}{12 x^{2} + 1}", "answer": "-infinity", "type": "choice", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{5 x}{6}$.", "At the specified end, the limit is $-\\infty$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-17-35", "module": 17, "family": 2, "topic": "Radical limits at infinity", "subtopic": "Connect", "difficulty": "Hard", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to \\infty}\\frac{\\sqrt{100 x^{2} + 12}}{12 x}", "answer": "\\frac{5}{6}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = 1.", "The limit is $\\frac{5}{6}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.8333333333333334}, {"id": "U1-18-35", "module": 18, "family": 2, "topic": "Exponential end behavior", "subtopic": "Connect", "difficulty": "Hard", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to \\infty}\\frac{10 x^{2} + 12}{x^{2} + e^{x}}", "answer": "0", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "An exponential in the denominator dominates polynomial growth.", "The remaining expression approaches 0."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.0}, {"id": "U1-19-35", "module": 19, "family": 2, "topic": "Domain, holes & restrictions", "subtopic": "Connect", "difficulty": "Hard", "question": "Find the x-coordinate of the vertical asymptote.", "math": "f(x)=\\frac{(x-10)(x+12)}{(x-10)(x+10)}", "answer": "-10", "type": "number", "solutionSteps": ["Cancel x − 10.", "The remaining denominator x + 10 vanishes at −10.", "The remaining numerator is nonzero there."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -10.0}, {"id": "U1-20-35", "module": 20, "family": 2, "topic": "Intercepts & curve sketching", "subtopic": "Connect", "difficulty": "Hard", "question": "Does this graph cross or touch the x-axis at x = 10?", "math": "f(x)=\\left(x - 10\\right)^{2} \\left(x + 12\\right)", "answer": "Touches", "type": "choice", "solutionSteps": ["The factor x − 10 has multiplicity 2.", "The other factor is nonzero at this root.", "Even multiplicity preserves sign, so the graph touches."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Hard"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-35", "module": 21, "family": 2, "topic": "Average rate of change", "subtopic": "Connect", "difficulty": "Hard", "question": "Find the average rate of change on [9, 11] in km/h.", "math": "", "answer": "10", "type": "number", "solutionSteps": ["The endpoint outputs are 102 and 122.", "The input change is 2.", "Divide the output change by 2 to obtain $10$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": {"headers": ["Time (h)", "Distance (km)"], "rows": [["9", "102"], ["11", "122"]]}, "numericAnswer": 10.0}, {"id": "U1-22-35", "module": 22, "family": 2, "topic": "Estimating instantaneous rates", "subtopic": "Connect", "difficulty": "Hard", "question": "Estimate the instantaneous rate at x = 12 using the secant on [11.5, 12.5].", "math": "f(x)=10 x^{3}", "answer": "\\frac{8645}{2}", "type": "number", "solutionSteps": ["Evaluate f at $\\frac{23}{2}$ and $\\frac{25}{2}$.", "The output change is $\\frac{8645}{2}$ and the input change is $1$.", "The secant estimate is $\\frac{8645}{2}$."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 4322.5}, {"id": "U1-23-35", "module": 23, "family": 2, "topic": "Squeeze Theorem", "subtopic": "Connect", "difficulty": "Hard", "question": "Near x = 10, p(x) ≤ g(x) ≤ q(x), and both bounding limits are 32. Find the limit of g.", "math": "", "answer": "32", "type": "number", "solutionSteps": ["The required nearby inequality is given.", "Both bounds approach 32.", "Therefore g also approaches 32."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 32.0}, {"id": "U1-24-35", "module": 24, "family": 2, "topic": "Combining limits", "subtopic": "Connect", "difficulty": "Hard", "question": "As x approaches 32, f(x) approaches 10 and g(x) approaches 12. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 32}\\frac{f(x)^2}{g(x)}", "answer": "\\frac{25}{3}", "type": "number", "solutionSteps": ["Use the component limits 10 and 12.", "Apply the operation to the component limits; the denominator is nonzero when present.", "The resulting value is $\\frac{25}{3}$."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 8.333333333333334}, {"id": "U1-25-35", "module": 25, "family": 2, "topic": "Limits of compositions", "subtopic": "Connect", "difficulty": "Hard", "question": "Let f(t) = 10 for t < 12, f(t) = 15 for t > 12, and f(12) = 99. If g(x) = 12 + x², find the limit of f(g(x)) as x → 0.", "math": "", "answer": "15", "type": "number", "solutionSteps": ["For nearby nonzero x, g(x) > 12.", "The inner output approaches the boundary from above.", "The outer right branch is always 15."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 15.0}, {"id": "U1-01-36", "module": 1, "family": 3, "topic": "Understanding a limit", "subtopic": "Reason", "difficulty": "Hard", "question": "If the limit at x = 6 equals 9, must f(6) equal 9?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["A limit describes punctured-neighborhood behavior.", "The point value may differ or be undefined.", "Therefore the point value is not determined."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-02-36", "module": 2, "family": 3, "topic": "Reading limits from graphs", "subtopic": "Reason", "difficulty": "Hard", "question": "Read the graph and find the two-sided limit.", "math": "\\lim_{x\\to 3}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left branch approaches 6.", "The right branch approaches 8.", "These unequal heights mean the limit does not exist."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "6", "8", "0"], "graph": {"type": "jump", "c": 3, "L": 6, "R": 8}, "table": null}, {"id": "U1-03-36", "module": 3, "family": 3, "topic": "One-sided limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<6\\\\x+8&x\\ge 6\\end{cases},\\quad\\lim_{x\\to 6^+}f(x)", "answer": "14", "type": "number", "solutionSteps": ["Use x + 8 from the right.", "Substitute x = 6 into that branch.", "The one-sided limit is 14."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 14.0}, {"id": "U1-04-36", "module": 4, "family": 3, "topic": "Direct substitution", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 7}8 x + \\left(x - 6\\right)^{3}", "answer": "57", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 7.", "Simplify to $57$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 57.0}, {"id": "U1-05-36", "module": 5, "family": 3, "topic": "Rational & trigonometric limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to \\frac{\\pi}{2}}\\frac{\\cos{\\left(x \\right)} + 6}{\\sin{\\left(x \\right)} + 8}", "answer": "\\frac{2}{3}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $\\frac{\\pi}{2}$ for x.", "Use exact values and simplify to $\\frac{2}{3}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.6666666666666666}, {"id": "U1-06-36", "module": 6, "family": 3, "topic": "Piecewise limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the two-sided limit at x = 6.", "math": "f(x)=\\begin{cases}x^2+6&x<6\\\\11&x=6\\\\x+37&x>6\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 42.", "The right limit is 43.", "The two-sided limit is DNE; the isolated value 11 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "42", "43", "11"], "graph": null, "table": null}, {"id": "U1-07-36", "module": 7, "family": 3, "topic": "The continuity test", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 8, the left limit is 6, the right limit is 6, and f(8) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-36", "module": 8, "family": 3, "topic": "Classifying discontinuities", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 6, the one-sided limits are 8 and 8, but f(6) = 12. Classify the discontinuity.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They agree but differ from the point value.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-36", "module": 9, "family": 3, "topic": "Factoring indeterminate limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 6}\\frac{x^{2} - 36}{x^{2} + 2 x - 48}", "answer": "\\frac{6}{7}", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 6 for nearby x.", "The reduced expression is $\\frac{x + 6}{x + 8}$.", "Substitute x = 6 to obtain $\\frac{6}{7}$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.8571428571428571}, {"id": "U1-10-36", "module": 10, "family": 3, "topic": "Rationalizing limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{7 x + 64} - 8}{x}", "answer": "\\frac{7}{16}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{7}{16}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.4375}, {"id": "U1-11-36", "module": 11, "family": 3, "topic": "Limits from numerical tables", "subtopic": "Reason", "difficulty": "Hard", "question": "The table omits x = 6. What does it tell you about f(6)?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The values shown are all near the point.", "A function value at a missing input can be assigned independently.", "The table does not determine that point value."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Not determined", "20", "0"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["5.900", "19.800"], ["5.990", "19.980"], ["5.999", "19.998"], ["6.001", "20.002"], ["6.010", "20.020"], ["6.100", "20.200"]]}}, {"id": "U1-12-36", "module": 12, "family": 3, "topic": "Making a function continuous", "subtopic": "Reason", "difficulty": "Hard", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2+K&|x|>6\\\\0&|x|\\le 6\\end{cases}", "answer": "-36", "type": "number", "solutionSteps": ["At both boundaries x = ±6, the outer limit is 36 + K.", "The inner branch and boundary values are zero.", "Set K = -36; this joins both boundaries."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -36.0}, {"id": "U1-13-36", "module": 13, "family": 3, "topic": "Intermediate Value Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "For f(x) = x² on [−6, 6], do endpoint values alone satisfy the IVT test for the target 0?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Both endpoint values are 36.", "Zero is not between these equal endpoint values.", "This IVT test does not guarantee the target, although f(0) = 0 actually attains it."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-36", "module": 14, "family": 3, "topic": "Infinite limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 8^+}\\frac{-6}{(x-8)^{2}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is -6, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-36", "module": 15, "family": 3, "topic": "Asymptotes & multiplicity", "subtopic": "Reason", "difficulty": "Hard", "question": "After reduction, classify the asymptote at x = 6.", "math": "f(x)=\\frac{x-6}{(x-6)^{2}}", "answer": "Odd", "type": "choice", "solutionSteps": ["Cancel one factor x − 6.", "The denominator power becomes 1.", "The remaining asymptote is odd."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-36", "module": 16, "family": 3, "topic": "Rational limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{\\left(x + 8\\right) \\left(6 x + 1\\right)}{\\left(x - 6\\right) \\left(8 x + 1\\right)}", "answer": "\\frac{3}{4}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{3}{4}$.", "At the specified end, the limit is $\\frac{3}{4}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.75}, {"id": "U1-17-36", "module": 17, "family": 3, "topic": "Radical limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{36 x^{2} + 8}}{8 x}", "answer": "- \\frac{3}{4}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $- \\frac{3}{4}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -0.75}, {"id": "U1-18-36", "module": 18, "family": 3, "topic": "Exponential end behavior", "subtopic": "Reason", "difficulty": "Hard", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}6 e^{x} + \\frac{8 x^{2} + 1}{x^{2} + 1}", "answer": "8", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 8."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-19-36", "module": 19, "family": 3, "topic": "Domain, holes & restrictions", "subtopic": "Reason", "difficulty": "Hard", "question": "After canceling the common factor, is x = 6 restored to the domain of the ORIGINAL function?", "math": "f(x)=\\frac{(x-6)(x+8)}{(x-6)(x+6)}", "answer": "No", "type": "choice", "solutionSteps": ["The original expression still has a zero denominator there.", "An equivalent reduced rule agrees only on the original domain.", "The original restriction persists."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-20-36", "module": 20, "family": 3, "topic": "Intercepts & curve sketching", "subtopic": "Reason", "difficulty": "Hard", "question": "Does this graph cross or touch the x-axis at x = 6?", "math": "f(x)=\\frac{\\left(x - 6\\right)^{3}}{\\left(x + 8\\right)^{2}}", "answer": "Crosses", "type": "choice", "solutionSteps": ["The denominator is nonzero at the root.", "The numerator root has odd multiplicity 3.", "The sign reverses, so the graph crosses."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Hard"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-36", "module": 21, "family": 3, "topic": "Average rate of change", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the average rate of change on [5, 7].", "math": "f(x)=x^{2} - 6 x", "answer": "6", "type": "number", "solutionSteps": ["The endpoint outputs are -5 and 7.", "The input change is 2.", "Divide the output change by 2 to obtain $6$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 6.0}, {"id": "U1-22-36", "module": 22, "family": 3, "topic": "Estimating instantaneous rates", "subtopic": "Reason", "difficulty": "Hard", "question": "Which interval is more local for estimating the instantaneous rate at x = 6?", "math": "", "answer": "[5.9, 6.1]", "type": "choice", "solutionSteps": ["Use a short interval containing the target input.", "Nearby secant slopes better reflect local behavior.", "Choose [5.9, 6.1]."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["[5.9, 6.1]", "[4, 8]", "[9, 10]"], "graph": null, "table": null}, {"id": "U1-23-36", "module": 23, "family": 3, "topic": "Squeeze Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "Near x = 6, p(x) ≤ g(x) ≤ q(x), but the bounding limits are 6 and 8. What is the limit of g?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The two bounding limits differ.", "The matching-limit hypothesis is missing.", "The limit cannot be determined from this information."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "6", "8", "DNE"], "graph": null, "table": null}, {"id": "U1-24-36", "module": 24, "family": 3, "topic": "Combining limits", "subtopic": "Reason", "difficulty": "Hard", "question": "As x approaches 20, f(x) approaches 6 and g(x) approaches 8. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 20}\\frac{f(x)-6}{g(x)-8}", "answer": "Not determined", "type": "choice", "solutionSteps": ["Use the component limits 6 and 8.", "The quotient gives 0/0, which is indeterminate.", "More information is needed."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "0", "1", "DNE"], "graph": null, "table": null}, {"id": "U1-25-36", "module": 25, "family": 3, "topic": "Limits of compositions", "subtopic": "Reason", "difficulty": "Hard", "question": "The inner limit is 6. The outer function has left limit 8, right limit 11, and point value 99 at 6. Without more information about the inner function, what is the composition limit?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The outer function is discontinuous at the inner limit.", "The inner outputs could approach from either side or hit the boundary.", "Their approach behavior is needed; the limit is not determined."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "8", "11", "99"], "graph": null, "table": null}, {"id": "U1-01-37", "module": 1, "family": 3, "topic": "Understanding a limit", "subtopic": "Reason", "difficulty": "Hard", "question": "If the limit at x = 7 equals 10, must f(7) equal 10?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["A limit describes punctured-neighborhood behavior.", "The point value may differ or be undefined.", "Therefore the point value is not determined."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-02-37", "module": 2, "family": 3, "topic": "Reading limits from graphs", "subtopic": "Reason", "difficulty": "Hard", "question": "Read the graph and find the two-sided limit.", "math": "\\lim_{x\\to 4}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left branch approaches 7.", "The right branch approaches 9.", "These unequal heights mean the limit does not exist."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "7", "9", "0"], "graph": {"type": "jump", "c": 4, "L": 7, "R": 9}, "table": null}, {"id": "U1-03-37", "module": 3, "family": 3, "topic": "One-sided limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<7\\\\x+9&x\\ge 7\\end{cases},\\quad\\lim_{x\\to 7^+}f(x)", "answer": "16", "type": "number", "solutionSteps": ["Use x + 9 from the right.", "Substitute x = 7 into that branch.", "The one-sided limit is 16."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 16.0}, {"id": "U1-04-37", "module": 4, "family": 3, "topic": "Direct substitution", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 8}9 x + \\left(x - 7\\right)^{3}", "answer": "73", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 8.", "Simplify to $73$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 73.0}, {"id": "U1-05-37", "module": 5, "family": 3, "topic": "Rational & trigonometric limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to \\frac{\\pi}{2}}\\frac{\\cos{\\left(x \\right)} + 7}{\\sin{\\left(x \\right)} + 9}", "answer": "\\frac{7}{10}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $\\frac{\\pi}{2}$ for x.", "Use exact values and simplify to $\\frac{7}{10}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.7}, {"id": "U1-06-37", "module": 6, "family": 3, "topic": "Piecewise limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the two-sided limit at x = 7.", "math": "f(x)=\\begin{cases}x^2+6&x<7\\\\12&x=7\\\\x+49&x>7\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 55.", "The right limit is 56.", "The two-sided limit is DNE; the isolated value 12 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "55", "56", "12"], "graph": null, "table": null}, {"id": "U1-07-37", "module": 7, "family": 3, "topic": "The continuity test", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 9, the left limit is 7, the right limit is 7, and f(9) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-37", "module": 8, "family": 3, "topic": "Classifying discontinuities", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 7, the one-sided limits are 9 and 9, but f(7) = 13. Classify the discontinuity.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They agree but differ from the point value.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-37", "module": 9, "family": 3, "topic": "Factoring indeterminate limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 7}\\frac{x^{2} - 49}{x^{2} + 2 x - 63}", "answer": "\\frac{7}{8}", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 7 for nearby x.", "The reduced expression is $\\frac{x + 7}{x + 9}$.", "Substitute x = 7 to obtain $\\frac{7}{8}$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.875}, {"id": "U1-10-37", "module": 10, "family": 3, "topic": "Rationalizing limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{8 x + 81} - 9}{x}", "answer": "\\frac{4}{9}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{4}{9}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.4444444444444444}, {"id": "U1-11-37", "module": 11, "family": 3, "topic": "Limits from numerical tables", "subtopic": "Reason", "difficulty": "Hard", "question": "The table omits x = 7. What does it tell you about f(7)?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The values shown are all near the point.", "A function value at a missing input can be assigned independently.", "The table does not determine that point value."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Not determined", "23", "0"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["6.900", "22.800"], ["6.990", "22.980"], ["6.999", "22.998"], ["7.001", "23.002"], ["7.010", "23.020"], ["7.100", "23.200"]]}}, {"id": "U1-12-37", "module": 12, "family": 3, "topic": "Making a function continuous", "subtopic": "Reason", "difficulty": "Hard", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2+K&|x|>7\\\\0&|x|\\le 7\\end{cases}", "answer": "-49", "type": "number", "solutionSteps": ["At both boundaries x = ±7, the outer limit is 49 + K.", "The inner branch and boundary values are zero.", "Set K = -49; this joins both boundaries."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -49.0}, {"id": "U1-13-37", "module": 13, "family": 3, "topic": "Intermediate Value Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "For f(x) = x² on [−7, 7], do endpoint values alone satisfy the IVT test for the target 0?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Both endpoint values are 49.", "Zero is not between these equal endpoint values.", "This IVT test does not guarantee the target, although f(0) = 0 actually attains it."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-37", "module": 14, "family": 3, "topic": "Infinite limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 9^+}\\frac{-7}{(x-9)^{2}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is -7, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-37", "module": 15, "family": 3, "topic": "Asymptotes & multiplicity", "subtopic": "Reason", "difficulty": "Hard", "question": "After reduction, classify the asymptote at x = 7.", "math": "f(x)=\\frac{x-7}{(x-7)^{2}}", "answer": "Odd", "type": "choice", "solutionSteps": ["Cancel one factor x − 7.", "The denominator power becomes 1.", "The remaining asymptote is odd."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-37", "module": 16, "family": 3, "topic": "Rational limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{\\left(x + 9\\right) \\left(7 x + 1\\right)}{\\left(x - 7\\right) \\left(9 x + 1\\right)}", "answer": "\\frac{7}{9}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{7}{9}$.", "At the specified end, the limit is $\\frac{7}{9}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.7777777777777778}, {"id": "U1-17-37", "module": 17, "family": 3, "topic": "Radical limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{49 x^{2} + 9}}{9 x}", "answer": "- \\frac{7}{9}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $- \\frac{7}{9}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -0.7777777777777778}, {"id": "U1-18-37", "module": 18, "family": 3, "topic": "Exponential end behavior", "subtopic": "Reason", "difficulty": "Hard", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}7 e^{x} + \\frac{9 x^{2} + 1}{x^{2} + 1}", "answer": "9", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 9."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-19-37", "module": 19, "family": 3, "topic": "Domain, holes & restrictions", "subtopic": "Reason", "difficulty": "Hard", "question": "After canceling the common factor, is x = 7 restored to the domain of the ORIGINAL function?", "math": "f(x)=\\frac{(x-7)(x+9)}{(x-7)(x+7)}", "answer": "No", "type": "choice", "solutionSteps": ["The original expression still has a zero denominator there.", "An equivalent reduced rule agrees only on the original domain.", "The original restriction persists."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-20-37", "module": 20, "family": 3, "topic": "Intercepts & curve sketching", "subtopic": "Reason", "difficulty": "Hard", "question": "Does this graph cross or touch the x-axis at x = 7?", "math": "f(x)=\\frac{\\left(x - 7\\right)^{3}}{\\left(x + 9\\right)^{2}}", "answer": "Crosses", "type": "choice", "solutionSteps": ["The denominator is nonzero at the root.", "The numerator root has odd multiplicity 3.", "The sign reverses, so the graph crosses."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Hard"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-37", "module": 21, "family": 3, "topic": "Average rate of change", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the average rate of change on [6, 8].", "math": "f(x)=x^{2} - 7 x", "answer": "7", "type": "number", "solutionSteps": ["The endpoint outputs are -6 and 8.", "The input change is 2.", "Divide the output change by 2 to obtain $7$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 7.0}, {"id": "U1-22-37", "module": 22, "family": 3, "topic": "Estimating instantaneous rates", "subtopic": "Reason", "difficulty": "Hard", "question": "Which interval is more local for estimating the instantaneous rate at x = 7?", "math": "", "answer": "[6.9, 7.1]", "type": "choice", "solutionSteps": ["Use a short interval containing the target input.", "Nearby secant slopes better reflect local behavior.", "Choose [6.9, 7.1]."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["[6.9, 7.1]", "[5, 9]", "[10, 11]"], "graph": null, "table": null}, {"id": "U1-23-37", "module": 23, "family": 3, "topic": "Squeeze Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "Near x = 7, p(x) ≤ g(x) ≤ q(x), but the bounding limits are 7 and 9. What is the limit of g?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The two bounding limits differ.", "The matching-limit hypothesis is missing.", "The limit cannot be determined from this information."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "7", "9", "DNE"], "graph": null, "table": null}, {"id": "U1-24-37", "module": 24, "family": 3, "topic": "Combining limits", "subtopic": "Reason", "difficulty": "Hard", "question": "As x approaches 23, f(x) approaches 7 and g(x) approaches 9. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 23}\\frac{f(x)-7}{g(x)-9}", "answer": "Not determined", "type": "choice", "solutionSteps": ["Use the component limits 7 and 9.", "The quotient gives 0/0, which is indeterminate.", "More information is needed."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "0", "1", "DNE"], "graph": null, "table": null}, {"id": "U1-25-37", "module": 25, "family": 3, "topic": "Limits of compositions", "subtopic": "Reason", "difficulty": "Hard", "question": "The inner limit is 7. The outer function has left limit 9, right limit 12, and point value 99 at 7. Without more information about the inner function, what is the composition limit?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The outer function is discontinuous at the inner limit.", "The inner outputs could approach from either side or hit the boundary.", "Their approach behavior is needed; the limit is not determined."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "9", "12", "99"], "graph": null, "table": null}, {"id": "U1-01-38", "module": 1, "family": 3, "topic": "Understanding a limit", "subtopic": "Reason", "difficulty": "Hard", "question": "If the limit at x = 8 equals 11, must f(8) equal 11?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["A limit describes punctured-neighborhood behavior.", "The point value may differ or be undefined.", "Therefore the point value is not determined."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-02-38", "module": 2, "family": 3, "topic": "Reading limits from graphs", "subtopic": "Reason", "difficulty": "Hard", "question": "Read the graph and find the two-sided limit.", "math": "\\lim_{x\\to 5}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left branch approaches 8.", "The right branch approaches 10.", "These unequal heights mean the limit does not exist."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "8", "10", "0"], "graph": {"type": "jump", "c": 5, "L": 8, "R": 10}, "table": null}, {"id": "U1-03-38", "module": 3, "family": 3, "topic": "One-sided limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<8\\\\x+10&x\\ge 8\\end{cases},\\quad\\lim_{x\\to 8^+}f(x)", "answer": "18", "type": "number", "solutionSteps": ["Use x + 10 from the right.", "Substitute x = 8 into that branch.", "The one-sided limit is 18."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 18.0}, {"id": "U1-04-38", "module": 4, "family": 3, "topic": "Direct substitution", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 9}10 x + \\left(x - 8\\right)^{3}", "answer": "91", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 9.", "Simplify to $91$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 91.0}, {"id": "U1-05-38", "module": 5, "family": 3, "topic": "Rational & trigonometric limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to \\frac{\\pi}{2}}\\frac{\\cos{\\left(x \\right)} + 8}{\\sin{\\left(x \\right)} + 10}", "answer": "\\frac{8}{11}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $\\frac{\\pi}{2}$ for x.", "Use exact values and simplify to $\\frac{8}{11}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.7272727272727273}, {"id": "U1-06-38", "module": 6, "family": 3, "topic": "Piecewise limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the two-sided limit at x = 8.", "math": "f(x)=\\begin{cases}x^2+6&x<8\\\\13&x=8\\\\x+63&x>8\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 70.", "The right limit is 71.", "The two-sided limit is DNE; the isolated value 13 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "70", "71", "13"], "graph": null, "table": null}, {"id": "U1-07-38", "module": 7, "family": 3, "topic": "The continuity test", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 10, the left limit is 8, the right limit is 8, and f(10) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-38", "module": 8, "family": 3, "topic": "Classifying discontinuities", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 8, the one-sided limits are 10 and 10, but f(8) = 14. Classify the discontinuity.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They agree but differ from the point value.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-38", "module": 9, "family": 3, "topic": "Factoring indeterminate limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 8}\\frac{x^{2} - 64}{x^{2} + 2 x - 80}", "answer": "\\frac{8}{9}", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 8 for nearby x.", "The reduced expression is $\\frac{x + 8}{x + 10}$.", "Substitute x = 8 to obtain $\\frac{8}{9}$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.8888888888888888}, {"id": "U1-10-38", "module": 10, "family": 3, "topic": "Rationalizing limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{9 x + 100} - 10}{x}", "answer": "\\frac{9}{20}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{9}{20}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.45}, {"id": "U1-11-38", "module": 11, "family": 3, "topic": "Limits from numerical tables", "subtopic": "Reason", "difficulty": "Hard", "question": "The table omits x = 8. What does it tell you about f(8)?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The values shown are all near the point.", "A function value at a missing input can be assigned independently.", "The table does not determine that point value."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Not determined", "26", "0"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["7.900", "25.800"], ["7.990", "25.980"], ["7.999", "25.998"], ["8.001", "26.002"], ["8.010", "26.020"], ["8.100", "26.200"]]}}, {"id": "U1-12-38", "module": 12, "family": 3, "topic": "Making a function continuous", "subtopic": "Reason", "difficulty": "Hard", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2+K&|x|>8\\\\0&|x|\\le 8\\end{cases}", "answer": "-64", "type": "number", "solutionSteps": ["At both boundaries x = ±8, the outer limit is 64 + K.", "The inner branch and boundary values are zero.", "Set K = -64; this joins both boundaries."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -64.0}, {"id": "U1-13-38", "module": 13, "family": 3, "topic": "Intermediate Value Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "For f(x) = x² on [−8, 8], do endpoint values alone satisfy the IVT test for the target 0?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Both endpoint values are 64.", "Zero is not between these equal endpoint values.", "This IVT test does not guarantee the target, although f(0) = 0 actually attains it."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-38", "module": 14, "family": 3, "topic": "Infinite limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 10^+}\\frac{-8}{(x-10)^{2}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is -8, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-38", "module": 15, "family": 3, "topic": "Asymptotes & multiplicity", "subtopic": "Reason", "difficulty": "Hard", "question": "After reduction, classify the asymptote at x = 8.", "math": "f(x)=\\frac{x-8}{(x-8)^{2}}", "answer": "Odd", "type": "choice", "solutionSteps": ["Cancel one factor x − 8.", "The denominator power becomes 1.", "The remaining asymptote is odd."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-38", "module": 16, "family": 3, "topic": "Rational limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{\\left(x + 10\\right) \\left(8 x + 1\\right)}{\\left(x - 8\\right) \\left(10 x + 1\\right)}", "answer": "\\frac{4}{5}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{4}{5}$.", "At the specified end, the limit is $\\frac{4}{5}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.8}, {"id": "U1-17-38", "module": 17, "family": 3, "topic": "Radical limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{64 x^{2} + 10}}{10 x}", "answer": "- \\frac{4}{5}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $- \\frac{4}{5}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -0.8}, {"id": "U1-18-38", "module": 18, "family": 3, "topic": "Exponential end behavior", "subtopic": "Reason", "difficulty": "Hard", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}8 e^{x} + \\frac{10 x^{2} + 1}{x^{2} + 1}", "answer": "10", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 10."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-19-38", "module": 19, "family": 3, "topic": "Domain, holes & restrictions", "subtopic": "Reason", "difficulty": "Hard", "question": "After canceling the common factor, is x = 8 restored to the domain of the ORIGINAL function?", "math": "f(x)=\\frac{(x-8)(x+10)}{(x-8)(x+8)}", "answer": "No", "type": "choice", "solutionSteps": ["The original expression still has a zero denominator there.", "An equivalent reduced rule agrees only on the original domain.", "The original restriction persists."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-20-38", "module": 20, "family": 3, "topic": "Intercepts & curve sketching", "subtopic": "Reason", "difficulty": "Hard", "question": "Does this graph cross or touch the x-axis at x = 8?", "math": "f(x)=\\frac{\\left(x - 8\\right)^{3}}{\\left(x + 10\\right)^{2}}", "answer": "Crosses", "type": "choice", "solutionSteps": ["The denominator is nonzero at the root.", "The numerator root has odd multiplicity 3.", "The sign reverses, so the graph crosses."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Hard"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-38", "module": 21, "family": 3, "topic": "Average rate of change", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the average rate of change on [7, 9].", "math": "f(x)=x^{2} - 8 x", "answer": "8", "type": "number", "solutionSteps": ["The endpoint outputs are -7 and 9.", "The input change is 2.", "Divide the output change by 2 to obtain $8$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 8.0}, {"id": "U1-22-38", "module": 22, "family": 3, "topic": "Estimating instantaneous rates", "subtopic": "Reason", "difficulty": "Hard", "question": "Which interval is more local for estimating the instantaneous rate at x = 8?", "math": "", "answer": "[7.9, 8.1]", "type": "choice", "solutionSteps": ["Use a short interval containing the target input.", "Nearby secant slopes better reflect local behavior.", "Choose [7.9, 8.1]."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["[7.9, 8.1]", "[6, 10]", "[11, 12]"], "graph": null, "table": null}, {"id": "U1-23-38", "module": 23, "family": 3, "topic": "Squeeze Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "Near x = 8, p(x) ≤ g(x) ≤ q(x), but the bounding limits are 8 and 10. What is the limit of g?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The two bounding limits differ.", "The matching-limit hypothesis is missing.", "The limit cannot be determined from this information."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "8", "10", "DNE"], "graph": null, "table": null}, {"id": "U1-24-38", "module": 24, "family": 3, "topic": "Combining limits", "subtopic": "Reason", "difficulty": "Hard", "question": "As x approaches 26, f(x) approaches 8 and g(x) approaches 10. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 26}\\frac{f(x)-8}{g(x)-10}", "answer": "Not determined", "type": "choice", "solutionSteps": ["Use the component limits 8 and 10.", "The quotient gives 0/0, which is indeterminate.", "More information is needed."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "0", "1", "DNE"], "graph": null, "table": null}, {"id": "U1-25-38", "module": 25, "family": 3, "topic": "Limits of compositions", "subtopic": "Reason", "difficulty": "Hard", "question": "The inner limit is 8. The outer function has left limit 10, right limit 13, and point value 99 at 8. Without more information about the inner function, what is the composition limit?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The outer function is discontinuous at the inner limit.", "The inner outputs could approach from either side or hit the boundary.", "Their approach behavior is needed; the limit is not determined."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "10", "13", "99"], "graph": null, "table": null}, {"id": "U1-01-39", "module": 1, "family": 3, "topic": "Understanding a limit", "subtopic": "Reason", "difficulty": "Hard", "question": "If the limit at x = 9 equals 12, must f(9) equal 12?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["A limit describes punctured-neighborhood behavior.", "The point value may differ or be undefined.", "Therefore the point value is not determined."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-02-39", "module": 2, "family": 3, "topic": "Reading limits from graphs", "subtopic": "Reason", "difficulty": "Hard", "question": "Read the graph and find the two-sided limit.", "math": "\\lim_{x\\to 6}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left branch approaches 9.", "The right branch approaches 11.", "These unequal heights mean the limit does not exist."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "9", "11", "0"], "graph": {"type": "jump", "c": 6, "L": 9, "R": 11}, "table": null}, {"id": "U1-03-39", "module": 3, "family": 3, "topic": "One-sided limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<9\\\\x+11&x\\ge 9\\end{cases},\\quad\\lim_{x\\to 9^+}f(x)", "answer": "20", "type": "number", "solutionSteps": ["Use x + 11 from the right.", "Substitute x = 9 into that branch.", "The one-sided limit is 20."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 20.0}, {"id": "U1-04-39", "module": 4, "family": 3, "topic": "Direct substitution", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 10}11 x + \\left(x - 9\\right)^{3}", "answer": "111", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 10.", "Simplify to $111$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 111.0}, {"id": "U1-05-39", "module": 5, "family": 3, "topic": "Rational & trigonometric limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to \\frac{\\pi}{2}}\\frac{\\cos{\\left(x \\right)} + 9}{\\sin{\\left(x \\right)} + 11}", "answer": "\\frac{3}{4}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $\\frac{\\pi}{2}$ for x.", "Use exact values and simplify to $\\frac{3}{4}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.75}, {"id": "U1-06-39", "module": 6, "family": 3, "topic": "Piecewise limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the two-sided limit at x = 9.", "math": "f(x)=\\begin{cases}x^2+6&x<9\\\\14&x=9\\\\x+79&x>9\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 87.", "The right limit is 88.", "The two-sided limit is DNE; the isolated value 14 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Hard"], "options": ["DNE", "87", "88", "14"], "graph": null, "table": null}, {"id": "U1-07-39", "module": 7, "family": 3, "topic": "The continuity test", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 11, the left limit is 9, the right limit is 9, and f(11) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-39", "module": 8, "family": 3, "topic": "Classifying discontinuities", "subtopic": "Reason", "difficulty": "Hard", "question": "At x = 9, the one-sided limits are 11 and 11, but f(9) = 15. Classify the discontinuity.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They agree but differ from the point value.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-39", "module": 9, "family": 3, "topic": "Factoring indeterminate limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 9}\\frac{x^{2} - 81}{x^{2} + 2 x - 99}", "answer": "\\frac{9}{10}", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 9 for nearby x.", "The reduced expression is $\\frac{x + 9}{x + 11}$.", "Substitute x = 9 to obtain $\\frac{9}{10}$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.9}, {"id": "U1-10-39", "module": 10, "family": 3, "topic": "Rationalizing limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{10 x + 121} - 11}{x}", "answer": "\\frac{5}{11}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{5}{11}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.45454545454545453}, {"id": "U1-11-39", "module": 11, "family": 3, "topic": "Limits from numerical tables", "subtopic": "Reason", "difficulty": "Hard", "question": "The table omits x = 9. What does it tell you about f(9)?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The values shown are all near the point.", "A function value at a missing input can be assigned independently.", "The table does not determine that point value."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Not determined", "29", "0"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["8.900", "28.800"], ["8.990", "28.980"], ["8.999", "28.998"], ["9.001", "29.002"], ["9.010", "29.020"], ["9.100", "29.200"]]}}, {"id": "U1-12-39", "module": 12, "family": 3, "topic": "Making a function continuous", "subtopic": "Reason", "difficulty": "Hard", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2+K&|x|>9\\\\0&|x|\\le 9\\end{cases}", "answer": "-81", "type": "number", "solutionSteps": ["At both boundaries x = ±9, the outer limit is 81 + K.", "The inner branch and boundary values are zero.", "Set K = -81; this joins both boundaries."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -81.0}, {"id": "U1-13-39", "module": 13, "family": 3, "topic": "Intermediate Value Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "For f(x) = x² on [−9, 9], do endpoint values alone satisfy the IVT test for the target 0?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Both endpoint values are 81.", "Zero is not between these equal endpoint values.", "This IVT test does not guarantee the target, although f(0) = 0 actually attains it."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-39", "module": 14, "family": 3, "topic": "Infinite limits", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 11^+}\\frac{-9}{(x-11)^{2}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is -9, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-39", "module": 15, "family": 3, "topic": "Asymptotes & multiplicity", "subtopic": "Reason", "difficulty": "Hard", "question": "After reduction, classify the asymptote at x = 9.", "math": "f(x)=\\frac{x-9}{(x-9)^{2}}", "answer": "Odd", "type": "choice", "solutionSteps": ["Cancel one factor x − 9.", "The denominator power becomes 1.", "The remaining asymptote is odd."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Hard"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-39", "module": 16, "family": 3, "topic": "Rational limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{\\left(x + 11\\right) \\left(9 x + 1\\right)}{\\left(x - 9\\right) \\left(11 x + 1\\right)}", "answer": "\\frac{9}{11}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{9}{11}$.", "At the specified end, the limit is $\\frac{9}{11}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 0.8181818181818182}, {"id": "U1-17-39", "module": 17, "family": 3, "topic": "Radical limits at infinity", "subtopic": "Reason", "difficulty": "Hard", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{81 x^{2} + 11}}{11 x}", "answer": "- \\frac{9}{11}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $- \\frac{9}{11}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": -0.8181818181818182}, {"id": "U1-18-39", "module": 18, "family": 3, "topic": "Exponential end behavior", "subtopic": "Reason", "difficulty": "Hard", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}9 e^{x} + \\frac{11 x^{2} + 1}{x^{2} + 1}", "answer": "11", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 11."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 11.0}, {"id": "U1-19-39", "module": 19, "family": 3, "topic": "Domain, holes & restrictions", "subtopic": "Reason", "difficulty": "Hard", "question": "After canceling the common factor, is x = 9 restored to the domain of the ORIGINAL function?", "math": "f(x)=\\frac{(x-9)(x+11)}{(x-9)(x+9)}", "answer": "No", "type": "choice", "solutionSteps": ["The original expression still has a zero denominator there.", "An equivalent reduced rule agrees only on the original domain.", "The original restriction persists."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Hard"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-20-39", "module": 20, "family": 3, "topic": "Intercepts & curve sketching", "subtopic": "Reason", "difficulty": "Hard", "question": "Does this graph cross or touch the x-axis at x = 9?", "math": "f(x)=\\frac{\\left(x - 9\\right)^{3}}{\\left(x + 11\\right)^{2}}", "answer": "Crosses", "type": "choice", "solutionSteps": ["The denominator is nonzero at the root.", "The numerator root has odd multiplicity 3.", "The sign reverses, so the graph crosses."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Hard"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-39", "module": 21, "family": 3, "topic": "Average rate of change", "subtopic": "Reason", "difficulty": "Hard", "question": "Find the average rate of change on [8, 10].", "math": "f(x)=x^{2} - 9 x", "answer": "9", "type": "number", "solutionSteps": ["The endpoint outputs are -8 and 10.", "The input change is 2.", "Divide the output change by 2 to obtain $9$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Hard"], "options": null, "graph": null, "table": null, "numericAnswer": 9.0}, {"id": "U1-22-39", "module": 22, "family": 3, "topic": "Estimating instantaneous rates", "subtopic": "Reason", "difficulty": "Hard", "question": "Which interval is more local for estimating the instantaneous rate at x = 9?", "math": "", "answer": "[8.9, 9.1]", "type": "choice", "solutionSteps": ["Use a short interval containing the target input.", "Nearby secant slopes better reflect local behavior.", "Choose [8.9, 9.1]."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["[8.9, 9.1]", "[7, 11]", "[12, 13]"], "graph": null, "table": null}, {"id": "U1-23-39", "module": 23, "family": 3, "topic": "Squeeze Theorem", "subtopic": "Reason", "difficulty": "Hard", "question": "Near x = 9, p(x) ≤ g(x) ≤ q(x), but the bounding limits are 9 and 11. What is the limit of g?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The two bounding limits differ.", "The matching-limit hypothesis is missing.", "The limit cannot be determined from this information."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "9", "11", "DNE"], "graph": null, "table": null}, {"id": "U1-24-39", "module": 24, "family": 3, "topic": "Combining limits", "subtopic": "Reason", "difficulty": "Hard", "question": "As x approaches 29, f(x) approaches 9 and g(x) approaches 11. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 29}\\frac{f(x)-9}{g(x)-11}", "answer": "Not determined", "type": "choice", "solutionSteps": ["Use the component limits 9 and 11.", "The quotient gives 0/0, which is indeterminate.", "More information is needed."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "0", "1", "DNE"], "graph": null, "table": null}, {"id": "U1-25-39", "module": 25, "family": 3, "topic": "Limits of compositions", "subtopic": "Reason", "difficulty": "Hard", "question": "The inner limit is 9. The outer function has left limit 11, right limit 14, and point value 99 at 9. Without more information about the inner function, what is the composition limit?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The outer function is discontinuous at the inner limit.", "The inner outputs could approach from either side or hit the boundary.", "Their approach behavior is needed; the limit is not determined."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Hard"], "options": ["Not determined", "11", "14", "99"], "graph": null, "table": null}, {"id": "U1-01-40", "module": 1, "family": 3, "topic": "Understanding a limit", "subtopic": "Reason", "difficulty": "Challenge", "question": "If the limit at x = 10 equals 13, must f(10) equal 13?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["A limit describes punctured-neighborhood behavior.", "The point value may differ or be undefined.", "Therefore the point value is not determined."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Challenge"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-02-40", "module": 2, "family": 3, "topic": "Reading limits from graphs", "subtopic": "Reason", "difficulty": "Challenge", "question": "Read the graph and find the two-sided limit.", "math": "\\lim_{x\\to 7}f(x)", "answer": "DNE", "type": "choice", "solutionSteps": ["The left branch approaches 10.", "The right branch approaches 12.", "These unequal heights mean the limit does not exist."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Challenge"], "options": ["DNE", "10", "12", "0"], "graph": {"type": "jump", "c": 7, "L": 10, "R": 12}, "table": null}, {"id": "U1-03-40", "module": 3, "family": 3, "topic": "One-sided limits", "subtopic": "Reason", "difficulty": "Challenge", "question": "Use the correct branch for this one-sided limit.", "math": "f(x)=\\begin{cases}x^2&x<10\\\\x+12&x\\ge 10\\end{cases},\\quad\\lim_{x\\to 10^+}f(x)", "answer": "22", "type": "number", "solutionSteps": ["Use x + 12 from the right.", "Substitute x = 10 into that branch.", "The one-sided limit is 22."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 22.0}, {"id": "U1-04-40", "module": 4, "family": 3, "topic": "Direct substitution", "subtopic": "Reason", "difficulty": "Challenge", "question": "Evaluate using continuity.", "math": "\\lim_{x\\to 11}12 x + \\left(x - 10\\right)^{3}", "answer": "133", "type": "number", "solutionSteps": ["The expression is continuous at the approached input.", "Substitute x = 11.", "Simplify to $133$."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 133.0}, {"id": "U1-05-40", "module": 5, "family": 3, "topic": "Rational & trigonometric limits", "subtopic": "Reason", "difficulty": "Challenge", "question": "Evaluate this limit. Trigonometric angles are in radians.", "math": "\\lim_{x\\to \\frac{\\pi}{2}}\\frac{\\cos{\\left(x \\right)} + 10}{\\sin{\\left(x \\right)} + 12}", "answer": "\\frac{10}{13}", "type": "number", "solutionSteps": ["Check continuity and any denominator restriction.", "Substitute $\\frac{\\pi}{2}$ for x.", "Use exact values and simplify to $\\frac{10}{13}$."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 0.7692307692307693}, {"id": "U1-06-40", "module": 6, "family": 3, "topic": "Piecewise limits", "subtopic": "Reason", "difficulty": "Challenge", "question": "Find the two-sided limit at x = 10.", "math": "f(x)=\\begin{cases}x^2+6&x<10\\\\15&x=10\\\\x+97&x>10\\end{cases}", "answer": "DNE", "type": "choice", "solutionSteps": ["The left limit is 106.", "The right limit is 107.", "The two-sided limit is DNE; the isolated value 15 does not decide it."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Challenge"], "options": ["DNE", "106", "107", "15"], "graph": null, "table": null}, {"id": "U1-07-40", "module": 7, "family": 3, "topic": "The continuity test", "subtopic": "Reason", "difficulty": "Challenge", "question": "At x = 12, the left limit is 10, the right limit is 10, and f(12) is undefined. Is f continuous there?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Continuity needs a defined value and equal one-sided limits.", "The two sides agree.", "The point value does not satisfy the continuity requirements."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Challenge"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-08-40", "module": 8, "family": 3, "topic": "Classifying discontinuities", "subtopic": "Reason", "difficulty": "Challenge", "question": "At x = 10, the one-sided limits are 12 and 12, but f(10) = 16. Classify the discontinuity.", "math": "", "answer": "Removable", "type": "choice", "solutionSteps": ["Compare the two approached heights.", "They agree but differ from the point value.", "This is a removable discontinuity."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Challenge"], "options": ["Removable", "Infinite", "Jump", "Continuous"], "graph": null, "table": null}, {"id": "U1-09-40", "module": 9, "family": 3, "topic": "Factoring indeterminate limits", "subtopic": "Reason", "difficulty": "Challenge", "question": "Evaluate the limit by factoring.", "math": "\\lim_{x\\to 10}\\frac{x^{2} - 100}{x^{2} + 2 x - 120}", "answer": "\\frac{10}{11}", "type": "number", "solutionSteps": ["Direct substitution gives 0/0, an indeterminate form.", "Factor and cancel the common factor x − 10 for nearby x.", "The reduced expression is $\\frac{x + 10}{x + 12}$.", "Substitute x = 10 to obtain $\\frac{10}{11}$."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 0.9090909090909091}, {"id": "U1-10-40", "module": 10, "family": 3, "topic": "Rationalizing limits", "subtopic": "Reason", "difficulty": "Challenge", "question": "Resolve the indeterminate form using a conjugate.", "math": "\\lim_{x\\to 0}\\frac{\\sqrt{11 x + 144} - 12}{x}", "answer": "\\frac{11}{24}", "type": "number", "solutionSteps": ["Substitution gives 0/0.", "Multiply numerator and denominator by the conjugate of the radical difference.", "Use the difference-of-squares identity and cancel the vanishing factor.", "The remaining expression approaches $\\frac{11}{24}$."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 0.4583333333333333}, {"id": "U1-11-40", "module": 11, "family": 3, "topic": "Limits from numerical tables", "subtopic": "Reason", "difficulty": "Challenge", "question": "The table omits x = 10. What does it tell you about f(10)?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The values shown are all near the point.", "A function value at a missing input can be assigned independently.", "The table does not determine that point value."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Challenge"], "options": ["Not determined", "32", "0"], "graph": null, "table": {"headers": ["x", "f(x)"], "rows": [["9.900", "31.800"], ["9.990", "31.980"], ["9.999", "31.998"], ["10.001", "32.002"], ["10.010", "32.020"], ["10.100", "32.200"]]}}, {"id": "U1-12-40", "module": 12, "family": 3, "topic": "Making a function continuous", "subtopic": "Reason", "difficulty": "Challenge", "question": "Find K so that the function is continuous everywhere.", "math": "f(x)=\\begin{cases}x^2+K&|x|>10\\\\0&|x|\\le 10\\end{cases}", "answer": "-100", "type": "number", "solutionSteps": ["At both boundaries x = ±10, the outer limit is 100 + K.", "The inner branch and boundary values are zero.", "Set K = -100; this joins both boundaries."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": -100.0}, {"id": "U1-13-40", "module": 13, "family": 3, "topic": "Intermediate Value Theorem", "subtopic": "Reason", "difficulty": "Challenge", "question": "For f(x) = x² on [−10, 10], do endpoint values alone satisfy the IVT test for the target 0?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Both endpoint values are 100.", "Zero is not between these equal endpoint values.", "This IVT test does not guarantee the target, although f(0) = 0 actually attains it."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Challenge"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-40", "module": 14, "family": 3, "topic": "Infinite limits", "subtopic": "Reason", "difficulty": "Challenge", "question": "Find the signed infinite limit.", "math": "\\lim_{x\\to 12^+}\\frac{-10}{(x-12)^{2}}", "answer": "-infinity", "type": "choice", "solutionSteps": ["The numerator is -10, which is nonzero.", "The denominator approaches zero positively.", "The quotient grows without bound toward -infinity."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Challenge"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-40", "module": 15, "family": 3, "topic": "Asymptotes & multiplicity", "subtopic": "Reason", "difficulty": "Challenge", "question": "After reduction, classify the asymptote at x = 10.", "math": "f(x)=\\frac{x-10}{(x-10)^{2}}", "answer": "Odd", "type": "choice", "solutionSteps": ["Cancel one factor x − 10.", "The denominator power becomes 1.", "The remaining asymptote is odd."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Challenge"], "options": ["Even", "Odd", "No asymptote"], "graph": null, "table": null}, {"id": "U1-16-40", "module": 16, "family": 3, "topic": "Rational limits at infinity", "subtopic": "Reason", "difficulty": "Challenge", "question": "Find the limit by comparing leading terms.", "math": "\\lim_{x\\to \\infty}\\frac{\\left(x + 12\\right) \\left(10 x + 1\\right)}{\\left(x - 10\\right) \\left(12 x + 1\\right)}", "answer": "\\frac{5}{6}", "type": "number", "solutionSteps": ["Identify the total numerator and denominator degrees.", "The ratio of dominant terms is $\\frac{5}{6}$.", "At the specified end, the limit is $\\frac{5}{6}$."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 0.8333333333333334}, {"id": "U1-17-40", "module": 17, "family": 3, "topic": "Radical limits at infinity", "subtopic": "Reason", "difficulty": "Challenge", "question": "Evaluate, paying attention to the sign of x.", "math": "\\lim_{x\\to -\\infty}\\frac{\\sqrt{100 x^{2} + 12}}{12 x}", "answer": "- \\frac{5}{6}", "type": "number", "solutionSteps": ["Factor x² from the radical.", "Use √(x²) = |x|, not x for all real inputs.", "Here |x|/x = -1.", "The limit is $- \\frac{5}{6}$."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": -0.8333333333333334}, {"id": "U1-18-40", "module": 18, "family": 3, "topic": "Exponential end behavior", "subtopic": "Reason", "difficulty": "Challenge", "question": "Combine exponential and rational end behavior.", "math": "\\lim_{x\\to -\\infty}10 e^{x} + \\frac{12 x^{2} + 1}{x^{2} + 1}", "answer": "12", "type": "number", "solutionSteps": ["Determine whether the exponential term grows or decays.", "The exponential term tends to zero at this end.", "The remaining expression approaches 12."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 12.0}, {"id": "U1-19-40", "module": 19, "family": 3, "topic": "Domain, holes & restrictions", "subtopic": "Reason", "difficulty": "Challenge", "question": "After canceling the common factor, is x = 10 restored to the domain of the ORIGINAL function?", "math": "f(x)=\\frac{(x-10)(x+12)}{(x-10)(x+10)}", "answer": "No", "type": "choice", "solutionSteps": ["The original expression still has a zero denominator there.", "An equivalent reduced rule agrees only on the original domain.", "The original restriction persists."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Challenge"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-20-40", "module": 20, "family": 3, "topic": "Intercepts & curve sketching", "subtopic": "Reason", "difficulty": "Challenge", "question": "Does this graph cross or touch the x-axis at x = 10?", "math": "f(x)=\\frac{\\left(x - 10\\right)^{3}}{\\left(x + 12\\right)^{2}}", "answer": "Crosses", "type": "choice", "solutionSteps": ["The denominator is nonzero at the root.", "The numerator root has odd multiplicity 3.", "The sign reverses, so the graph crosses."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Challenge"], "options": ["Crosses", "Touches", "Neither"], "graph": null, "table": null}, {"id": "U1-21-40", "module": 21, "family": 3, "topic": "Average rate of change", "subtopic": "Reason", "difficulty": "Challenge", "question": "Find the average rate of change on [9, 11].", "math": "f(x)=x^{2} - 10 x", "answer": "10", "type": "number", "solutionSteps": ["The endpoint outputs are -9 and 11.", "The input change is 2.", "Divide the output change by 2 to obtain $10$."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 10.0}, {"id": "U1-22-40", "module": 22, "family": 3, "topic": "Estimating instantaneous rates", "subtopic": "Reason", "difficulty": "Challenge", "question": "Which interval is more local for estimating the instantaneous rate at x = 10?", "math": "", "answer": "[9.9, 10.1]", "type": "choice", "solutionSteps": ["Use a short interval containing the target input.", "Nearby secant slopes better reflect local behavior.", "Choose [9.9, 10.1]."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Challenge"], "options": ["[9.9, 10.1]", "[8, 12]", "[13, 14]"], "graph": null, "table": null}, {"id": "U1-23-40", "module": 23, "family": 3, "topic": "Squeeze Theorem", "subtopic": "Reason", "difficulty": "Challenge", "question": "Near x = 10, p(x) ≤ g(x) ≤ q(x), but the bounding limits are 10 and 12. What is the limit of g?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The two bounding limits differ.", "The matching-limit hypothesis is missing.", "The limit cannot be determined from this information."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Challenge"], "options": ["Not determined", "10", "12", "DNE"], "graph": null, "table": null}, {"id": "U1-24-40", "module": 24, "family": 3, "topic": "Combining limits", "subtopic": "Reason", "difficulty": "Challenge", "question": "As x approaches 32, f(x) approaches 10 and g(x) approaches 12. Find the limit, if these facts determine it.", "math": "\\lim_{x\\to 32}\\frac{f(x)-10}{g(x)-12}", "answer": "Not determined", "type": "choice", "solutionSteps": ["Use the component limits 10 and 12.", "The quotient gives 0/0, which is indeterminate.", "More information is needed."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Challenge"], "options": ["Not determined", "0", "1", "DNE"], "graph": null, "table": null}, {"id": "U1-25-40", "module": 25, "family": 3, "topic": "Limits of compositions", "subtopic": "Reason", "difficulty": "Challenge", "question": "The inner limit is 10. The outer function has left limit 12, right limit 15, and point value 99 at 10. Without more information about the inner function, what is the composition limit?", "math": "", "answer": "Not determined", "type": "choice", "solutionSteps": ["The outer function is discontinuous at the inner limit.", "The inner outputs could approach from either side or hit the boundary.", "Their approach behavior is needed; the limit is not determined."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Challenge"], "options": ["Not determined", "12", "15", "99"], "graph": null, "table": null}, {"id": "U1-01-20", "module": 1, "family": 4, "topic": "Understanding a limit", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "At x = 2, both one-sided limits equal 5, but f(2) is undefined. Which changes preserve the limit and make the function continuous? Select all that apply.", "math": "", "answer": ["Set f(2) = 5 without changing nearby values"], "type": "multi", "solutionSteps": ["The nearby limit is already 5.", "Continuity requires the value at the point to exist and equal 5.", "Changing only the point to 5 preserves the limit and establishes continuity."], "explanation": "Separate what a function approaches from its value at a point. Look for “approaches,” not “equals.” A limit describes nearby outputs.", "hints": ["Look for “approaches,” not “equals.” A limit describes nearby outputs.", "Identify the input being approached.", "Compare the outputs on both sides."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=L"], "commonMistakes": ["A filled point gives f(c), not necessarily the limit."], "tags": ["Understanding a limit", "1.1 · Limits & continuity", "Challenge"], "options": ["Set f(2) = 5 without changing nearby values", "Set f(2) = 0", "Leave f(2) undefined", "Set f(2) = 6"], "graph": null, "table": null}, {"id": "U1-02-20", "module": 2, "family": 4, "topic": "Reading limits from graphs", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Use the graph to evaluate the limit of f(x)² − f(1) as x → 1.", "math": "", "answer": "4", "type": "number", "solutionSteps": ["The graph has limit 3 at x = 1, but the filled point gives f(1) = 5.", "The constant f(1) is 5 throughout the expression.", "The required limit is 3² − 5 = 4."], "explanation": "Read open points, filled points, and nearby behavior. Follow the curve toward the specified input from each side.", "hints": ["Follow the curve toward the specified input from each side.", "Trace the graph from the left.", "Trace it from the right."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=L"], "commonMistakes": ["An open circle can still mark the value of a limit."], "tags": ["Reading limits from graphs", "1.1 · Limits & continuity", "Challenge"], "options": null, "graph": {"type": "hole", "c": 1, "L": 3, "value": 5, "m": 1}, "table": null, "numericAnswer": 4.0}, {"id": "U1-03-20", "module": 3, "family": 4, "topic": "One-sided limits", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Evaluate the left-hand limit. Factor before analyzing the absolute value.", "math": "\\lim_{x\\to2^-}\\frac{x^2-4}{|x-2|}", "answer": "-4", "type": "number", "solutionSteps": ["Factor the numerator as (x − 2)(x + 2).", "For x < 2, |x − 2| = −(x − 2).", "The expression becomes −(x + 2), which tends to −4."], "explanation": "Use direction to distinguish left and right behavior. A minus superscript means inputs below c; a plus means inputs above c.", "hints": ["A minus superscript means inputs below c; a plus means inputs above c.", "Identify the side indicated by the superscript.", "Use only the rule valid on that side."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x),\\quad\\lim_{x\\to c^+}f(x)"], "commonMistakes": ["The minus sign specifies direction, not a negative answer."], "tags": ["One-sided limits", "1.1 · Limits & continuity", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": -4.0}, {"id": "U1-04-20", "module": 4, "family": 4, "topic": "Direct substitution", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Evaluate by identifying the continuous inner and outer expressions.", "math": "\\lim_{x\\to1}\\sqrt{(x^2+3)^2+9}", "answer": "5", "type": "number", "solutionSteps": ["The inner polynomial tends to 1² + 3 = 4.", "Squaring and adding 9 gives 25.", "The square-root function is continuous at 25, so the result is 5."], "explanation": "Evaluate limits of continuous polynomial and radical functions. Polynomials are continuous everywhere; radicals are continuous on their domains.", "hints": ["Polynomials are continuous everywhere; radicals are continuous on their domains.", "Check that the expression is defined nearby.", "Substitute the approached input."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)\\quad\\text{when }f\\text{ is continuous at }c"], "commonMistakes": ["Substitute into every occurrence of the variable."], "tags": ["Direct substitution", "1.1 · Limits & continuity", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 5.0}, {"id": "U1-05-20", "module": 5, "family": 4, "topic": "Rational & trigonometric limits", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Evaluate exactly, checking the denominator first.", "math": "\\lim_{x\\to\\pi/2}\\frac{2\\sin x+\\cos^2x}{3-\\sin x}", "answer": "1", "type": "number", "solutionSteps": ["At π/2, sin x = 1 and cos x = 0.", "The denominator tends to 2, so substitution is valid.", "The numerator tends to 2, giving 2/2 = 1."], "explanation": "Substitute into rational and trigonometric expressions when allowed. A nonzero denominator permits direct substitution. Trig inputs use radians.", "hints": ["A nonzero denominator permits direct substitution. Trig inputs use radians.", "Evaluate the denominator first.", "Check continuity of each part."], "formulasNeeded": ["\\lim_{x\\to c}\\frac{p(x)}{q(x)}=\\frac{p(c)}{q(c)},\\quad q(c)\\ne0"], "commonMistakes": ["Never use the quotient rule for limits if the denominator limit is zero."], "tags": ["Rational & trigonometric limits", "1.1 · Limits & continuity", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-06-20", "module": 6, "family": 4, "topic": "Piecewise limits", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Evaluate the two-sided limit, even though the point value differs.", "math": "f(x)=\\begin{cases}\\frac{x^2-4}{x-2}&x<2\\\\9&x=2\\\\\\sqrt{x+14}&x>2\\end{cases},\\quad\\lim_{x\\to2}f(x)", "answer": "4", "type": "number", "solutionSteps": ["The left branch simplifies to x + 2, with limit 4.", "The right branch approaches √16 = 4.", "The one-sided limits agree; the isolated value 9 does not affect the limit."], "explanation": "Choose the right branch and compare both sides of a boundary. A formula changes at a boundary; the equality sign only controls the point value.", "hints": ["A formula changes at a boundary; the equality sign only controls the point value.", "Identify the branch used immediately left of the boundary.", "Evaluate the right branch separately."], "formulasNeeded": ["\\lim_{x\\to c}f(x)\\text{ exists iff the one-sided limits agree}"], "commonMistakes": ["Using the branch containing the equality sign for both sides can give a false limit."], "tags": ["Piecewise limits", "1.1 · Limits & continuity", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 4.0}, {"id": "U1-07-20", "module": 7, "family": 4, "topic": "The continuity test", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "A function has left limit 4, right limit 4, and value 7 at x = 3. Which statements are true?", "math": "", "answer": ["The limit exists", "The function is discontinuous", "Changing f(3) to 4 fixes continuity"], "type": "multi", "solutionSteps": ["The equal one-sided limits give a two-sided limit of 4.", "The current value 7 differs from the limit.", "Changing that one value to 4 restores continuity."], "explanation": "Check the three requirements for continuity at a point. Ask whether the value exists, the limit exists, and they match.", "hints": ["Ask whether the value exists, the limit exists, and they match.", "Find f(c).", "Determine the two-sided limit."], "formulasNeeded": ["\\lim_{x\\to c}f(x)=f(c)"], "commonMistakes": ["A defined function value alone does not establish continuity."], "tags": ["The continuity test", "1.1 · Limits & continuity", "Challenge"], "options": ["The limit exists", "The function is discontinuous", "Changing f(3) to 4 fixes continuity", "There is a vertical asymptote"], "graph": null, "table": null}, {"id": "U1-08-20", "module": 8, "family": 4, "topic": "Classifying discontinuities", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Reduce first. How many removable discontinuities does this function have?", "math": "f(x)=\\frac{(x-1)(x+2)}{(x-1)(x+2)^2}", "answer": "1", "type": "number", "solutionSteps": ["Cancel one factor x − 1 and one factor x + 2.", "The reduced rule is 1/(x + 2).", "At x = 1 there is a hole; at x = −2 a denominator factor remains, so only one discontinuity is removable."], "explanation": "Tell holes, jumps, and infinite discontinuities apart. A finite shared limit gives a removable hole; unequal sides give a jump.", "hints": ["A finite shared limit gives a removable hole; unequal sides give a jump.", "Compute the one-sided limits.", "If both equal a finite value, check the point value."], "formulasNeeded": ["\\text{Removable: a finite limit exists but continuity fails}"], "commonMistakes": ["A vertical asymptote is not removable by changing one point."], "tags": ["Classifying discontinuities", "1.2 · Algebraic limits & IVT", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-09-20", "module": 9, "family": 4, "topic": "Factoring indeterminate limits", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Factor both parts and evaluate the limit.", "math": "\\lim_{x\\to2}\\frac{x^3-8}{x^2-4}", "answer": "3", "type": "number", "solutionSteps": ["Direct substitution gives 0/0.", "Factor as (x − 2)(x² + 2x + 4) over (x − 2)(x + 2).", "Cancel x − 2 for nearby inputs.", "At x = 2 the result is 12/4 = 3."], "explanation": "Resolve zero over zero by factoring and cancellation. Direct substitution gives 0/0, suggesting a common factor.", "hints": ["Direct substitution gives 0/0, suggesting a common factor.", "Try substitution and identify 0/0.", "Factor numerator and denominator."], "formulasNeeded": ["x^2-a^2=(x-a)(x+a)"], "commonMistakes": ["Cancel factors, not terms. The original point remains excluded."], "tags": ["Factoring indeterminate limits", "1.2 · Algebraic limits & IVT", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-10-20", "module": 10, "family": 4, "topic": "Rationalizing limits", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Both numerator and denominator have radical differences. Evaluate.", "math": "\\lim_{x\\to0}\\frac{\\sqrt{1+3x}-1}{\\sqrt{1+2x}-1}", "answer": "\\frac{3}{2}", "type": "number", "solutionSteps": ["Rationalize each radical difference.", "For x ≠ 0, the ratio becomes 3(√(1 + 2x) + 1) / [2(√(1 + 3x) + 1)].", "Substitution gives 3·2/(2·2) = 3/2."], "explanation": "Use a conjugate to simplify radical differences. A difference of radicals over a vanishing denominator often gives 0/0.", "hints": ["A difference of radicals over a vanishing denominator often gives 0/0.", "Confirm the indeterminate form.", "Multiply numerator and denominator by the conjugate."], "formulasNeeded": ["(\\sqrt{u}-\\sqrt{v})(\\sqrt{u}+\\sqrt{v})=u-v"], "commonMistakes": ["Multiply both numerator and denominator by the conjugate."], "tags": ["Rationalizing limits", "1.2 · Algebraic limits & IVT", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 1.5}, {"id": "U1-11-20", "module": 11, "family": 4, "topic": "Limits from numerical tables", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "A finite table suggests a limit of 6 at x = 1. A new rule agrees at every sampled input, but has spikes of height 10 at other inputs accumulating at 1. Does agreement with the table prove the limit is 6?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["Finite samples leave other inputs unchecked.", "Spikes accumulating at the approached input can violate the proposed limit.", "The table alone does not prove the limit."], "explanation": "Use nearby values as evidence for a limit. Read the closest inputs on each side, without treating a finite table as proof.", "hints": ["Read the closest inputs on each side, without treating a finite table as proof.", "Sort inputs by the side they approach from.", "Compare the trend of nearby outputs."], "formulasNeeded": ["x\\to c^-\\quad\\text{and}\\quad x\\to c^+"], "commonMistakes": ["A finite table suggests behavior but cannot prove every nearby value follows it."], "tags": ["Limits from numerical tables", "1.2 · Algebraic limits & IVT", "Challenge"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-12-20", "module": 12, "family": 4, "topic": "Making a function continuous", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Find A + B so this three-part function is continuous.", "math": "f(x)=\\begin{cases}x^2&x<1\\\\Ax+B&1\\le x\\le3\\\\x+3&x>3\\end{cases}", "answer": "1", "type": "number", "solutionSteps": ["At x = 1, continuity requires A + B = 1.", "At x = 3, continuity requires 3A + B = 6.", "Solving gives A = 5/2 and B = −3/2, so A + B = 1."], "explanation": "Find missing values and parameters that join the pieces. The unknown parameter must make both limits and the point value agree.", "hints": ["The unknown parameter must make both limits and the point value agree.", "Evaluate the boundary expression on both sides.", "Set their values equal."], "formulasNeeded": ["\\lim_{x\\to c^-}f(x)=\\lim_{x\\to c^+}f(x)=f(c)"], "commonMistakes": ["Matching one side is insufficient if the other side differs."], "tags": ["Making a function continuous", "1.2 · Algebraic limits & IVT", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 1.0}, {"id": "U1-13-20", "module": 13, "family": 4, "topic": "Intermediate Value Theorem", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "For f(x) = (x² − 1)/(x − 1) on [0, 2], does the IVT apply to the ORIGINAL function on the full interval?", "math": "", "answer": "No", "type": "choice", "solutionSteps": ["The original rule is undefined at x = 1.", "Cancellation gives x + 1 only when x ≠ 1.", "The original function is not continuous on the whole interval, so IVT does not apply."], "explanation": "Check when a continuous function must reach a target output. You need continuity on the whole closed interval and a target between endpoint values.", "hints": ["You need continuity on the whole closed interval and a target between endpoint values.", "Verify continuity on [a,b].", "Compute both endpoint values and compare with the target."], "formulasNeeded": ["f(a)<k<f(b)\\ \\Longrightarrow\\ \\exists c\\in(a,b):f(c)=k"], "commonMistakes": ["IVT guarantees existence, not uniqueness. Failure of its test does not prove no solution exists."], "tags": ["Intermediate Value Theorem", "1.2 · Algebraic limits & IVT", "Challenge"], "options": ["Yes", "No"], "graph": null, "table": null}, {"id": "U1-14-20", "module": 14, "family": 4, "topic": "Infinite limits", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Cancel what you can, then determine the signed limit.", "math": "\\lim_{x\\to2^-}\\frac{x^2-4}{(x-2)^2}", "answer": "-infinity", "type": "choice", "solutionSteps": ["Factor x² − 4 = (x − 2)(x + 2).", "Cancel one factor to get (x + 2)/(x − 2).", "From the left, the numerator approaches 4 and the denominator approaches zero negatively, giving −∞."], "explanation": "Analyze sign near a zero denominator. A nonzero numerator over a denominator approaching zero requires a sign check.", "hints": ["A nonzero numerator over a denominator approaching zero requires a sign check.", "Check whether cancellation is possible.", "Determine numerator and denominator signs on each side."], "formulasNeeded": ["\\frac{\\text{positive}}{0^+}\\to+\\infty,\\quad\\frac{\\text{positive}}{0^-}\\to-\\infty"], "commonMistakes": ["Infinity describes unbounded behavior, not a real function value."], "tags": ["Infinite limits", "1.3 · Infinite limits & end behavior", "Challenge"], "options": ["infinity", "-infinity", "0", "DNE"], "graph": null, "table": null}, {"id": "U1-15-20", "module": 15, "family": 4, "topic": "Asymptotes & multiplicity", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "After full reduction, which asymptote descriptions are correct?", "math": "f(x)=\\frac{(x-2)^2}{(x-2)^3(x+1)^2}", "answer": ["x = 2 has odd multiplicity", "x = −1 has even multiplicity"], "type": "multi", "solutionSteps": ["Cancel the two numerator factors.", "The reduced denominator is (x − 2)(x + 1)².", "The remaining powers are 1 at x = 2 and 2 at x = −1."], "explanation": "Use remaining factor powers to predict vertical asymptote behavior. Reduce first; odd and even denominator powers behave differently across a root.", "hints": ["Reduce first; odd and even denominator powers behave differently across a root.", "Reduce common factors.", "Locate remaining real denominator zeros."], "formulasNeeded": ["f(x)=\\frac{A}{(x-c)^n}"], "commonMistakes": ["Classify multiplicity after cancellation, not before."], "tags": ["Asymptotes & multiplicity", "1.3 · Infinite limits & end behavior", "Challenge"], "options": ["x = 2 has odd multiplicity", "x = −1 has even multiplicity", "x = 2 is a hole", "x = −1 has odd multiplicity"], "graph": null, "table": null}, {"id": "U1-16-20", "module": 16, "family": 4, "topic": "Rational limits at infinity", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Use total degrees of the products to evaluate.", "math": "\\lim_{x\\to-\\infty}\\frac{(2x+1)^2(x-3)}{(x+4)(3x-1)^2}", "answer": "\\frac{4}{9}", "type": "number", "solutionSteps": ["Both numerator and denominator have total degree 3.", "Their leading terms are 4x³ and 9x³.", "Equal degrees give the coefficient ratio 4/9, including at negative infinity."], "explanation": "Compare degrees and leading coefficients to read end behavior. The input approaches infinity, so leading terms dominate.", "hints": ["The input approaches infinity, so leading terms dominate.", "Determine total degrees, expanding leading terms when needed.", "Lower numerator degree gives 0; equal degree gives a/b."], "formulasNeeded": ["\\frac{a x^m}{b x^n}\\sim\\frac ab x^{m-n}"], "commonMistakes": ["The largest individual factor is not the total degree of a product."], "tags": ["Rational limits at infinity", "1.3 · Infinite limits & end behavior", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 0.4444444444444444}, {"id": "U1-17-20", "module": 17, "family": 4, "topic": "Radical limits at infinity", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Account for the sign hidden inside the radical.", "math": "\\lim_{x\\to-\\infty}\\frac{\\sqrt{9x^2+1}+2x}{x}", "answer": "-1", "type": "number", "solutionSteps": ["Split the expression into √(9x² + 1)/x + 2.", "The radical ratio is (|x|/x)√(9 + 1/x²).", "At negative infinity this is −3, so the full limit is −3 + 2 = −1."], "explanation": "Keep track of absolute values when extracting powers from radicals. At negative infinity, the sign hidden in a square root matters.", "hints": ["At negative infinity, the sign hidden in a square root matters.", "Factor x² from under the radical.", "Replace √(x²) with |x|."], "formulasNeeded": ["\\sqrt{x^2}=|x|"], "commonMistakes": ["Writing √(x²) = x for negative x reverses the answer."], "tags": ["Radical limits at infinity", "1.3 · Infinite limits & end behavior", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": -1.0}, {"id": "U1-18-20", "module": 18, "family": 4, "topic": "Exponential end behavior", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Combine a decaying exponential with a rational limit.", "math": "\\lim_{x\\to-\\infty}\\frac{3x^2+e^x}{2x^2+1}", "answer": "\\frac{3}{2}", "type": "number", "solutionSteps": ["As x → −∞, eˣ → 0.", "Divide numerator and denominator by x².", "The extra terms vanish, leaving 3/2."], "explanation": "Combine exponential behavior with polynomial and rational terms. Watch the sign of the exponent and whether x goes left or right.", "hints": ["Watch the sign of the exponent and whether x goes left or right.", "Determine the exponent’s direction.", "Use exponential growth or decay."], "formulasNeeded": ["e^x\\to0\\ (x\\to-\\infty),\\quad e^x\\to\\infty\\ (x\\to\\infty)"], "commonMistakes": ["eˣ approaches zero at negative infinity, not at positive infinity."], "tags": ["Exponential end behavior", "1.3 · Infinite limits & end behavior", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 1.5}, {"id": "U1-19-20", "module": 19, "family": 4, "topic": "Domain, holes & restrictions", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Find the sum of the y-coordinate of the hole and the x-coordinate of the vertical asymptote.", "math": "f(x)=\\frac{(x-2)(x+3)}{(x-2)(x+1)}", "answer": "\\frac{2}{3}", "type": "number", "solutionSteps": ["The original restrictions are x ≠ 2 and x ≠ −1.", "The reduced rule is (x + 3)/(x + 1), so the hole is (2, 5/3).", "The vertical asymptote is x = −1.", "The requested sum is 5/3 − 1 = 2/3."], "explanation": "Preserve original restrictions while finding removable holes. Original denominator zeros stay excluded after cancellation.", "hints": ["Original denominator zeros stay excluded after cancellation.", "Record original denominator zeros.", "Factor and reduce."], "formulasNeeded": ["\\text{Hole at }(c,f_{\\mathrm{reduced}}(c))"], "commonMistakes": ["Canceling a factor does not put its excluded input back in the domain."], "tags": ["Domain, holes & restrictions", "1.4 · Curve sketching", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 0.6666666666666666}, {"id": "U1-20-20", "module": 20, "family": 4, "topic": "Intercepts & curve sketching", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Select every true feature of this graph.", "math": "f(x)=\\frac{(x-2)(x+1)^2}{(x-2)(x-3)}", "answer": ["Hole at (2, −9)", "Vertical asymptote x = 3", "Touches the x-axis at x = −1"], "type": "multi", "solutionSteps": ["Cancel x − 2 while preserving x ≠ 2.", "The reduced value at 2 is 9/(−1) = −9, giving the hole.", "The denominator still vanishes at 3.", "The numerator has a double root at −1, so the graph touches there."], "explanation": "Assemble intercepts, asymptotes, and end behavior into a graph. A useful sketch begins with structural features, not random plotting.", "hints": ["A useful sketch begins with structural features, not random plotting.", "Give the domain and reduce.", "Find asymptotes, holes, and valid intercepts."], "formulasNeeded": ["x\\text{-intercept: }f(x)=0;\\quad y\\text{-intercept: }f(0)"], "commonMistakes": ["A canceled numerator zero is not an x-intercept if the input is excluded."], "tags": ["Intercepts & curve sketching", "1.4 · Curve sketching", "Challenge"], "options": ["Hole at (2, −9)", "Vertical asymptote x = 3", "Touches the x-axis at x = −1", "x-intercept at (2, 0)"], "graph": null, "table": null}, {"id": "U1-21-20", "module": 21, "family": 4, "topic": "Average rate of change", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "A trip covers 90 km in its first 2 hours and another 60 km in the next hour. Find the average speed for the entire trip, in km/h.", "math": "", "answer": "50", "type": "number", "solutionSteps": ["The total distance change is 90 + 60 = 150 km.", "The total elapsed time is 2 + 1 = 3 hours.", "The average speed is 150/3 = 50 km/h, not the unweighted mean of 45 and 60."], "explanation": "Find a secant slope from formulas, points, and motion tables. Two inputs or times signal an average rate over an interval.", "hints": ["Two inputs or times signal an average rate over an interval.", "Evaluate the output at both endpoints.", "Subtract outputs in the same order as inputs."], "formulasNeeded": ["\\mathrm{AROC}=\\frac{f(b)-f(a)}{b-a}"], "commonMistakes": ["Average speed is distance change divided by time change, not the average of the two distances."], "tags": ["Average rate of change", "1.5 · Rates, squeeze & composition", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 50.0}, {"id": "U1-22-20", "module": 22, "family": 4, "topic": "Estimating instantaneous rates", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "For f(x) = x³, use the secant on [1.5, 2.5] to estimate the instantaneous rate at x = 2.", "math": "", "answer": "\\frac{49}{4}", "type": "number", "solutionSteps": ["f(2.5) = 15.625 and f(1.5) = 3.375.", "The output change is 12.25 and the input change is 1.", "The secant estimate is 12.25 = 49/4; it is an estimate of the instantaneous rate."], "explanation": "Use nearby secant slopes to estimate a rate at one instant. A single instant calls for a local estimate, not a long-interval average.", "hints": ["A single instant calls for a local estimate, not a long-interval average.", "Choose nearby points that bracket the instant.", "Compute their secant slope."], "formulasNeeded": ["f\\text{ near }c:\\quad\\frac{f(c+h)-f(c-h)}{2h}"], "commonMistakes": ["This unit estimates curved-graph instantaneous rates; derivative rules belong to a later unit."], "tags": ["Estimating instantaneous rates", "1.5 · Rates, squeeze & composition", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 12.25}, {"id": "U1-23-20", "module": 23, "family": 4, "topic": "Squeeze Theorem", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Evaluate by constructing matching bounds.", "math": "\\lim_{x\\to2}\\left[3+(x-2)^2\\cos\\left(\\frac1{x-2}\\right)\\right]", "answer": "3", "type": "number", "solutionSteps": ["The cosine factor stays between −1 and 1.", "The expression lies between 3 − (x − 2)² and 3 + (x − 2)².", "Both bounds tend to 3, so the Squeeze Theorem gives 3."], "explanation": "Find a limit by trapping a function between matching bounds. A bounded oscillation multiplied by a vanishing factor is a common clue.", "hints": ["A bounded oscillation multiplied by a vanishing factor is a common clue.", "Verify the bounding inequality near the point.", "Find both bounding limits."], "formulasNeeded": ["f(x)\\le g(x)\\le h(x),\\quad\\lim f=\\lim h=L\\Rightarrow\\lim g=L"], "commonMistakes": ["Different bounding limits do not determine the middle limit."], "tags": ["Squeeze Theorem", "1.5 · Rates, squeeze & composition", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 3.0}, {"id": "U1-24-20", "module": 24, "family": 4, "topic": "Combining limits", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Suppose f(x) → 2 and g(x) → −1 as x → 3. Evaluate the combined limit.", "math": "\\lim_{x\\to3}\\frac{f(x)^2-3g(x)}{2f(x)+g(x)}", "answer": "\\frac{7}{3}", "type": "number", "solutionSteps": ["The numerator limit is 2² − 3(−1) = 7.", "The denominator limit is 2·2 − 1 = 3, which is nonzero.", "The quotient law gives 7/3."], "explanation": "Use limit laws with sums, products, and quotients. Known limits can be combined when the relevant operations are defined.", "hints": ["Known limits can be combined when the relevant operations are defined.", "Record each component limit.", "Apply sum, product, or quotient rules."], "formulasNeeded": ["\\lim(af+bg)=a\\lim f+b\\lim g"], "commonMistakes": ["Do not insert a function value when the problem supplies a different limit."], "tags": ["Combining limits", "1.5 · Rates, squeeze & composition", "Challenge"], "options": null, "graph": null, "table": null, "numericAnswer": 2.3333333333333335}, {"id": "U1-25-20", "module": 25, "family": 4, "topic": "Limits of compositions", "subtopic": "Synthesize", "difficulty": "Challenge", "question": "Let f(t) = 1 for t < 2, f(t) = 5 for t > 2, and f(2) = 99. If g(x) = 2 + x³, find the limit of f(g(x)) as x → 0.", "math": "", "answer": "DNE", "type": "choice", "solutionSteps": ["For x < 0, g(x) < 2, so f(g(x)) = 1.", "For x > 0, g(x) > 2, so f(g(x)) = 5.", "The two composition limits differ, so the limit does not exist."], "explanation": "Follow inner outputs into the correct side of an outer function. If the outer function is discontinuous, track which side the inner outputs approach.", "hints": ["If the outer function is discontinuous, track which side the inner outputs approach.", "Find the limiting inner output.", "Determine its approach side if the outer function jumps."], "formulasNeeded": ["\\lim f(g(x))=f(L)\\quad\\text{if }g(x)\\to L\\text{ and }f\\text{ is continuous at }L"], "commonMistakes": ["At an outer discontinuity, knowing only the inner limit can be insufficient."], "tags": ["Limits of compositions", "1.5 · Rates, squeeze & composition", "Challenge"], "options": ["DNE", "1", "5", "99"], "graph": null, "table": null}]};